  ui_story_5020_50200101_15_dialog_content = "Se enseñó a sí misma a asumir las responsabilidades de su amo.",
  ui_story_5020_50200101_16_dialog_content = "Hasta que un día encontró la oportunidad de rescatar a su amo.",
  ui_story_5020_50200101_17_dialog_content = "Se adentró en el territorio de su enemigo y, por fin, encontró al mentor que había anhelado durante diez años en Sealed Ground.",
