  ui_story_5020_50200101_54_dialog_content = "¿¿¿Qué???",
  ui_story_5020_50200101_55_dialog_content = "¿Dónde está el amor y el odio en nuestra historia?",
  ui_story_5020_50200101_56_dialog_content = "no hay ninguno!!",
  ui_story_5020_50200101_57_dialog_content = "Bueno, miré a través de la rendija de la puerta hace un momento...",
  ui_story_5020_50200101_58_dialog_content = "Está muerto de silencio ahí fuera.",
