  ui_story_5020_50200101_65_dialog_content = "<color=#e8d9bb>Gong...!</color>",
  ui_story_5020_50200101_66_dialog_content = "<color=#e8d9bb>¡Gong, gong...!</color>",
  ui_story_5020_50200101_67_dialog_content = "Con los taiko thuds llega el momento...",
  ui_story_5020_50200101_68_dialog_content = "¡Vamos! ¡Vamos!",
