  ui_story_5020_50200101_70_dialog_content = "<size=45>¡Cargaaaargo! ¡Hagamos algo de dinero!</size>",
  ui_story_5020_50200101_71_dialog_content = "Seguro que parece animado por ahí.",
  ui_story_5020_50200101_72_dialog_content = "Correcto... Podríamos usar las multitudes para cubrir nuestra huida.",
  ui_story_5020_50200101_73_dialog_content = "El general no permitirá que sus hombres lleven a cabo una cacería humana mientras la gente está fuera, para que no cause pánico.",
  ui_story_5020_50200101_74_dialog_content = "También es hora de reunirse con Yao.",
  ui_story_5020_50200101_75_dialog_content = "Está tardando demasiado... Me preocupa que se haya metido en problemas.",
  ui_story_5020_50200101_76_dialog_content = "Bueno, ya que esto es Yao estamos hablando, no puedo dejar de pensar que podría haberse perdido en el camino aquí...",
  ui_story_5020_50200101_77_dialog_content = "Hmm... Eso sería muy característico de Yao, en efecto.",
  ui_story_5020_50200101_78_dialog_content = "En cualquier caso, aún deberíamos idear un plan para encontrarla.",
  ui_story_5020_50200101_79_dialog_content = "Ven, empezaremos por buscar en las calles.",
  ui_story_5020_50200101_80_dialog_content = "¡¡Woo-hoo!!",
  ui_story_5020_50200101_81_dialog_content = "¡Papá! ¡Papá! ¡¡Mira allá!!",
  ui_story_5020_50200101_82_dialog_content = "¡Oye, más despacio! ¡No podré encontrarte con esa máscara puesta!",
  ui_story_5020_50200101_83_dialog_content = "¿Tu lo crees?",
  ui_story_5020_50200101_84_dialog_content = "¡Entonces deberíamos jugar al escondite!",
  ui_story_5020_50200101_85_dialog_content = "¡Entendido! No más fugas, ¿entiendes?",
  ui_story_5020_50200101_86_dialog_content = "Jajajaja! ¡Basta, papá! ¡Te prometo que no me escaparé de nuevo!",
  ui_story_5020_50200101_87_dialog_content = "¿Por qué todos usan máscaras? Sin embargo, son un poco lindos. Se parecen a...",
  ui_story_5020_50200101_88_dialog_content = "gatos",
  ui_story_5020_50200101_89_dialog_content = "Los gatos son criaturas nocturnas y son vistos como mensajeros entre el mundo de los vivos y el de los muertos.",
  ui_story_5020_50200101_90_dialog_content = "¿Es porque la gente de aquí quiere restablecer algún tipo de conexión con el difunto?",
  ui_story_5020_50200101_91_dialog_content = "En cierto modo, sí. Es una tradición que nace del deseo de volver a ver a los difuntos.",
  ui_story_5020_50200101_92_dialog_content = "Los queridos difuntos, eh...",
  ui_story_5020_50200101_93_dialog_content = "¿PlayerName?",
  ui_story_5020_50200101_94_dialog_content = "¿Qué?",
  ui_story_5020_50200101_95_dialog_content = "¡Esta máscara es tan linda! ¿Por qué no conseguimos uno para nosotros también?",
  ui_story_5020_50200101_96_dialog_content = "Ahora no es el momento para eso, Vice. Necesitamos que...",
  ui_story_5020_50200101_97_dialog_content = "Vice tiene un punto Las máscaras podrían ayudar a disimular nuestros rostros.",
  ui_story_5020_50200101_98_dialog_content = "Sigamos a la multitud por ahora.",
  ui_story_5020_50200101_99_dialog_content = "Compraremos alguna si nos encontramos con algún puesto de mascarillas.",
  ui_story_5020_50200101_100_dialog_content = "Está bien.",
  ui_story_5020_50200101_101_dialog_content = "¿Eh? Aférrate, PlayerName...",
  ui_story_5020_50200101_102_dialog_content = "¿Qué pasa, Vice?",
  ui_story_5020_50200101_103_dialog_content = "¿Por qué hay un frijol en tu cabello...?",
  ui_story_5020_50200101_104_dialog_content = "¿Una judía? Sentí que algo ligero golpeó mi cabeza justo ahora...",
  ui_story_5020_50200101_105_dialog_content = "¿De dónde vino este frijol?",
  ui_story_5020_50200101_106_dialog_content = "¡Ánimo, que venga la felicidad!",
  ui_story_5020_50200101_107_dialog_content = "¿¡Eh!?",
  ui_story_5020_50200101_108_dialog_content = "¡¿P-Por qué me tiran frijoles?!",
  ui_story_5020_50200101_109_dialog_content = "Los frijoles son para alejar a los fantasmas malignos que puedan haberse infiltrado en la celebración. Es otra tradición nuestra.",
  ui_story_5020_50200101_110_dialog_content = "Sin embargo, ¿realmente parezco un fantasma...?",
  ui_story_5020_50200101_111_dialog_content = "Solo están tratando de protegerte del mal... Es algo bueno, lo prometo.",
  ui_story_5020_50200101_112_dialog_content = "Oh, ya veo.",
  ui_story_5020_50200101_113_dialog_content = "¡Oh, lo siento por eso! Los niños pueden salirse un poco de control a veces.",
  ui_story_5020_50200101_114_dialog_content = "¡Está bien! Todo es parte de las festividades, ¿verdad?",
  ui_story_5020_50200101_115_dialog_content = "¡Así es! Lo están haciendo para protegernos, así que no hay daño.",
  ui_story_5020_50200101_116_dialog_content = "¡Toma, puedes tener esta bolsa de frijoles! ¡Ahora también puedes proteger a los demás!",
  ui_story_5020_50200101_117_dialog_content = "¡Dilo conmigo! ¡Ánimo, que venga la felicidad!",
  ui_story_5020_50200101_118_dialog_content = "... ¡Ánimo, que venga la felicidad!",
  ui_story_5020_50200101_119_dialog_content = "Aprendes rápido, PlayerName.",
  ui_story_5020_50200101_120_dialog_content = "...",
  ui_story_5020_50200101_121_dialog_content = "Oye, mira para allá.",
  ui_story_5020_50200101_122_dialog_content = "Esa persona en la máscara...",
  ui_story_5020_50200101_123_dialog_content = "amemori?",
  ui_story_5020_50200101_124_dialog_content = "Qué vas a...",
  ui_story_5020_50200101_125_dialog_content = "Shhh—",
