  ui_story_5020_50200101_127_dialog_content = "¿Ah?",
  ui_story_5020_50200101_128_dialog_content = "Escóndete o vete a algún lugar lejano, ¿entendido?",
  ui_story_5020_50200101_129_dialog_content = "Koufu-jou...",
  ui_story_5020_50200101_130_dialog_content = "Está a punto de renacer entre las llamas del sufrimiento.",
  ui_story_5020_50200101_131_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5020_50200101_132_dialog_content = "Que planeas hacer, Amemori?",
