  ui_story_5020_50200101_134_dialog_content = "La dama ninja es tan sucinta como siempre.",
  ui_story_5020_50200101_135_dialog_content = "Sin embargo...",
  ui_story_5020_50200101_136_dialog_content = "¿Era realmente necesario que ella hiciera todo este camino solo para entregar un mensaje tan escaso...?",
  ui_story_5020_50200101_137_dialog_content = "¡Papá, mira para allá! ¡Sus máscaras se ven geniales!",
  ui_story_5020_50200101_138_dialog_content = "Eso es...",
  ui_story_5020_50200101_139_dialog_content = "<anim type=Shake><size=45>Graaah!!</size></anim>",
  ui_story_5020_50200101_140_dialog_content = "¡Es un fantasma! ¡Los fantasmas están aquí!",
  ui_story_5020_50200101_141_dialog_content = "¡Fantasmas! ¡Fantasmas en la ciudad!",
  ui_story_5020_50200101_142_dialog_content = "¡Corre!",
  ui_story_5020_50200101_143_dialog_content = "¡¡Ayúdanos!!",
  ui_story_5020_50200101_144_dialog_content = "¡¿?!",
  ui_story_5020_50200101_145_dialog_content = "PlayerName! ¡Viene el enemigo! ¡Prepárate para la batalla!",
  ui_story_5020_50200202_1_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_5020_50200202_2_dialog_content = "¡Ah! ¡A-Aléjate de mí!",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5020_50200202_4_dialog_content = "¿Estás herida?",
  ui_story_5020_50200202_5_dialog_content = "N-No... *Sniff* Estoy bien. Gracias.",
  ui_story_5020_50200202_6_dialog_content = "<anim type=Shake>Gra, gra...</anim>",
  ui_story_5020_50200202_7_dialog_content = "Mierda... No hay final para ellos...",
  ui_story_5020_50200202_8_dialog_content = "¿Qué vamos a hacer?",
  ui_story_5020_50200202_9_dialog_content = "Corre hacia allí lo más rápido que puedas y no mires atrás.",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>Uaaagh...</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName? ¿Qué estás haciendo?",
  ui_story_5020_50200202_12_dialog_content = "Has estado murmurando extrañamente para ti mismo por un tiempo.",
  ui_story_5020_50200202_13_dialog_content = "He estado tirando frijoles a los fantasmas... Bolsas y bolsas de ellos.",
  ui_story_5020_50200202_14_dialog_content = "Todo el tiempo, he estado gritando:",
  ui_story_5020_50200202_15_option_content = "¡Ánimo, que venga la felicidad!",
  ui_story_5020_50200202_16_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5020_50200202_17_option_content = "¡Ánimo, que venga la felicidad!",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5020_50200202_19_option_content = "Thpirith vete!! May feliz venga!!",
  ui_story_5020_50200202_20_dialog_content = "Ay... Grité tanto que me mordí la lengua.",
  ui_story_5020_50200202_21_dialog_content = "¿Está funcionando?",
  ui_story_5020_50200202_22_dialog_content = "Bueno, como puedes ver... probablemente vamos a necesitar las habilidades de combate de todos para manejar las cosas aquí.",
  ui_story_5020_50200202_23_dialog_content = "<size=45>¡Aaaahhhh!</size>",
  ui_story_5020_50200202_24_dialog_content = "¡Atrás, todos! ¡No te acerques más...!",
  ui_story_5020_50200202_25_dialog_content = "¡Torrente rápido!",
  ui_story_5020_50200202_26_dialog_content = "¿Cómo llegaron a Sakai? ¿Dónde están los guardias de la ciudad del general?",
  ui_story_5020_50200202_27_dialog_content = "No pueden estar todos custodiando las puertas de la ciudad, ¿verdad?",
  ui_story_5020_50200202_28_dialog_content = "De ninguna manera... Nuestro escape no debería merecer tanta atención.",
  ui_story_5020_50200202_29_dialog_content = "Este lugar no es seguro. Tenemos que encontrar una manera de ayudar a la gente del pueblo a evacuar.",
  ui_story_5020_50200202_30_dialog_content = "PlayerName, saca a la gente de aquí primero.",
  ui_story_5020_50200202_31_dialog_content = "¡Así, todos! ¡Sígueme!",
  ui_story_5020_50200202_32_dialog_content = "Oye... ¿No es esa la sacerdotisa?",
  ui_story_5020_50200202_33_dialog_content = "Además de un montón de extraños también.",
  ui_story_5020_50200202_34_dialog_content = "¿Deberíamos ir con ellos?",
  ui_story_5020_50200202_35_dialog_content = "Parece que no confían en nosotros... ¿Qué debemos hacer?",
  ui_story_5020_50200202_36_dialog_content = "¡¿Por qué estás dudando?! ¡Esta es una situación de vida o muerte!",
  ui_story_5020_50200202_37_dialog_content = "<size=45>¡¿Qué hacen todos estos fantasmas aquí?!</size>",
  ui_story_5020_50200202_38_dialog_content = "¡Oye! PlayerName! ¿Por qué no habéis escapado tú y los demás todavía?",
  ui_story_5020_50200202_39_dialog_content = "¡Están volteando todos los puestos! ¡Retirada! ¡Retirada!",
  ui_story_5020_50200202_40_dialog_content = "¡Esperar! ¡Vuelvan aquí, ustedes dos!",
  ui_story_5020_50200202_41_dialog_content = "Momo! Anzu! ¡Realmente nos vendría bien tu ayuda ahora mismo!",
  ui_story_5020_50200202_42_dialog_content = "¡Estoy seguro de que podemos hablar más tarde, ¿verdad?!",
  ui_story_5020_50200202_43_dialog_content = "¡Así es! Ahora mismo, lo más importante es correr!!",
  ui_story_5020_50200202_44_dialog_content = "¡Eso es suficiente! ¡Cálmense los dos!",
  ui_story_5020_50200202_45_dialog_content = "Ustedes quieren mantener el negocio en auge, ¿verdad?",
  ui_story_5020_50200202_46_dialog_content = "<size=45>¡Sí!</size>",
  ui_story_5020_50200202_47_dialog_content = "Quieren ser los mejores dueños de restaurantes en toda Cloud Island, ¿verdad?",
  ui_story_5020_50200202_48_dialog_content = "<size=45>¡Sí!</size>",
  ui_story_5020_50200202_49_dialog_content = "Pues bien, usa tu habitual... ejem... fervor para llevar a todas estas personas a un lugar seguro.",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>¡Por aquí, todos! ¡¡¡Ven, rápido!!!</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "Ay, mis oídos...",
  ui_story_5020_50200301_1_dialog_content = "Kubou-sama, hay varios mercaderes esperando fuera del castillo principal. Buscan a tu audiencia.",
  ui_story_5020_50200301_2_dialog_content = "Ahora, de todos los tiempos? ¿No deberían estar vendiendo sus mercancías en las calles esta noche?",
  ui_story_5020_50200301_3_dialog_content = "Muy bien, déjalos entrar.",
  ui_story_5020_50200301_4_dialog_content = "Kubou-sama! ¡Debes salvarnos!",
  ui_story_5020_50200301_5_dialog_content = "Olvídate de las formalidades y cuéntame qué ha pasado.",
  ui_story_5020_50200301_6_dialog_content = "¡Mi señor, aún no debe haberlo oído! ¡Sakai está bajo el ataque de los fantasmas!",
  ui_story_5020_50200301_7_dialog_content = "¡Así es! ¡Así es!",
  ui_story_5020_50200301_8_dialog_content = "¡Nuestros puestos están hechos pedazos! Todos perdimos mucho dinero esta noche...",
  ui_story_5020_50200301_9_dialog_content = "El Festival Kasuga no será el mismo este año...",
  ui_story_5020_50200301_10_dialog_content = "*Se aclara la garganta* ¿Es este realmente el momento para sus pequeñas quejas, ustedes? ¡Cálmense todos!",
  ui_story_5020_50200301_11_dialog_content = "Perdónanos, Kubou-sama, pero vinimos a decírtelo tan pronto como pudimos.",
  ui_story_5020_50200301_12_dialog_content = "¿Es verdad?",
  ui_story_5020_50200301_13_dialog_content = "Perdóname, Kubou-sama, pero los guardianes están actualmente—",
  ui_story_5020_50200301_14_dialog_content = "¡Envíalos a Sakai, ahora!",
  ui_story_5020_50200301_15_dialog_content = "¡Y si hay más percances, consideren sus vidas perdidas!",
  ui_story_5020_50200301_16_dialog_content = "¡Sí!",
  ui_story_5020_50200301_17_dialog_content = "¡Estamos eternamente agradecidos, mi señor!",
  ui_story_5020_50200301_18_dialog_content = "Las fallas de mis subordinados son mi responsabilidad. En todo caso, debería disculparme con todos ustedes.",
  ui_story_5020_50200301_19_dialog_content = "¡Para nada!",
  ui_story_5020_50200301_20_dialog_content = "De hecho, recuerdo claramente haber visto Rinne-sama en la ciudad, evacuando a la gente a un lugar seguro.",
  ui_story_5020_50200301_21_dialog_content = "¿Oh? Rinne esta en la ciudad?",
  ui_story_5020_50200301_22_dialog_content = "¡Sí! Rinne-sama debe haberse estado preparando para las Fiestas Nocturnas, para que ella haya respondido al ataque tan rápido.",
  ui_story_5020_50200301_23_dialog_content = "¡Su heroica presencia nos conmovió a todos!",
  ui_story_5020_50200301_24_dialog_content = "Tanto es así que sentimos que debíamos ayudar.",
  ui_story_5020_50200301_25_dialog_content = "Ocupada como estaba defendiéndonos a todos, supusimos que no tenía forma de darte la noticia. Por eso, decidimos venir y decíroslo nosotros mismos. ¡Por favor, perdónanos, Kubou-sama!",
  ui_story_5020_50200301_26_dialog_content = "No hay nada que perdonar. Tenían razón al hacerlo, todos ustedes.",
  ui_story_5020_50200301_27_dialog_content = "Creo que las fuerzas rebeldes tienen la culpa de llevar a los fantasmas a la ciudad. Deben tratar de utilizar el caos para promover sus planes, incluso a expensas de la seguridad de la gente.",
  ui_story_5020_50200301_28_dialog_content = "Pero no temas. Los guardianes están en camino y tu seguridad está casi garantizada.",
  ui_story_5020_50200301_29_dialog_content = "¡La Isla de las Nubes tiene la suerte de tenerte, Kubou-sama!",
  ui_story_5020_50200301_30_dialog_content = "Nos despediremos ahora.",
  ui_story_5020_50200301_31_dialog_content = "La gente de Cloud Island no entiende el significado de la paz... todo lo que saben es hacer demandas sin cesar.",
  ui_story_5020_50200301_32_dialog_content = "Para realizar sus deseos, se deben hacer ciertos sacrificios.",
  ui_story_5020_50200301_33_dialog_content = "Más sorprendente, sin embargo, es que el <color=#FFB400>Jirón</color> todavía tienen que hacer un movimiento.",
  ui_story_5020_50200301_34_dialog_content = "¿Se ha encontrado a Nagi?",
  ui_story_5020_50200301_35_dialog_content = "Aún no.",
  ui_story_5020_50200301_36_dialog_content = "<size=45>¡Necios inútiles!</size>",
  ui_story_5020_50200301_37_dialog_content = "Mis disculpas, Kubou-sama.",
  ui_story_5020_50200301_38_dialog_content = "Lleva el ejército fantasma a Sakai. Eso debería sacarlos.",
  ui_story_5020_50200301_39_dialog_content = "Debemos poner fin a esto hoy, de una vez por todas.",
  ui_story_5020_50200301_40_dialog_content = "El Festival Kasuga debe continuar sin incidentes.",
  ui_story_5020_50200301_41_dialog_content = "Entendido.",
  ui_story_5020_50200301_42_dialog_content = "A veces, Rinne se parece tanto a ti.",
  ui_story_5020_50200301_43_dialog_content = "Si tan solo estuvieras aquí... Estoy seguro de que le tendrías mucho cariño.",
  ui_story_5020_50200301_44_dialog_content = "Desde el día que te fuiste, he puesto todas mis esperanzas en criar a una nueva sacerdotisa.",
  ui_story_5020_50200301_45_dialog_content = "Pero no importa cómo lo vea, todos mis esfuerzos sin duda han sido en vano.",
  ui_story_5020_50200301_46_dialog_content = "Tú eres el especial, después de todo.",
  ui_story_5020_50200301_47_dialog_content = "Pero ten por seguro que cumpliré la promesa que te hice.",
  ui_story_5020_50200301_48_dialog_content = "Este es tu deseo... Y el mío también.",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>Graah!</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "¡Hay demasiados de ellos!",
  ui_story_5020_50200301_51_dialog_content = "¿El General Fujikumo realmente tiene la intención de simplemente esperar y ver morir a la gente?",
  ui_story_5020_50200301_52_dialog_content = "¡Torrente rápido...!",
  ui_story_5020_50200301_53_dialog_content = "Estos fantasmas son cada vez más fuertes...",
  ui_story_5020_50200301_54_dialog_content = "Tengo que concentrarme... Nuestra máxima prioridad es sacar a los civiles de aquí.",
  ui_story_5020_50200301_55_dialog_content = "Rinne... Vice... ¡Solo espera un poco más!",
  ui_story_5020_50200302_1_dialog_content = "Espero que Momo y Anzu estén mejor por su parte...",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName!</size>",
  ui_story_5020_50200302_3_dialog_content = "¿Alguien dijo mi nombre hace un momento?",
  ui_story_5020_50200302_4_dialog_content = "¿Eh? No escuché nada.",
  ui_story_5020_50200302_5_dialog_content = "¡¡PlayerName!!",
  ui_story_5020_50200302_6_dialog_content = "Espera, creo que lo escucho ahora.",
  ui_story_5020_50200302_7_dialog_content = "¡Parece que alguien está tratando de acercarse a nosotros!",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName!!!</size>",
  ui_story_5020_50200302_9_option_content = "¡¿Momo?!",
  ui_story_5020_50200302_10_dialog_content = "¿No se supone que debes evacuar a los civiles con Anzu?",
  ui_story_5020_50200302_11_option_content = "¡¿Anzu?!",
  ui_story_5020_50200302_12_dialog_content = "¿No se supone que debes evacuar a los civiles con Momo?",
  ui_story_5020_50200302_13_dialog_content = "No, PlayerName! ¡Soy Momo!",
  ui_story_5020_50200302_14_dialog_content = "¡Oh! L-Lo siento por eso... Es solo que ustedes dos se ven muy similares.",
  ui_story_5020_50200302_15_dialog_content = "¿Qué estás haciendo aquí? ¿Dónde están Anzu y los civiles?",
  ui_story_5020_50200302_16_dialog_content = "¡Estoy aquí!",
  ui_story_5020_50200302_17_dialog_content = "¡¿Por qué ustedes dos trajeron a toda la gente de vuelta?!",
  ui_story_5020_50200302_18_dialog_content = "¡Nunca nos fuimos! ¡Mientras ustedes cubrían nuestra retaguardia, aparecieron más fantasmas frente a nosotros!",
  ui_story_5020_50200302_19_dialog_content = "¡Estamos completamente rodeados!",
  ui_story_5020_50200302_20_dialog_content = "\"¡En estos tiempos difíciles, todos debemos abrir nuestro propio camino hacia la victoria!\"",
  ui_story_5020_50200302_21_dialog_content = "¿Por qué suena tan familiar?",
  ui_story_5020_50200302_22_dialog_content = "¿Lo hace?",
  ui_story_5020_50200302_23_dialog_content = "Hojeé la Guía de viaje de la Isla de las Nubes de Yao hace algún tiempo.",
  ui_story_5020_50200302_24_dialog_content = "Este fue uno de los eslóganes utilizados en la sección Moda del folleto.",
  ui_story_5020_50200302_25_dialog_content = "Para decirte la verdad, Rinne... No creo que sea realmente tu estilo...",
  ui_story_5020_50200302_26_dialog_content = "¿En serio? ¡Pensé que sonaba realmente genial!",
  ui_story_5020_50200302_27_dialog_content = "Es solo que por alguna extraña razón...",
  ui_story_5020_50200302_28_dialog_content = "no puedo conseguir la imagen de Sinsa vestido como un samurái rebelde de la Isla de las Nubes fuera de mi cabeza.",
  ui_story_5020_50200302_29_dialog_content = "Ahora que lo mencionas... yo también lo veo ahora.",
  ui_story_5020_50200302_30_dialog_content = "¡Bien! ¡Es hora de abrir nuestro propio camino hacia la victoria!",
  ui_story_5020_50200302_31_dialog_content = "¡A por ellos, soldados!",
  ui_story_5020_50200302_32_dialog_content = "¡¡¡Cargar!!!",
  ui_story_5020_50200302_33_dialog_content = "¡¿Q-Qué...?!",
  ui_story_5020_50200302_34_dialog_content = "¿Es esta realmente toda la ayuda que el General Fujikumo podría brindar?",
  ui_story_5020_50200302_35_dialog_content = "A juzgar por sus atuendos, supongo que son personas normales.",
  ui_story_5020_50200302_36_dialog_content = "Ellos son los rebeldes.",
  ui_story_5020_50200302_37_dialog_content = "Eso es <color=#FFB400>Jirón</color> a ti, muchas gracias!",
  ui_story_5020_50200302_38_dialog_content = "Ahora, ¿quién eres tú?",
  ui_story_5020_50200302_39_dialog_content = "Eran...",
  ui_story_5020_50200302_40_dialog_content = "Una sacerdotisa y un par de forasteros, ¿eh?",
  ui_story_5020_50200302_41_dialog_content = "¡Agárralos!",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>¡Achu!</anim>",
  ui_story_5020_50200401_2_dialog_content = "Uf... Alguien debe estar hablando mal de mí ahora mismo.",
  ui_story_5020_50200401_3_dialog_content = "Mis piernas están entumecidas por tanto estar en cuclillas... Pero ahora parece bastante seguro afuera.",
  ui_story_5020_50200401_4_dialog_content = "¡Ah, mucho mejor! ¡Un poco de estiramiento siempre hace el truco!",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50200401_6_dialog_content = "¿Cómo diablos lograron estos fantasmas entrar en el castillo principal?",
  ui_story_5020_50200401_7_dialog_content = "<size=45>¡Hoo-ah!</size>",
  ui_story_5020_50200401_8_dialog_content = "¿Qué le pasa a ese viejo? ¿No podría al menos proteger el castillo principal?",
  ui_story_5020_50200401_9_dialog_content = "¡Y ahora mi peinado está arruinado! Maldiciones... ¡¿Sabes cuánto se tarda en atarlo así?!",
  ui_story_5020_50200401_10_dialog_content = "Además... ¿Dónde estoy ahora?",
  ui_story_5020_50200401_11_dialog_content = "Este castillo es demasiado grande... ¿Y por qué parece que todos los pisos son exactamente iguales?",
  ui_story_5020_50200401_12_dialog_content = "¿He estado ya en este pasillo?",
  ui_story_5020_50200401_13_dialog_content = "Ugh, no es bueno... Necesito dejar marcadores o algo así.",
  ui_story_5020_50200401_14_dialog_content = "Uf, este es un fantasma fuerte... Debes haber comido mucho en tu tiempo, ¿eh?",
  ui_story_5020_50200401_15_dialog_content = "Ahora, si lo paro así... Pongo su brazo así... Y hago que sus dedos apunten de esa manera...",
  ui_story_5020_50200401_16_dialog_content = "¡Voila! ¡Ahora sé hacia dónde voy!",
  ui_story_5020_50200401_17_dialog_content = "Excepto... Ugh, esto realmente apesta.",
  ui_story_5020_50200401_18_dialog_content = "... ¡¿Dónde está la salida?! ¡¡No quiero tocar más fantasmas!!",
  ui_story_5020_50200401_19_dialog_content = "¡Argh, esto es tan asqueroso! ¡Lo juro, me daré al menos diez baños tan pronto como regrese!",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>Gong...!</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>¡Gong, Gong...!</color>",
  ui_story_5020_50200401_22_dialog_content = "Mierda... ¿Ese es el sonido de los tambores taiko? Rinne estaba hablando antes?",
  ui_story_5020_50200401_23_dialog_content = "¡¿Cuánto tiempo he estado atrapada aquí?!",
  ui_story_5020_50200401_24_dialog_content = "Grr... Consíguelo, Yao! ¡Vamos, cerebro, tenemos que resolver algo!",
  ui_story_5020_50200401_25_dialog_content = "PlayerName Siempre dice que confíe en mi intuición.",
  ui_story_5020_50200401_26_dialog_content = "Y mi intuición me dice que vaya por este camino...",
  ui_story_5020_50200401_27_dialog_content = "Ahora dice que gire a la izquierda...",
  ui_story_5020_50200401_28_dialog_content = "¡J-Solo tengo que seguir girando a la derecha! Estoy seguro de que no he estado así antes...",
  ui_story_5020_50200401_29_dialog_content = "...",
  ui_story_5020_50200401_30_dialog_content = "PlayerName, ¡mentiroso! ¡¡Mi intuición es completamente inútil!!",
  ui_story_5020_50200401_31_dialog_content = "Agh, olvídalo.",
  ui_story_5020_50200401_32_dialog_content = "En lugar de golpear mi cabeza contra la pared de esta manera, debería hacer lo que hizo el maestro y simplemente saltar del Pabellón de las Nubes.",
  ui_story_5020_50200401_33_dialog_content = "¡Bien! ¡Suena como un plan sólido para mí!",
  ui_story_5020_50200401_34_dialog_content = "Sí... quiero decir, desde aquí arriba...",
  ui_story_5020_50200401_35_dialog_content = "¡No parece tan alto en absoluto!",
  ui_story_5020_50200401_36_dialog_content = "La Maestra probablemente usó ese cerezo para amortiguar su caída... ¿verdad?",
  ui_story_5020_50200401_37_dialog_content = "Muy bien, cerezo... Listo o no, ¡aquí voy!",
  ui_story_5020_50200401_38_dialog_content = "...",
  ui_story_5020_50200401_39_dialog_content = "¡¡Yo... no puedo hacerlo!!",
  ui_story_5020_50200401_40_dialog_content = "No sé cómo lo hizo el maestro, ¡pero estoy seguro de que no puedo!",
  ui_story_5020_50200401_41_dialog_content = "Quiero decir, mira lo lejos que estoy...",
  ui_story_5020_50200401_41X1_dialog_content = "¡Un verdadero guerrero nunca haría nada de lo que no esté seguro!",
  ui_story_5020_50200401_41X2_dialog_content = "Veré si hay una cuerda o algo que me ayude a bajar...",
  ui_story_5020_50200401_41X3_dialog_content = "Ahh... El único lugar para esconder algo en esta habitación debería ser...",
  ui_story_5020_50200401_41X4_dialog_content = "¡El ropero!",
  ui_story_5020_50200401_41X5_dialog_content = "¿Mmm?",
  ui_story_5020_50200401_41X6_dialog_content = "¿Qué fue eso?",
  ui_story_5020_50200401_41X7_dialog_content = "¿Por qué este sentimiento es tan <color=#FFB400>familiar</color>?",
  ui_story_5020_50200401_41X8_dialog_content = "¡No importa! ¡Abriré el armario y buscaré una cuerda primero!",
  ui_story_5020_50200401_42_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_44_dialog_content = "¡¿Eh?!",
  ui_story_5020_50200401_45_dialog_content = "¿Una campana Kagura?",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>¡Ding... Ding... Ding!</color>",
  ui_story_5020_50200401_47_dialog_content = "Oh... un <color=#FFB400>carillón de viento</color> ¿en el ropero?",
  ui_story_5020_50200401_48_dialog_content = "Extraño... ¿Por qué suena tanto como una campana Kagura?",
  ui_story_5020_50200401_49_dialog_content = "Espera... Esto es...",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>Hace diez años.</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_52_dialog_content = "¡Shh! Tranquilo, Yao! ¡Quédate adentro y no hagas ruido!",
  ui_story_5020_50200401_53_dialog_content = "¿Qué está pasando afuera, Tsuki? Tengo miedo...",
  ui_story_5020_50200401_54_dialog_content = "No me vas a dejar aquí solo, ¿verdad?",
  ui_story_5020_50200401_55_dialog_content = "Por favor Tsuki...",
  ui_story_5020_50200401_56_dialog_content = "Solo duerme un rato dentro de esto <color=#FFB400>guardarropa</color>, y todo estará bien cuando te despiertes. Prometo.",
  ui_story_5020_50200401_57_dialog_content = "Tsuki...",
  ui_story_5020_50200401_58_dialog_content = "<size=45>¡Abrir!</size>",
  ui_story_5020_50200401_58X1_dialog_content = "(¡Alguien está tratando de entrar!)",
  ui_story_5020_50200401_58X2_dialog_content = "¡Venir! ¡Cuida la puerta! ¡No dejes que ninguna de las vil presencia entre aquí!",
  ui_story_5020_50200401_58X3_dialog_content = "\"Una oda a los muertos y a los vivos. May esta canción guía vuestras almas de vuelta al lugar que les corresponde...\"",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5020_50200401_58X5_dialog_content = "(¡Es un canto de Kagura Bell que exorciza fantasmas...!)",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5020_50200401_59_dialog_content = "¡Detener! ¡¿Quién es usted?! no puedes...",
  ui_story_5020_50200401_60_dialog_content = "<size=45>¡Batirlo!</size>",
  ui_story_5020_50200401_61_dialog_content = "(Esa voz... ¿Maestro?)",
  ui_story_5020_50200401_62_dialog_content = "Nagi?",
  ui_story_5020_50200401_63_dialog_content = "No te atrevas a llamarme así, <color=#FFB400>dama sacerdotisa</color>.",
  ui_story_5020_50200401_64_dialog_content = "No te lo mereces.",
  ui_story_5020_50200401_65_dialog_content = "Dime... ¿Por qué convenciste al Wisp para que se rindiera?",
  ui_story_5020_50200401_66_dialog_content = "¡Me prometiste que te convertirías en sacerdotisa por el bien de la gente! ¡Para traer prosperidad a todos en Cloud Island!",
  ui_story_5020_50200401_67_dialog_content = "...",
  ui_story_5020_50200401_68_dialog_content = "¡Te hice una pregunta!",
  ui_story_5020_50200401_69_dialog_content = "¡¿?!",
  ui_story_5020_50200401_70_dialog_content = "Tsuki!",
  ui_story_5020_50200401_71_dialog_content = "¡¿Has perdido la cabeza, Nagi?!",
  ui_story_5020_50200401_72_dialog_content = "¡Ella es tu hermana!",
  ui_story_5020_50200401_73_dialog_content = "¡Guardias! ¡Mátala ahora!",
  ui_story_5020_50200401_74_dialog_content = "No...!",
  ui_story_5020_50200401_75_dialog_content = "Por favor, Kubou-sama... No hagas esto...",
  ui_story_5020_50200401_76_dialog_content = "El río bajo nuestros pies pasa por las granjas de arroz al oeste de la ciudad...",
  ui_story_5020_50200401_77_dialog_content = "El jardín que se encuentra en las estribaciones occidentales... Los cerezos blancos deben estar en plena floración ahora...",
  ui_story_5020_50200401_78_dialog_content = "Por favor, no manches sus hermosos pétalos con el color de la sangre...",
  ui_story_5020_50200401_79_dialog_content = "Cuando me haya ido... Acuéstame para descansar bajo esos cerezos en flor blancos...",
  ui_story_5020_50200401_80_dialog_content = "Prométeme... ¿de acuerdo?",
  ui_story_5020_50200401_81_dialog_content = "¡Espera, Tsuki! Lo prometo, lo haré...",
  ui_story_5020_50200401_82_dialog_content = "\"Una oda... a los muertos y a los vivos...\"",
  ui_story_5020_50200401_83_dialog_content = "Espera... ¡¿Qué estás haciendo?!",
  ui_story_5020_50200401_84_dialog_content = "¡Tsuki, no! ¡Tu cuerpo no lo soportará ahora!",
  ui_story_5020_50200401_85_dialog_content = "\"May esta canción...\"",
  ui_story_5020_50200401_86_dialog_content = "\"Guía mi alma de regreso al lugar que le corresponde\".",
  ui_story_5020_50200401_87_dialog_content = "¡Urgh...!",
  ui_story_5020_50200401_88_dialog_content = "...",
  ui_story_5020_50200401_89_dialog_content = "...",
  ui_story_5020_50200401_90_dialog_content = "Incluso después de todo lo que ha pasado, ¿aún deseas protegerla...?",
  ui_story_5020_50200401_91_dialog_content = "Guardias...",
  ui_story_5020_50200401_92_dialog_content = "A partir de este día, el ejército fantasma protegerá estos terrenos para siempre.",
  ui_story_5020_50200401_93_dialog_content = "¡Encerrad a esta mujer por el resto de su miserable vida, para que nunca más vea la luz del día con sus propios ojos!",
  ui_story_5020_50200401_94_dialog_content = "¡Sí!",
  ui_story_5020_50200401_95_dialog_content = "El resto... Se hará de acuerdo con los deseos de Tsuki.",
  ui_story_5020_50200401_96_dialog_content = "Como usted ordene.",
  ui_story_5020_50200401_97_dialog_content = "En cuanto a ti...",
  ui_story_5020_50200401_98_dialog_content = "Todo lo que ella quería era protegerte, y tú la asesinaste a cambio... ¿No tienes vergüenza? ¿No tienes corazón?",
  ui_story_5020_50200401_99_dialog_content = "Nunca necesité su protección, y morirás en mis manos, como ella.",
  ui_story_5020_50200401_100_dialog_content = "Has estado ciega a la verdad todo este tiempo, Nagi...",
  ui_story_5020_50200401_101_dialog_content = "Ciega a la razón detrás de su decisión de estar a mi lado.",
  ui_story_5020_50200401_102_dialog_content = "Fue precisamente porque le di una especie de aprobación silenciosa, que se enteró de cosas que nunca debería haber sabido.",
  ui_story_5020_50200401_103_dialog_content = "La diferencia entre exorcizar fantasmas y controlarlos no es tan grande como parece, pero las leyes y costumbres de Cloud Island se pueden entender a través de esta distinción.",
  ui_story_5020_50200401_104_dialog_content = "Preservar la paz en Cloud Island es un esfuerzo de toda la vida. Ella entendió esto, así como mi posición, y obedientemente depositó su confianza en mí.",
  ui_story_5020_50200401_105_dialog_content = "Y sabiendo lo que sabía, eligió protegerte a pesar de tu violenta ignorancia.",
  ui_story_5020_50200401_106_dialog_content = "¡No, tu estas equivocado!",
  ui_story_5020_50200401_107_dialog_content = "Pero, ¿qué otra cosa podría ser, entonces?",
  ui_story_5020_50200401_108_dialog_content = "¿Los lazos de hermandad que has cortado por completo?",
  ui_story_5020_50200401_109_dialog_content = "Tenía la misma edad que tú, pero sus ojos siempre estaban llenos de compasión y comprensión, de una sabiduría mucho más allá de su edad...",
  ui_story_5020_50200401_110_dialog_content = "Y sin embargo... ¡¡¡La asesinaste!!!",
  ui_story_5020_50200401_111_dialog_content = "¡Tú le quitaste la vida y sus esperanzas y sueños para Cloud Island con ella!",
  ui_story_5020_50200401_112_dialog_content = "¡¿Qué derecho tienes de vivir en este mundo por más tiempo?!?!",
  ui_story_5020_50200401_113_dialog_content = "...",
  ui_story_5020_50200401_114_dialog_content = "<size=33>¡¿Por qué eligió protegerte, incluso a costa de su propia vida...?!</size>",
  ui_story_5020_50200401_115_dialog_content = "¡Qué honor para mí haber podido escuchar un discurso tan grandioso!",
  ui_story_5020_50200401_116_dialog_content = "Retorcer la narrativa de su explotación de ella, en una historia de confianza y comprensión...",
  ui_story_5020_50200401_117_dialog_content = "¡¿Así es como la engañaste?!",
  ui_story_5020_50200401_118_dialog_content = "Era una persona de extraordinaria sabiduría.",
  ui_story_5020_50200401_119_dialog_content = "En su corazón, sabía que nuestros objetivos eran proteger este lugar a toda costa. Como tal, la palabra explotación no existía entre nosotros.",
  ui_story_5020_50200401_120_dialog_content = "... Veo. El sello que te ha puesto es exactamente el castigo que te mereces.",
  ui_story_5020_50200401_121_dialog_content = "May pasas el resto de tus días aquí, sin nada más que tu odio y tu ira para hacerte compañía.",
  ui_story_5020_50200401_122_dialog_content = "¡Te juro que algún día te mataré!",
  ui_story_5020_50200401_123_dialog_content = "Veremos si ese día llega.",
  ui_story_5020_50200401_124_dialog_content = "Tsuki...?",
  ui_story_5020_50200401_125_dialog_content = "Mi amo... Fue el que <size=45>¿Mató a la sacerdotisa?</size>",
  ui_story_5020_50200401_126_dialog_content = "Pero mi maestro no es ese tipo de persona...",
  ui_story_5020_50200401_127_dialog_content = "¿También la usaste así en el pasado?",
  ui_story_5020_50200401_128_dialog_content = "Niña... No eres más que un reemplazo.",
  ui_story_5020_50200401_129_dialog_content = "¿Sabes lo que le pasó a la última sacerdotisa?",
  ui_story_5020_50200401_130_dialog_content = "¡Callate la boca!",
  ui_story_5020_50200401_131_dialog_content = "¡Guardias, agárrenla!",
  ui_story_5020_50200401_132_dialog_content = "No... Tiene que haber algún tipo de error.",
  ui_story_5020_50200401_133_dialog_content = "Urgh... Mi cabeza...",
  ui_story_5020_50200401_134_dialog_content = "necesito unirme a PlayerName, y cuéntales todo esto!",
  ui_story_5020_50200501_1_dialog_content = "¡Oye! ¡Déjanos ir! ¿No podemos simplemente usar nuestras palabras?",
  ui_story_5020_50200501_2_dialog_content = "¡Así es! ¡Debe haber algún malentendido!",
  ui_story_5020_50200501_3_dialog_content = "...",
  ui_story_5020_50200501_4_dialog_content = "Debería estar a salvo aquí, por ahora.",
  ui_story_5020_50200501_5_dialog_content = "Ve a ayudar a la gente a instalarse.",
  ui_story_5020_50200501_6_dialog_content = "¡Sí!",
  ui_story_5020_50200501_7_dialog_content = "En cuanto a esos bocazas...",
  ui_story_5020_50200501_8_dialog_content = "Átelos a un poste en alguna parte.",
  ui_story_5020_50200501_9_dialog_content = "¿¡Qué!?",
  ui_story_5020_50200501_10_dialog_content = "¡Sí!",
  ui_story_5020_50200501_11_dialog_content = "¡Oye! ¡Deja de dar vueltas!",
  ui_story_5020_50200501_12_dialog_content = "Uf... Estos tipos...",
  ui_story_5020_50200501_13_dialog_content = "¡Espera un minuto, hay algo que no entiendo!",
  ui_story_5020_50200501_14_dialog_content = "Ustedes están protegiendo a los civiles, ¿verdad? ¡Así somos nosotros! ¿No significa eso que estamos en la misma página?",
  ui_story_5020_50200501_15_dialog_content = "Para nada.",
  ui_story_5020_50200501_16_dialog_content = "Estás con la sacerdotisa, lo que significa que vamos juntos tan bien como el agua y el fuego.",
  ui_story_5020_50200501_17_dialog_content = "¿La sacerdotisa? ¿Qué tiene que ver ella con eso...?",
  ui_story_5020_50200501_18_dialog_content = "Entiendo.",
  ui_story_5020_50200501_19_dialog_content = "Si no me equivoco, Amemori es uno de ustedes, ¿correcto?",
  ui_story_5020_50200501_20_dialog_content = "Recuerda tu lugar, sacerdotisa.",
  ui_story_5020_50200501_21_dialog_content = "No está en posición de hacernos preguntas.",
  ui_story_5020_50200501_22_dialog_content = "Je... Parece que hablé fuera de lugar.",
  ui_story_5020_50200501_23_dialog_content = "¿Quizás deberíamos esperar a que se presenten?",
  ui_story_5020_50200501_24_dialog_content = "¿O tal vez incluso dejarte pronunciar tu discurso de reclutamiento...?",
  ui_story_5020_50200501_25_dialog_content = "Jajajaja! Así que la sacerdotisa tiene sentido del humor, ¿eh?",
  ui_story_5020_50200501_26_dialog_content = "Quién sabía que llegaría un día en que una sacerdotisa de Cloud Island ni siquiera sabría quiénes son los Wisp.",
  ui_story_5020_50200501_27_dialog_content = "Quién sabe, tal vez en unas pocas generaciones, ¡incluso la propia Isla de las Nubes será olvidada!",
  ui_story_5020_50200501_28_dialog_content = "Al final, no es como si nada de eso te importara.",
  ui_story_5020_50200501_29_dialog_content = "Como sacerdotisa, solo necesitas quedarte en tu castillo grande y cómodo, y pasar tus días preocupando tu linda cabecita por ese Kubou-sama tuyo.",
  ui_story_5020_50200501_30_dialog_content = "...",
  ui_story_5020_50200501_31_dialog_content = "¡Eso es demasiado!",
  ui_story_5020_50200501_32_dialog_content = "Rinne ¡Ha estado protegiendo a la gente de Koufu-jou todo este tiempo! ¡Ustedes mismos lo vieron!",
  ui_story_5020_50200501_33_dialog_content = "¿Proteger? Ahórranos los eufemismos elevados, forastero.",
  ui_story_5020_50200501_34_dialog_content = "Ella no es más que un gato doméstico, persiguiendo y matando ratas criadas en casa.",
  ui_story_5020_50200501_35_dialog_content = "Eso no es protección. Es una actuación.",
  ui_story_5020_50200501_36_dialog_content = "¿Una actuación? Que se supone que significa eso...?",
  ui_story_5020_50200501_37_dialog_content = "Déjame preguntarte algo, ¿de dónde crees que vinieron todos estos fantasmas?",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_39_dialog_content = "Eres una experta en el tema, ¿verdad, sacerdotisa? ¿Le importaria explicar?",
  ui_story_5020_50200501_40_dialog_content = "... Cuando hay abundancia de energía Yin, las almas de los muertos no pueden descansar y, en cambio, regresan como fantasmas vengativos.",
  ui_story_5020_50200501_41_dialog_content = "Entonces dinos, ¿de dónde vino esta abundancia de energía Yin? ¿De la nada?",
  ui_story_5020_50200501_42_dialog_content = "...",
  ui_story_5020_50200501_43_dialog_content = "Permanecer en silencio, ¿eh? No te preocupes, ya sé la respuesta: <color=#FFB400>alguien</color> está detrás de él.",
  ui_story_5020_50200501_44_dialog_content = "Desde la antigüedad, Cloud Island ha sido el hogar de tres <color=#FFB400>artefactos espirituales</color>.",
  ui_story_5020_50200501_45_dialog_content = "<color=#FFB400>Pedazo de cielo</color>, la espada que mata fantasmas y fuente de energía Yang, está actualmente desaparecida.",
  ui_story_5020_50200501_46_dialog_content = "<color=#FFB400>Rebelión y Ryojin</color>, el jade que equilibra el Yin y el Yang, está en posesión de Wisp.",
  ui_story_5020_50200501_47_dialog_content = "Y el <color=#FFB400>Espejo de nube</color>, la fuente de energía Yin, siempre ha estado en manos del general.",
  ui_story_5020_50200501_48_dialog_content = "Ese fue el espejo que le robó el general Rinne más temprano...",
  ui_story_5020_50200501_49_dialog_content = "\"Así como las nubes oscuras oscurecen el sol, los habitantes del infierno cruzan al mundo de los vivos\".",
  ui_story_5020_50200501_50_dialog_content = "Lo único que podría convocar a tantos fantasmas para enloquecer en la ciudad... Es el <color=#FFB400>Espejo de nube</color>.",
  ui_story_5020_50200501_51_dialog_content = "Así que dime, ¿quién crees que es el autor intelectual detrás de todo esto? ¡Estoy seguro de que ya puedes adivinar!",
  ui_story_5020_50200501_52_dialog_content = "... Para ser honesto, también hemos llegado a una conclusión similar.",
  ui_story_5020_50200501_53_dialog_content = "Pero todavía hay algo que no puedo entender.",
  ui_story_5020_50200501_54_dialog_content = "Si Fujikumo puede controlar fantasmas a su voluntad, ¿por qué sigue criando y entrenando sacerdotisas para exorcizarlos?",
  ui_story_5020_50200501_55_dialog_content = "¿No te lo dije ya? No es más que una actuación.",
  ui_story_5020_50200501_56_dialog_content = "Los fantasmas están aquí porque cumplen sus órdenes. La sacerdotisa es solo una figura decorativa utilizada para conquistar a las personas y mantenerlas bajo control.",
  ui_story_5020_50200501_57_dialog_content = "¿Mantenerlos bajo control?",
  ui_story_5020_50200501_58_dialog_content = "El general controla los fantasmas, que utiliza para sembrar el miedo en los corazones de los civiles de Cloud Island.",
  ui_story_5020_50200501_59_dialog_content = "Pero el miedo no es forma de gobernar Cloud Island. Cualquier líder real podría decirte eso.",
  ui_story_5020_50200501_60_dialog_content = "Ahí es donde entra en juego la sacerdotisa. Están entrenados para enfrentar este miedo por el bien de la gente.",
  ui_story_5020_50200501_61_dialog_content = "El pueblo llega a confiar en la sacerdotisa, y la sacerdotisa obedece al general y sólo a él. Este es su método de gobernarnos a todos.",
  ui_story_5020_50200501_62_dialog_content = "Desafortunadamente para él, se sobreestimó.",
  ui_story_5020_50200501_63_dialog_content = "La gente de Cloud Island no es estúpida. No nos dejaremos engañar por un acto de engaño de dos bits como este.",
  ui_story_5020_50200501_64_dialog_content = "Ustedes sacerdotisas afirman que al exorcizar fantasmas, están devolviendo el equilibrio a la tierra... Y sin embargo, ¿cómo es que la amenaza de los fantasmas nunca ha disminuido después de todo este tiempo?",
  ui_story_5020_50200501_65_dialog_content = "...",
  ui_story_5020_50200501_66_dialog_content = "Este lugar no siempre se llamó Koufu-jou. Eso es mucho, no lo hemos olvidado.",
  ui_story_5020_50200501_67_dialog_content = "No importa cuántos castillos construyan, o cuánta riqueza traigan...",
  ui_story_5020_50200501_68_dialog_content = "Siempre serán invasores para nosotros.",
  ui_story_5020_50200501_69_dialog_content = "Los Wisp son los únicos verdaderos guardianes de Cloud Island.",
  ui_story_5020_50200501_70_dialog_content = "Porque solo nosotros somos nativos de esta tierra.",
  ui_story_5020_50200501_71_dialog_content = "invasores? ¿Es así como ves a la gente en la isla principal...?",
  ui_story_5020_50200501_72_dialog_content = "Supongo que no han aprendido mucho sobre la historia de Cloud Island.",
  ui_story_5020_50200501_73_dialog_content = "Y eso tiene sentido. Quiero decir, ¿dónde podrías haberlo aprendido?",
  ui_story_5020_50200501_74_dialog_content = "(Aprendí un poco de la historia de Cloud Island de Anzu y Momo...)",
  ui_story_5020_50200501_75_dialog_content = "(¿Pero la versión de Wisp podría tener algunas diferencias clave?)",
  ui_story_5020_50200501_76_dialog_content = "Estás bien. No sabemos mucho sobre Cloud Island en absoluto, ya que somos de un lugar lejano.",
  ui_story_5020_50200501_77_dialog_content = "Lo supuse. Permítanme informarles sobre algunos de los puntos más importantes. Considéralo un pequeño acto de misericordia.",
  ui_story_5020_50200501_78_dialog_content = "Años y años atrás, antes de que los samuráis de la isla principal pusieran un pie en la Isla de las Nubes, era un lugar mucho más hermoso de lo que es ahora.",
  ui_story_5020_50200501_79_dialog_content = "Un lugar abundante, libre de conflictos, en el que los fantasmas rara vez aparecían para aterrorizar la tierra.",
  ui_story_5020_50200501_80_dialog_content = "Los orígenes de Wisp se remontan a esa época. En aquel entonces, era nuestra misión sagrada luchar contra los fantasmas y asegurar la paz en Cloud Island.",
  ui_story_5020_50200501_81_dialog_content = "Pero quienes finalmente arruinaron esa paz no fueron los fantasmas, sino los vivos.",
  ui_story_5020_50200501_82_dialog_content = "Nunca satisfechos con la tierra que ya ocupaban, la isla principal envió a su primer general a conquistar este lugar.",
  ui_story_5020_50200501_83_dialog_content = "Wisp nunca había librado una guerra contra los vivos antes, pero arriesgaron sus vidas, de todos modos.",
  ui_story_5020_50200501_84_dialog_content = "El general lanzó campañas contra Cloud Island, pero nunca pudo anexarnos por completo.",
  ui_story_5020_50200501_85_dialog_content = "Pero un día, idearon su plan más despreciable hasta el momento. Comenzaron a aprender a controlar fantasmas, para poder usar su fuerza maligna en la batalla.",
  ui_story_5020_50200501_86_dialog_content = "En esos años, no faltaban los fantasmas salvajes que deambulaban por la tierra.",
  ui_story_5020_50200501_87_dialog_content = "Nos derrumbamos bajo la amenaza fantasmal, junto con la soberanía de Cloud Island. Poco después, el general construyó Koufu-jou a lo largo del océano y lo designó como su sede de poder.",
  ui_story_5020_50200501_88_dialog_content = "Sin otra opción, los restos de Wisp se vieron obligados a esconderse, albergando su furia contra sus invasores y transmitiendo ese odio de generación en generación.",
  ui_story_5020_50200501_89_dialog_content = "Si algo nos enseñó la guerra es a esperar la oportunidad perfecta. Entonces, y solo entonces, Cloud Island recuperará lo que perdió hace tantos años.",
  ui_story_5020_50200501_90_dialog_content = "(Entonces, ¿así es como surgió el conflicto en Cloud Island...?)",
  ui_story_5020_50200501_91_dialog_content = "(Aparentemente, era una batalla entre personas y fantasmas, pero en realidad... Era una guerra entre dos naciones diferentes...)",
  ui_story_5020_50200501_92_dialog_content = "Y esta oportunidad...",
  ui_story_5020_50200501_93_dialog_content = "Podría estar sobre nosotros pronto.",
  ui_story_5020_50200501_94_dialog_content = "La gente está a salvo ahora, señor.",
  ui_story_5020_50200501_95_dialog_content = "A continuación, tenemos que...",
  ui_story_5020_50200501_96_dialog_content = "Veo. Hablemos por ahí.",
  ui_story_5020_50200501_97_dialog_content = "...",
  ui_story_5020_50200501_98_dialog_content = "¿Crees que estaba diciendo la verdad sobre la historia de Cloud Island?",
  ui_story_5020_50200501_99_dialog_content = "No sé... Dijo tanto, todavía no lo he digerido todo...",
  ui_story_5020_50200501_100_dialog_content = "Siempre he pensado que estaba prestando atención a la orden más simple.",
  ui_story_5020_50200501_101_dialog_content = "Obedecer a mi padre adoptivo y proteger a la gente de Koufu-jou.",
  ui_story_5020_50200501_102_dialog_content = "Pero si lo que dice es cierto...",
  ui_story_5020_50200501_103_dialog_content = "Entonces hay una paradoja entre estos dos comandos.",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_105_dialog_content = "Todo lo que he hecho... ¿Realmente no ha sido más que una actuación?",
  ui_story_5020_50200501_106_dialog_content = "N-No necesitamos creer todo lo que dijo, ¿verdad?",
  ui_story_5020_50200501_107_dialog_content = "Quiero decir, ni siquiera puede notar la diferencia entre amigo y enemigo. ¡Mira cómo nos ató!",
  ui_story_5020_50200501_108_dialog_content = "Derecha, PlayerName?",
  ui_story_5020_50200501_109_dialog_content = "¿Por qué pareces estar distraído?",
  ui_story_5020_50200501_110_dialog_content = "Shhh—",
  ui_story_5020_50200501_111_dialog_content = "Estoy tratando de escuchar a escondidas su conversación...",
  ui_story_5020_50200501_112_dialog_content = "¡¿Escuchar a escondidas?!",
  ui_story_5020_50200501_113_dialog_content = "¡Suena divertido! ¡Yo también quiero unirme!",
  ui_story_5020_50200501_114_dialog_content = "Bien, acércate entonces.",
  ui_story_5020_50200501_115_dialog_content = "Mm-hmm!",
  ui_story_5020_50200501_116_dialog_content = "No hay otro lugar al que podamos ir, señor.",
  ui_story_5020_50200501_117_dialog_content = "Las calles están llenas de fantasmas. No hemos podido contactar con ninguna de nuestras personas estacionadas en otros lugares...",
  ui_story_5020_50200501_118_dialog_content = "Veo. No vamos a ninguna parte y defenderemos este lugar con nuestras vidas.",
  ui_story_5020_50200501_119_dialog_content = "Señor, usted mencionó que Amemori-sama logro rescatar al comandante, si?",
  ui_story_5020_50200501_120_dialog_content = "¿Crees que... vendrán a ayudarnos?",
  ui_story_5020_50200501_121_dialog_content = "No hay razón para tener miedo. Mientras la Espada del Inframundo esté viva y bien, ¿qué son unos cuantos fantasmas más?",
  ui_story_5020_50200501_122_dialog_content = "(Entonces Amemori está de su lado, después de todo!)",
  ui_story_5020_50200501_123_dialog_content = "(Sí... Y por lo que parece, ella ocupa una posición bastante alta dentro de Wisp).",
  ui_story_5020_50200501_124_dialog_content = "Escucha aquí, chico. Wisp nunca ha necesitado la ayuda de nadie cuando se trata de una batalla.",
  ui_story_5020_50200501_125_dialog_content = "Incluso si eres el último en pie, debes luchar hasta el amargo final.",
  ui_story_5020_50200501_126_dialog_content = "¿Significa eso que ellos...",
  ui_story_5020_50200501_127_dialog_content = "El comandante y Amemori-sama tiene otros asuntos que tratar.",
  ui_story_5020_50200501_128_dialog_content = "No estoy preocupado en lo más mínimo, y tú tampoco deberías estarlo.",
  ui_story_5020_50200501_129_dialog_content = "(Oh, cierto... me pregunto cómo Amemori está haciendo ahora...)",
  ui_story_5020_50200501_130_dialog_content = "(Relájate, estoy seguro de que está perfectamente bien. Después de todo, es increíblemente fuerte).",
  ui_story_5020_50200501_131_dialog_content = "...",
  ui_story_5020_50200501_132_dialog_content = "Todo el mundo se siente aliviado al saber que el comandante está a salvo, señor.",
  ui_story_5020_50200501_133_dialog_content = "Es solo que... Ninguno de nosotros ha visto nunca la cara del comandante.",
  ui_story_5020_50200501_134_dialog_content = "Un número de nuestra gente está empezando a preguntarse si la noticia es cierta o no.",
  ui_story_5020_50200501_135_dialog_content = "Algunos incluso dicen...",
  ui_story_5020_50200501_136_dialog_content = "Que después de diez años, casi se ha olvidado de Wisp...",
  ui_story_5020_50200501_137_dialog_content = "...",
  ui_story_5020_50200501_138_dialog_content = "Eso es suficiente.",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5020_50200501_140_dialog_content = "(?!)",
  ui_story_5020_50200501_141_dialog_content = "¿Qué tal?",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5020_50200501_143_dialog_content = "(¡Está cerca! ¡Parece que viene del otro lado de la pared!)",
  ui_story_5020_50200501_144_dialog_content = "¡Prepárate para la batalla!",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>Graaaah!!</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "¿Cómo nos encontraron tan rápido...?",
  ui_story_5020_50200501_148_dialog_content = "Ah, solo era cuestión de tiempo, supongo.",
  ui_story_5020_50200501_149_dialog_content = "Hermanos de Wisp!",
  ui_story_5020_50200501_150_dialog_content = "¡¡¡Sí señor!!!",
  ui_story_5020_50200501_151_dialog_content = "¡Reúne tu coraje!",
  ui_story_5020_50200501_152_dialog_content = "¡Enviaremos a cada uno de estos fantasmas de vuelta al subsuelo!",
  ui_story_5020_50200501_153_dialog_content = "Esto no es bueno... ¡Los fantasmas nos encontraron!",
  ui_story_5020_50200501_154_dialog_content = "¡Sé! ¡¿Qué debemos hacer ahora?!",
  ui_story_5020_50200501_155_dialog_content = "¡No podemos hacer nada mientras estemos atados!",
  ui_story_5020_50200501_156_dialog_content = "<size=45>¡Oye! Date prisa y déjanos ir!!!</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>¡¡¡Podemos ayudarte a combatirlos!!!</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_159_dialog_content = "Uh... ¿Estás escuchando?",
  ui_story_5020_50200501_160_dialog_content = "¿Qué hay de usar sus habilidades psíquicas?",
  ui_story_5020_50200501_161_dialog_content = "¡Correcto! I...",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50200501_164_dialog_content = "¡Oh, no! En un momento como este, también...",
  ui_story_5020_50200501_165_dialog_content = "¡Se está acercando!",
  ui_story_5020_50200501_166_dialog_content = "Incluso si llamo a un luchador Wisp... ¿Llegarán a tiempo?",
  ui_story_5020_50200501_167_dialog_content = "¡Dígame usted!",
  ui_story_5020_50200501_168_dialog_content = "Je... Sólo tenemos que encontrar a alguien que nos libere, ¿verdad?",
  ui_story_5020_50200501_169_dialog_content = "Si Wisp no está dispuesto a ayudar, tendremos que conformarnos con esa cosa.",
  ui_story_5020_50200501_170_dialog_content = "¿Esa cosa? Espera, no querrás decir...",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>Grrr...</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "¿Dejar que el fantasma corte la cuerda? ¡Creo que nos trituraremos primero!",
  ui_story_5020_50200501_170X3_dialog_content = "Bueno, entonces deberías mantenerte bajo por un momento.",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>Uaaagh...</anim>",
  ui_story_5020_50200501_173_dialog_content = "¿Ves?",
  ui_story_5020_50200501_174_dialog_content = "Los fantasmas a veces pueden ser más obedientes que las personas.",
  ui_story_5020_50200502_1_dialog_content = "¡Señor! ¡Los fantasmas vienen de todas direcciones!",
  ui_story_5020_50200502_2_dialog_content = "¡Estamos rodeados!",
  ui_story_5020_50200502_3_dialog_content = "Su ataque sorpresa en este momento fue para ganar tiempo para establecer su asedio...",
  ui_story_5020_50200502_4_dialog_content = "Con tácticas como esta, algo debe estar sucediendo detrás de escena.",
  ui_story_5020_50200502_5_dialog_content = "A qué se refiere, señor...?",
  ui_story_5020_50200502_6_dialog_content = "En todos nuestros años de lucha contra fantasmas, ¿alguna vez Wisp ha sido arrinconado por ellos?",
  ui_story_5020_50200502_7_dialog_content = "Los fantasmas no son las criaturas más perceptivas. Se sienten atraídos por el combate, sí, pero nunca tan rápido.",
  ui_story_5020_50200502_8_dialog_content = "Y para ponernos en una situación como esta... Primero tenían que discernir nuestra ubicación, luego unirse y rodearnos antes de finalmente atacarnos todos a la vez.",
  ui_story_5020_50200502_9_dialog_content = "Alguien tiene que estar controlando sus acciones.",
  ui_story_5020_50200502_10_dialog_content = "Parece que el general... finalmente está haciendo su movimiento.",
  ui_story_5020_50200502_11_dialog_content = "¿Qué debemos hacer entonces, señor?",
  ui_story_5020_50200502_12_dialog_content = "Primero tenemos que entender la situación, para que podamos buscar una manera a través de sus filas.",
  ui_story_5020_50200502_13_dialog_content = "Como mínimo, tenemos que sacar a los civiles de Koufu-jou a salvo...",
  ui_story_5020_50200502_14_dialog_content = "(¡Cuidado detrás de ti!)",
  ui_story_5020_50200502_15_dialog_content = "¡¿?!",
  ui_story_5020_50200502_16_dialog_content = "¡¿Quién dijo eso hace un momento?!",
  ui_story_5020_50200502_17_dialog_content = "(¡Soy yo! ¡Uno de los forasteros que ataste antes!)",
  ui_story_5020_50200502_18_dialog_content = "¿Cómo escapó?",
  ui_story_5020_50200502_19_dialog_content = "Si eres lo suficientemente valiente como para hablar conmigo, ¡entonces deja de escabullirte y muéstrate!",
  ui_story_5020_50200502_20_dialog_content = "(Er... en realidad no estoy cerca de ti en este momento).",
  ui_story_5020_50200502_21_dialog_content = "(Estoy usando mi habilidad psíquica para comunicarme contigo).",
  ui_story_5020_50200502_22_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5020_50200502_23_dialog_content = "(Bueno, es... Uh, no importa. No es importante.)",
  ui_story_5020_50200502_24_dialog_content = "(¡Lo importante es que mis amigos y yo podemos ayudarte!)",
  ui_story_5020_50200502_25_dialog_content = "¿Ayuda? ¡Ja! ¡Wisp nunca pide ayuda, especialmente a prisioneros como tú!",
  ui_story_5020_50200502_26_dialog_content = "(Con todos los fantasmas atacando aquí, ¿es realmente el momento de actuar alto y poderoso?)",
  ui_story_5020_50200502_27_dialog_content = "¡Por qué tú...!",
  ui_story_5020_50200502_28_dialog_content = "(¡Los fantasmas se acercan desde la calle a su derecha!)",
  ui_story_5020_50200502_29_dialog_content = "¿De la derecha?",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>Gruñido ... </anim>",
  ui_story_5020_50200502_31_dialog_content = "Estás diciendo la verdad...",
  ui_story_5020_50200502_32_dialog_content = "¡Ojos a la derecha! ¡Soldados, ataquen!",
  ui_story_5020_50200502_33_dialog_content = "(Uh, en realidad... También vienen por la izquierda.)",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50200502_35_dialog_content = "Qué... ¡¿Por qué no me lo dijiste antes?!",
  ui_story_5020_50200502_36_dialog_content = "(Porque podemos manejar las cosas de este lado).",
  ui_story_5020_50200502_37_dialog_content = "¡De nada!",
  ui_story_5020_50200502_38_dialog_content = "¿Por qué nos ayudas?",
  ui_story_5020_50200502_39_dialog_content = "El general no moverá un dedo contra ti mientras estés con la sacerdotisa.",
  ui_story_5020_50200502_40_dialog_content = "(Es una larga historia, pero no estamos exactamente en los mejores términos con el general en este momento...)",
  ui_story_5020_50200502_41_dialog_content = "¿Qué quieres decir?",
  ui_story_5020_50200502_42_dialog_content = "(Nos peleamos entre nosotros no hace mucho tiempo... Es difícil de explicar).",
  ui_story_5020_50200502_43_dialog_content = "(Después de escuchar su historia, me di cuenta de que la historia de Cloud Island es mucho más complicada de lo que pensaba).",
  ui_story_5020_50200502_44_dialog_content = "(Como extraños, no tenemos derecho a tomar una postura sobre sus problemas).",
  ui_story_5020_50200502_45_dialog_content = "(Pero luchar contra los fantasmas para proteger a los demás nunca es una mala elección).",
  ui_story_5020_50200502_46_dialog_content = "(¡Es por eso que, al menos por el momento, debemos trabajar juntos y derrotarlos!)",
  ui_story_5020_50200502_47_dialog_content = "...",
  ui_story_5020_50200502_48_dialog_content = "Está bien.",
  ui_story_5020_50200502_49_dialog_content = "Te aceptaré como un aliado en nuestra batalla, al menos por el momento.",
  ui_story_5020_50200502_50_dialog_content = "Rinne! ¿Estás bien?",
  ui_story_5020_50200502_51_dialog_content = "... Si, gracias.",
  ui_story_5020_50200502_52_dialog_content = "Estás lastimado, Rinne?",
  ui_story_5020_50200502_53_dialog_content = "Normalmente, ya habrías exorcizado a todos estos fantasmas.",
  ui_story_5020_50200502_54_dialog_content = "...",
  ui_story_5020_50200502_55_dialog_content = "Perdóname por preocuparte.",
  ui_story_5020_50200502_56_dialog_content = "Es que... no estoy en el estado mental adecuado.",
  ui_story_5020_50200502_57_dialog_content = "¿Es por la historia de ese tipo Wisp?",
  ui_story_5020_50200502_58_dialog_content = "...Sí.",
  ui_story_5020_50200502_59_dialog_content = "No puedo quitarme esa palabra de la cabeza... \"Rendimiento\"...",
  ui_story_5020_50200502_60_dialog_content = "Sigue atormentando mis pensamientos y soy incapaz de luchar con todo mi poder.",
  ui_story_5020_50200502_61_dialog_content = "Yo... siento como si hubiera perdido mi razón para luchar.",
  ui_story_5020_50200502_62_dialog_content = "Pero pensé que ya lo habías descubierto, después de nuestra pelea con el general en el castillo principal...",
  ui_story_5020_50200502_63_dialog_content = "Estaba enojado en ese momento. no entendía bien las cosas...",
  ui_story_5020_50200502_64_dialog_content = "Pero ahora, creo que entiendo.",
  ui_story_5020_50200502_65_dialog_content = "¿Entender qué?",
  ui_story_5020_50200502_66_dialog_content = "Desde el principio, nunca quiso que exorcizara fantasmas.",
  ui_story_5020_50200502_67_dialog_content = "En cambio, quería usarme... Para forzarme a vestirme de sacerdotisa, para que pudiera engañar a los civiles en el escenario que montó.",
  ui_story_5020_50200502_68_dialog_content = "Todos estos años estuve viviendo en mi papel, orgullosa de ser la sacerdotisa que podía disipar todo miedo.",
  ui_story_5020_50200502_69_dialog_content = "Pero ahora que ya no estoy actuando en el escenario, de repente escucho mi propia historia, a través de la boca de otros.",
  ui_story_5020_50200502_70_dialog_content = "Yo... ya no sé quién soy...",
  ui_story_5020_50200502_71_dialog_content = "¿Debería ser la persona que debo ser, o la persona que se suponía que debía ser...?",
  ui_story_5020_50200601_1_dialog_content = "¡Todos, vengan conmigo!",
  ui_story_5020_50200601_2_dialog_content = "¿Qué, nos vamos de nuevo? ¿Hacia dónde nos dirigimos esta vez?",
  ui_story_5020_50200601_3_dialog_content = "¡Nos estamos alejando cada vez más de Sakai!",
  ui_story_5020_50200601_4_dialog_content = "Eso es porque nos vamos de Koufu-jou por completo.",
  ui_story_5020_50200601_5_dialog_content = "¿Qué? ¡¿Por qué?!",
  ui_story_5020_50200601_6_dialog_content = "¿Cómo se supone que vamos a hacer negocios en medio de la nada?",
  ui_story_5020_50200601_7_dialog_content = "Los fantasmas están invadiendo la ciudad bajo sus órdenes. En este momento, cualquier lugar fuera de la ciudad es más seguro que dentro de ella.",
  ui_story_5020_50200601_8_dialog_content = "Oh...",
  ui_story_5020_50200601_9_dialog_content = "Momo... ¿Está diciendo que el general es el que convocó a los fantasmas?",
  ui_story_5020_50200601_10_dialog_content = "Creo que sí, Anzu. ¿Pero por qué?",
  ui_story_5020_50200601_11_dialog_content = "¿El general está tratando de... *Gulp* Matar a todos...?",
  ui_story_5020_50200601_12_dialog_content = "No lo creo... Él es el gobernante de Koufu-jou, después de todo.",
  ui_story_5020_50200601_13_dialog_content = "¿A quién gobernaría si matara a todos sus súbditos?",
  ui_story_5020_50200601_14_dialog_content = "Tal vez él... ¿quiere gobernar sobre fantasmas?",
  ui_story_5020_50200601_15_dialog_content = "¡N-No digas eso! ¡Usted me está volviendo loco!",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5020_50200601_17_dialog_content = "¡¿?!",
  ui_story_5020_50200601_18_dialog_content = "<size=45>¡Oigan ustedes! ¡Alto ahí!</size>",
  ui_story_5020_50200601_19_dialog_content = "!",
  ui_story_5020_50200601_20_dialog_content = "Maldito...",
  ui_story_5020_50200601_21_dialog_content = "Es la mitad de la noche. ¿A dónde crees que vas?",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>Los tejados sobre las calles de Koufu-jou</color>",
  ui_story_5020_50200601_21X2_dialog_content = "¡E-Es tan alto! ¡Reduzcan la velocidad, muchachos!",
  ui_story_5020_50200601_21X3_dialog_content = "Sólo un poco más. Los techos son la única salida rápida y segura en este momento.",
  ui_story_5020_50200601_22_dialog_content = "es un callejón sin salida, PlayerName!",
  ui_story_5020_50200601_23_dialog_content = "¿Qué debemos hacer?",
  ui_story_5020_50200601_24_dialog_content = "Parece que no tenemos elección...",
  ui_story_5020_50200601_25_dialog_content = "¿vamos a saltar?",
  ui_story_5020_50200601_26_dialog_content = "Sí...",
  ui_story_5020_50200601_27_dialog_content = "¡Maravilloso!",
  ui_story_5020_50200601_28_dialog_content = "¡Oye! ¡No saltes así!",
  ui_story_5020_50200601_29_dialog_content = "¿Ahora quién me va a ayudar...?",
  ui_story_5020_50200601_30_dialog_content = "Darse prisa, PlayerName!",
  ui_story_5020_50200601_31_dialog_content = "¡No podrás saltar si los fantasmas te atrapan!",
  ui_story_5020_50200601_32_dialog_content = "¡Yo sé eso!",
  ui_story_5020_50200601_33_dialog_content = "Uff.",
  ui_story_5020_50200601_34_dialog_content = "¡¡¡Aquí va!!!",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>¡Aaaaaahhh!</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5020_50200601_37_dialog_content = "Estoy... ¿Sigo vivo?",
  ui_story_5020_50200601_38_dialog_content = "Es imposible encontrar un lugar seguro para aterrizar con los ojos cerrados, ya sabes.",
  ui_story_5020_50200601_39_dialog_content = "¡Menos mal que estaba allí para atraparte!",
  ui_story_5020_50200601_40_dialog_content = "Usted es el mejor, Vice...",
  ui_story_5020_50200601_41_dialog_content = "Claro, pero... ¿Podrías valerte por ti mismo ahora?",
  ui_story_5020_50200601_42_dialog_content = "Oh, lo siento...",
  ui_story_5020_50200601_43_dialog_content = "Ahora bien.",
  ui_story_5020_50200601_44_dialog_content = "Nos encontramos de nuevo, forasteros.",
  ui_story_5020_50200601_45_dialog_content = "Entonces, ¿te has estado escondiendo en los tejados todo el tiempo?",
  ui_story_5020_50200601_46_dialog_content = "Mmm...",
  ui_story_5020_50200601_47_dialog_content = "Sé que es mejor si mantenemos cierta distancia el uno del otro...",
  ui_story_5020_50200601_48_dialog_content = "Pero no creo que podamos permitirnos el lujo de la distancia en este momento.",
  ui_story_5020_50200601_49_dialog_content = "¿Nos estás pidiendo que vayamos a tu rescate ahora?",
  ui_story_5020_50200601_50_dialog_content = "Este realmente no es el momento para tu actitud...",
  ui_story_5020_50200601_51_dialog_content = "No estoy tratando de causarte más problemas.",
  ui_story_5020_50200601_52_dialog_content = "Solo intento señalar que los fantasmas van a estar aquí muy pronto.",
  ui_story_5020_50200601_53_dialog_content = "Si usted y su gente están listos para renunciar, nos gustaría seguir funcionando.",
  ui_story_5020_50200601_54_dialog_content = "Y si todavía tienes ganas de luchar contra los fantasmas, también estaremos encantados de ayudarte.",
  ui_story_5020_50200601_55_dialog_content = "Tch, eres ingenioso, ¿verdad?",
  ui_story_5020_50200601_56_dialog_content = "Veamos si puedes caminar la charla en una pelea.",
  ui_story_5020_50200601_57_dialog_content = "¡Lo verás por ti mismo en un momento!",
  ui_story_5020_50200601_58_dialog_content = "Sin embargo, una última cosa. Mantén a esa mujer lejos de nosotros.",
  ui_story_5020_50200601_59_dialog_content = "No queremos luchar junto a la sacerdotisa. Ni ahora, ni nunca.",
  ui_story_5020_50200601_60_dialog_content = "...",
  ui_story_5020_50200601_61_dialog_content = "Eh... En realidad, Rinne es...",
  ui_story_5020_50200601_62_dialog_content = "Estoy bien con eso.",
  ui_story_5020_50200601_63_dialog_content = "Ya que usted y sus hombres están dispuestos a hacer frente a la situación.",
  ui_story_5020_50200601_64_dialog_content = "Estoy más que feliz de complacer.",
  ui_story_5020_50200601_65_dialog_content = "¡Tú!",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50200601_68_dialog_content = "Tch... Olvídalo.",
  ui_story_5020_50200601_69_dialog_content = "¡Jirón! ¡Prepárate para la batalla!",
  ui_story_5020_50200602_1_dialog_content = "¿Cuántos quedan?",
  ui_story_5020_50200602_2_dialog_content = "Casi ha terminado... Puedo sentir que la energía a nuestro alrededor se ha debilitado.",
  ui_story_5020_50200602_3_dialog_content = "¡Vice!",
  ui_story_5020_50200602_4_dialog_content = "¡Entendido!",
  ui_story_5020_50200602_5_dialog_content = "¿Aún puedes pelear?",
  ui_story_5020_50200602_6_dialog_content = "¿Con quién crees que estás hablando, chico?",
  ui_story_5020_50200602_7_dialog_content = "Solo preocúpate de ti por ahora.",
  ui_story_5020_50200602_8_dialog_content = "Puedo sentirlo... Tu cuerpo está al límite.",
  ui_story_5020_50200602_9_dialog_content = "Si eres tan intuitivo como crees que eres, sabrás que mi espíritu está ansioso por partir.",
  ui_story_5020_50200602_10_dialog_content = "Pero ¿de qué te servirá tu espíritu si tu cuerpo decae de cansancio?",
  ui_story_5020_50200602_11_dialog_content = "Fíjate bien, chico. Esas cosas con las que estamos luchando ni siquiera tienen cuerpo, ¡pero siguen viniendo hacia nosotros!",
  ui_story_5020_50200602_12_dialog_content = "Es porque todavía les queda un poco de su espíritu.",
  ui_story_5020_50200602_13_dialog_content = "Las personas aquí creemos que el espíritu es mucho más importante que el cuerpo físico.",
  ui_story_5020_50200602_14_dialog_content = "Podemos perder la batalla, e incluso nuestras vidas, pero nunca nos rendiremos.",
  ui_story_5020_50200602_15_dialog_content = "Esa es una convicción bastante aterradora que ustedes tienen...",
  ui_story_5020_50200602_16_dialog_content = "Pero no será necesario esta vez.",
  ui_story_5020_50200602_17_dialog_content = "Pronto terminará.",
  ui_story_5020_50200602_18_dialog_content = "Mmm...",
  ui_story_5020_50200602_19_dialog_content = "¡Este es el último!",
  ui_story_5020_50200602_20_dialog_content = "Uf... Estoy exhausto.",
  ui_story_5020_50200602_21_dialog_content = "¿Qué camino sigue, chico?",
  ui_story_5020_50200602_22_dialog_content = "Tenemos que darnos prisa y reunirnos con el resto de los civiles.",
  ui_story_5020_50200602_23_dialog_content = "Espera... ¡No bajes la guardia todavía!",
  ui_story_5020_50200602_24_dialog_content = "Un grupo de personas se acerca...",
  ui_story_5020_50200602_25_dialog_content = "¿Gente? ¿Que clase de gente?",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>Pisa, pisa, pisa...</color>",
  ui_story_5020_50200602_27_dialog_content = "Si no me equivoco, no creo que sean personas a las que te alegrará ver...",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>Pisa, pisa, pisa...</color>",
  ui_story_5020_50200602_29_dialog_content = "¡Escoria rebelde!",
  ui_story_5020_50200602_30_dialog_content = "¡Azote de todos los Koufu-jou!",
  ui_story_5020_50200602_31_dialog_content = "Hoy dia...",
  ui_story_5020_50200602_32_dialog_content = "<size=40>¡Libraremos a nuestra ciudad de tu presencia de una vez por todas!</size>",
  ui_story_5020_50200602_33_dialog_content = "¿Samurai? ¡¡Y muchos de ellos!!",
  ui_story_5020_50200602_34_dialog_content = "Hmph, a los perritos falderos del general les encanta correr en manada.",
  ui_story_5020_50200602_35_dialog_content = "Su ladrido siempre es mucho peor que su mordida.",
  ui_story_5020_50200602_36_dialog_content = "¡A las armas, hombres!",
  ui_story_5020_50200602_37_dialog_content = "¡Espera!",
  ui_story_5020_50200602_38_dialog_content = "Hay otros detrás de ellos...",
  ui_story_5020_50200602_39_dialog_content = "¿Otros?",
  ui_story_5020_50200602_40_dialog_content = "¡Guau! Vice! PlayerName!",
  ui_story_5020_50200602_41_dialog_content = "¿Están bien?",
  ui_story_5020_50200602_42_dialog_content = "¿Anzu? momo??",
  ui_story_5020_50200602_43_dialog_content = "¿No se supone que debes estar con los civiles?",
  ui_story_5020_50200602_44_dialog_content = "Papá...",
  ui_story_5020_50200602_45_dialog_content = "Cállate.",
  ui_story_5020_50200602_46_dialog_content = "¡Q-Qué despreciable!",
  ui_story_5020_50200602_47_dialog_content = "¡Cómo te atreves a capturar a civiles inocentes!",
  ui_story_5020_50200602_48_dialog_content = "¡Debería ser yo quien diga eso!",
  ui_story_5020_50200602_49_dialog_content = "¡Tú, escoria de Wisp, estabas planeando huir con nuestra gente del pueblo como rehenes!",
  ui_story_5020_50200602_50_dialog_content = "Esa es tu primera transgresión.",
  ui_story_5020_50200602_51_dialog_content = "¿Rehenes? ¡¿Estás loco?!",
  ui_story_5020_50200602_52_dialog_content = "¿Dónde estabas cuando las calles estaban repletas de fantasmas? ¡¿Y ahora crees que puedes jugar a los héroes?!",
  ui_story_5020_50200602_53_dialog_content = "Desobedecer al general y formar una facción rebelde en secreto...",
  ui_story_5020_50200602_54_dialog_content = "Esa es tu segunda transgresión.",
  ui_story_5020_50200602_55_dialog_content = "¡Por qué tú...!",
  ui_story_5020_50200602_56_dialog_content = "Y a pesar de tu intento fallido de derrocar el gobierno del general...",
  ui_story_5020_50200602_57_dialog_content = "Incursionaste en las artes prohibidas e invocaste fantasmas en la ciudad para sembrar la discordia.",
  ui_story_5020_50200602_58_dialog_content = "Esa es tu tercera transgresión.",
  ui_story_5020_50200602_59_dialog_content = "¡¿De qué estás hablando?!",
  ui_story_5020_50200602_60_dialog_content = "¡Los Wisps han estado luchando contra los fantasmas todo este tiempo!",
  ui_story_5020_50200602_61_dialog_content = "Mmm...",
  ui_story_5020_50200602_62_dialog_content = "Creo que está diciendo todo esto para que la gente del pueblo lo escuche.",
  ui_story_5020_50200602_63_dialog_content = "Maestro samurái, ¿es esto cierto?",
  ui_story_5020_50200602_64_dialog_content = "¿El Wisp realmente convocó a los fantasmas?",
  ui_story_5020_50200602_65_dialog_content = "Pero ellos son los que nos salvaron hace un momento...",
  ui_story_5020_50200602_66_dialog_content = "Claro, ¡pero quién sabe lo que realmente está sucediendo detrás de escena!",
  ui_story_5020_50200602_67_dialog_content = "Eso es cierto. Solo somos un grupo de civiles indefensos, qué sabríamos...",
  ui_story_5020_50200602_68_dialog_content = "Yo digo que solo confiemos en los que pueden protegernos mejor...",
  ui_story_5020_50200602_69_dialog_content = "...",
  ui_story_5020_50200602_70_dialog_content = "Pensé que se suponía que los samuráis debían cumplir con un código de honor...",
  ui_story_5020_50200602_71_dialog_content = "Pero parece que te di demasiado crédito.",
  ui_story_5020_50200602_72_dialog_content = "¿Honestamente pensaste que podrías torcer la verdad a tu favor tan fácilmente? ¿De verdad tomas al público por tonto?",
  ui_story_5020_50200602_73_dialog_content = "¡Tienen ojos! Hay testigos.",
  ui_story_5020_50200602_74_dialog_content = "Quien peleó a muerte contra los fantasmas...",
  ui_story_5020_50200602_75_dialog_content = "Y que se escondieron detrás de los muros de su castillo, encogiéndose de miedo... ¡La verdad es clara como el agua!",
  ui_story_5020_50200602_76_dialog_content = "Todo lo que han visto hoy es una manada de traidores que infringen la ley para servir a sus propios intereses.",
  ui_story_5020_50200602_77_dialog_content = "¡Escolta a los civiles de regreso al castillo principal! No podemos arriesgarnos a que se pierdan más vidas inocentes en la batalla que se avecina...",
  ui_story_5020_50200602_78_dialog_content = "Oh chico, otra pelea...",
  ui_story_5020_50200602_79_dialog_content = "Vamos, salgamos de aquí...",
  ui_story_5020_50200602_80_dialog_content = "Que pasa con el mundo...",
  ui_story_5020_50200602_81_dialog_content = "¡Oye! Tenemos dos amigos allí, ¡no les hagas daño!",
  ui_story_5020_50200602_82_dialog_content = "Vice! PlayerName! ¡Ven con nosotros, rápido...!",
  ui_story_5020_50200602_83_dialog_content = "Parece que la gente de Cloud Island está a punto de pelear entre ellos... ¿Qué debemos hacer?",
  ui_story_5020_50200602_84_dialog_content = "Espera... No creo que las cosas sean tan simples.",
  ui_story_5020_50200602_85_dialog_content = "Vamos a ver cómo van las cosas por ahora...",
  ui_story_5020_50200602_86_dialog_content = "Podemos estar de acuerdo en este punto, al menos. La vida de la gente del pueblo es lo primero.",
  ui_story_5020_50200602_87_dialog_content = "Naturalmente. Preservar la paz en Koufu-jou es nuestro deber, después de todo.",
  ui_story_5020_50200602_88_dialog_content = "¿En serio? Y aquí pensé que ese era el trabajo del Wisp todo este tiempo...",
  ui_story_5020_50200602_89_dialog_content = "Si está verdaderamente dedicado a preservar la paz, deponga las armas y acepte el castigo por sus crímenes.",
  ui_story_5020_50200602_90_dialog_content = "<size=45>Jajajajaja!</size>",
  ui_story_5020_50200602_91_dialog_content = "¡Las leyes del general no se aplican a mí!",
  ui_story_5020_50200602_92_dialog_content = "Terco hasta el final... Entonces prepárate para cosechar lo que has sembrado.",
  ui_story_5020_50200602_93_dialog_content = "¡Hmph! ¡No podría estar mas de acuerdo!",
  ui_story_5020_50200602_94_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50200602_95_dialog_content = "?!?",
  ui_story_5020_50200602_96_dialog_content = "!!!",
  ui_story_5020_50200602_97_dialog_content = "Siento interrumpir esta animada conversación...",
  ui_story_5020_50200602_98_dialog_content = "Pero tengo algunas preguntas que hacerte antes de que os destrozéis.",
  ui_story_5020_50200602_99_dialog_content = "¿Señora sacerdotisa?",
  ui_story_5020_50200602_100_dialog_content = "¡Así que también fuiste capturado por los rebeldes!",
  ui_story_5020_50200602_101_dialog_content = "Disculpe mi llegada tardía. Te juro que te rescataré a toda costa...",
  ui_story_5020_50200602_102_dialog_content = "Dices... que los fantasmas fueron convocados aquí por los Wisps, ¿sí?",
  ui_story_5020_50200602_103_dialog_content = "¿Dónde está tu evidencia?",
  ui_story_5020_50200602_104_dialog_content = "... ¿Evidencia?",
  ui_story_5020_50200602_105_dialog_content = "¿Cuándo convocaron a los fantasmas? ¿Donde? ¿Por qué método?",
  ui_story_5020_50200602_106_dialog_content = "...",
  ui_story_5020_50200602_107_dialog_content = "L-Lady Sacerdotisa, solo soy un humilde soldado. No estoy al tanto del conocimiento de mis superiores...",
  ui_story_5020_50200602_108_dialog_content = "Pero tranquilos, estas fueron las palabras del propio general.",
  ui_story_5020_50200602_109_dialog_content = "¿Oh?",
  ui_story_5020_50200602_110_dialog_content = "¿Y está seguro de que estas palabras salieron de la boca del general? ¿Que no son mentiras dichas por otra persona?",
  ui_story_5020_50200602_111_dialog_content = "Sí, mi señora. Esto lo puedo garantizar.",
  ui_story_5020_50200602_112_dialog_content = "...",
  ui_story_5020_50200602_113_dialog_content = "Ja... Ya veo.",
  ui_story_5020_50200602_114_dialog_content = "Déle las gracias al general, por mostrarme exactamente dónde estoy parado en todo esto.",
  ui_story_5020_50200602_115_dialog_content = "Gracias por su comprensión, Lady Sacerdotisa.",
  ui_story_5020_50200602_116_dialog_content = "Ahora, por favor, párate detrás de mí. No permitiré que nadie te haga daño en la escaramuza que se avecina.",
  ui_story_5020_50200602_117_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50200602_118_dialog_content = "Eso no será necesario.",
  ui_story_5020_50200602_119_dialog_content = "Aquí es precisamente donde pertenezco.",
  ui_story_5020_50200602_120_dialog_content = "...",
  ui_story_5020_50200602_121_dialog_content = "Lady Sacerdotisa... ¿Seguro que sabe lo que significa interponerse en nuestro camino?",
  ui_story_5020_50200602_122_dialog_content = "Yo no.",
  ui_story_5020_50200602_123_dialog_content = "Simplemente elijo no moverme. Lo que hagas y adónde vayas... no es de mi incumbencia.",
  ui_story_5020_50200602_124_dialog_content = "Si te paras en medio de nuestro campo de batalla, serás considerado nuestro enemigo.",
  ui_story_5020_50200602_125_dialog_content = "En otras palabras... Un enemigo del general.",
  ui_story_5020_50200602_126_dialog_content = "soy una sacerdotisa Nunca he considerado a nadie como mi enemigo.",
  ui_story_5020_50200602_127_dialog_content = "Pero tal vez haya quienes me conviertan en un enemigo.",
  ui_story_5020_50200602_128_dialog_content = "¿Estás insinuando que el general tiene la culpa de todo esto?",
  ui_story_5020_50200602_129_dialog_content = "Para nada. Finalmente lo veo por lo que es.",
  ui_story_5020_50200602_130_dialog_content = "Todo gracias a que entregaste su mensaje de que los Wisps fueron los responsables de convocar a los fantasmas aquí.",
  ui_story_5020_50200602_131_dialog_content = "...",
  ui_story_5020_50200602_132_dialog_content = "Cuando vi los fantasmas en el Pabellón de las Nubes, no entendí.",
  ui_story_5020_50200602_133_dialog_content = "Y cuando el Espejo de la Nube de algún modo devolvió la vida a los fantasmas, tampoco lo entendí.",
  ui_story_5020_50200602_134_dialog_content = "La contradicción entre las palabras del general y sus acciones me confundió... No pude entender nada de eso.",
  ui_story_5020_50200602_135_dialog_content = "Pero tú y tus hombres finalmente me habéis dado la respuesta que estaba buscando.",
  ui_story_5020_50200602_136_dialog_content = "Las sacerdotisas y los fantasmas se han visto como enemigos durante generaciones... Sin embargo, a los ojos del general, somos iguales.",
  ui_story_5020_50200602_137_dialog_content = "No somos diferentes, porque ambos somos solo armas para usar.",
  ui_story_5020_50200602_138_dialog_content = "Siempre que se requiere fuerza, utiliza los fantasmas para aplastar a sus enemigos.",
  ui_story_5020_50200602_139_dialog_content = "Y cada vez que necesita ganarse a la gente, envía a una sacerdotisa para luchar contra los mismos fantasmas que convoca.",
  ui_story_5020_50200602_140_dialog_content = "Creo que todavía hay mucho que no sabes, Lady Sacerdotisa.",
  ui_story_5020_50200602_141_dialog_content = "Tal vez... Y por eso, he elegido creer sólo lo que puedo entender.",
  ui_story_5020_50200602_142_dialog_content = "Que es lo que he aprendido todo este tiempo... Elijo confiar en mi deber como sacerdotisa.",
  ui_story_5020_50200602_143_dialog_content = "Fantasmas, son mis eternos enemigos.",
  ui_story_5020_50200602_144_dialog_content = "...",
  ui_story_5020_50200602_145_dialog_content = "Esta es también la razón por la que estoy parado donde estoy ahora.",
  ui_story_5020_50200602_146_dialog_content = "El samurái detrás de ti...",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>Ninguno de ellos está vivo.</color>, ¿son ellos?",
  ui_story_5020_50200602_148_dialog_content = "...",
  ui_story_5020_50200602_149_dialog_content = "Parece que el tiempo de las palabras ha pasado.",
  ui_story_5020_50200602_150_dialog_content = "...",
  ui_story_5020_50200602_151_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50200602_152_dialog_content = "\"Una oda a los muertos y a los vivos. May esta canción guía vuestras almas de vuelta a los lugares que les corresponden\".",
  ui_story_5020_50200701_1_dialog_content = "(Mientras observábamos al samurái fantasma acercarse, nuestros cuerpos se entumecieron por la pura presión).",
  ui_story_5020_50200701_2_dialog_content = "(Como una gran ola que se prepara para estrellarse contra nosotros).",
  ui_story_5020_50200701_3_dialog_content = "(Pero allí, en medio de la calle, estaba Rinne, solo y completamente ajeno a la ola que se avecina.)",
  ui_story_5020_50200701_4_dialog_content = "(Mirando fijamente a las entrañas del infierno, con el mundo de los vivos a sus espaldas.)",
  ui_story_5020_50200701_5_dialog_content = "Vaya...?",
  ui_story_5020_50200701_6_dialog_content = "¿Pensé que Wisp no tenía ningún deseo de luchar junto a una sacerdotisa?",
  ui_story_5020_50200701_7_dialog_content = "...",
  ui_story_5020_50200701_8_dialog_content = "Odiaríamos aún más si permitiéramos que nos protejas.",
  ui_story_5020_50200701_9_dialog_content = "jejeje que pena.",
  ui_story_5020_50200701_10_dialog_content = "Si todos ustedes están atrapados en la batalla, ¿quién más verá mi... actuación?",
  ui_story_5020_50200701_11_dialog_content = "Usando mis propias palabras en mi contra, ¿eh? No puedo decir que me guste mucho...",
  ui_story_5020_50200701_12_dialog_content = "Fuiste tú quien lo dijo primero.",
  ui_story_5020_50200701_13_dialog_content = "Seguro que sabes cómo guardar rencor... Eso, o mi discurso fue muy acertado.",
  ui_story_5020_50200701_14_dialog_content = "Mmm. Así es.",
  ui_story_5020_50200701_15_dialog_content = "Por ser un enemigo de las sacerdotisas, ciertamente pareces entenderlas incluso más que yo.",
  ui_story_5020_50200701_16_dialog_content = "Si supieras lo que yo sé... Definitivamente también te odiarías por serlo.",
  ui_story_5020_50200701_17_dialog_content = "Ah... No te apresures a juzgar.",
  ui_story_5020_50200701_18_dialog_content = "El rendimiento fue una forma dura de decirlo, pero no me importa particularmente.",
  ui_story_5020_50200701_19_dialog_content = "Entonces, ¿todavía estás dispuesto a ser un títere?",
  ui_story_5020_50200701_20_dialog_content = "Lo que te preocupa a ti ya tus hombres es solo quién está moviendo los hilos del títere.",
  ui_story_5020_50200701_21_dialog_content = "Yo, por otro lado, simplemente deseo dar un buen espectáculo.",
  ui_story_5020_50200701_22_dialog_content = "Ninguno de los títeres que vinieron antes que usted pudo lograr eso.",
  ui_story_5020_50200701_23_dialog_content = "¿Es eso así? Entonces, ¿crees que tendré éxito donde todos han fallado?",
  ui_story_5020_50200701_24_dialog_content = "...",
  ui_story_5020_50200701_25_dialog_content = "¿Es por eso que siempre has estado tan preocupado por asesinar a las sacerdotisas?",
  ui_story_5020_50200701_26_dialog_content = "Amemori Me causó muchos problemas, ¿sabes?",
  ui_story_5020_50200701_27_dialog_content = "Amén...",
  ui_story_5020_50200701_28_dialog_content = "Te dirigirás a ella como Amemori-sama, entendido? ¡Muestra algo de respeto!",
  ui_story_5020_50200701_29_dialog_content = "¿Oh?",
  ui_story_5020_50200701_30_dialog_content = "Pero Amemori siempre falla en sus intentos de asesinato... Pensé que finalmente se había rendido para salvarse de ser una desgracia.",
  ui_story_5020_50200701_31_dialog_content = "¡Por qué tú...!",
  ui_story_5020_50200701_32_dialog_content = "Qué es Amemori a Wisp?",
  ui_story_5020_50200701_33_dialog_content = "Amemori-sama es el discípulo de nuestro comandante.",
  ui_story_5020_50200701_34_dialog_content = "En los años posteriores al encarcelamiento de nuestro comandante, se convirtió en la líder no oficial de Wisp.",
  ui_story_5020_50200701_35_dialog_content = "Veo... Amemori Nunca fue mucho para conversar, así que no tenía ni idea.",
  ui_story_5020_50200701_36_dialog_content = "Tu comandante es conocido como la Espada del Inframundo, ¿correcto?",
  ui_story_5020_50200701_37_dialog_content = "¿Por qué? ¿La has visto?",
  ui_story_5020_50200701_38_dialog_content = "Por supuesto. Nosotros también tuvimos una batalla.",
  ui_story_5020_50200701_39_dialog_content = "Como alguien que podía luchar al mismo nivel que el general... Era terriblemente poderosa.",
  ui_story_5020_50200701_40_dialog_content = "Y para Amemori ocupar su lugar durante tantos años... Debe haber sido bastante difícil.",
  ui_story_5020_50200701_41_dialog_content = "Amemori-sama es muy parecida a la comandante, y ha cumplido con sus deberes admirablemente.",
  ui_story_5020_50200701_42_dialog_content = "En algunos casos... Incluso lo ha hecho mejor que el comandante.",
  ui_story_5020_50200701_43_dialog_content = "¿En serio?",
  ui_story_5020_50200701_44_dialog_content = "Debo decir que sus habilidades para asesinar sacerdotisas dejan mucho que desear.",
  ui_story_5020_50200701_45_dialog_content = "¿Significa eso que su comandante es aún peor en eso que Amemori?",
  ui_story_5020_50200701_46_dialog_content = "...",
  ui_story_5020_50200701_47_dialog_content = "Creo que sabes la respuesta a eso.",
  ui_story_5020_50200701_48_dialog_content = "Intenta recordar la razón por la que te convertiste en sacerdotisa en primer lugar.",
  ui_story_5020_50200701_49_dialog_content = "...",
  ui_story_5020_50200701_50_dialog_content = "Je... ya veo.",
  ui_story_5020_50200701_51_dialog_content = "¿No dirías que matar sacerdotisas es tu propia versión de una actuación?",
  ui_story_5020_50200701_52_dialog_content = "No nos compares contigo mismo.",
  ui_story_5020_50200701_53_dialog_content = "Pero estamos aquí, luchando juntos, ¿no?",
  ui_story_5020_50200701_54_dialog_content = "Usted y sus hombres son todos parte del acto ahora.",
  ui_story_5020_50200702_1_dialog_content = "¡Hay más samuráis fantasmas acercándose por detrás de nosotros!",
  ui_story_5020_50200702_2_dialog_content = "¡Están trayendo refuerzos!",
  ui_story_5020_50200702_3_dialog_content = "...Ya veo.",
  ui_story_5020_50200702_4_dialog_content = "¡No duraremos mucho más a este ritmo, señor!",
  ui_story_5020_50200702_5_dialog_content = "¿Cuáles son sus órdenes?",
  ui_story_5020_50200702_6_dialog_content = "...",
  ui_story_5020_50200702_7_dialog_content = "Me temo que esta no es una batalla que podamos ganar.",
  ui_story_5020_50200702_8_dialog_content = "Señor...",
  ui_story_5020_50200702_9_dialog_content = "Entonces, ¿es este realmente el final...?",
  ui_story_5020_50200702_10_dialog_content = "¡Incluso si lo es, no vamos a caer sin luchar!",
  ui_story_5020_50200702_11_dialog_content = "Nosotros... podemos ser capaces de ganar el <color=#FFB400>próxima pelea</color>.",
  ui_story_5020_50200702_12_dialog_content = "¿La próxima pelea?",
  ui_story_5020_50200702_13_dialog_content = "Pero si perdemos aquí y ahora, ¡no habrá ninguna próxima pelea!",
  ui_story_5020_50200702_14_dialog_content = "Quiero intentar algo que no hayamos hecho antes.",
  ui_story_5020_50200702_15_dialog_content = "¡Oye, forastero! ¡¡¡Ven aquí!!!",
  ui_story_5020_50200702_16_dialog_content = "N-No hay necesidad de gritar... Estoy parado justo a tu lado...",
  ui_story_5020_50200702_17_dialog_content = "Déjame preguntarte, ¿crees que tenemos alguna posibilidad de escapar de aquí?",
  ui_story_5020_50200702_18_dialog_content = "¿Escapar?",
  ui_story_5020_50200702_19_dialog_content = "Hay demasiados samuráis fantasmas... Nuestras posibilidades de escapar son escasas o nulas.",
  ui_story_5020_50200702_20_dialog_content = "¿Qué pasaría si el Wisp te cubriera por detrás? ¿Podrías escapar entonces?",
  ui_story_5020_50200702_21_dialog_content = "¿Ah?",
  ui_story_5020_50200702_22_dialog_content = "Escuchen. En este momento, ustedes dos forasteros deben salir de aquí y llevarse a la sacerdotisa con ustedes.",
  ui_story_5020_50200702_23_dialog_content = "Cubriremos tu huida, pero no podremos detenerlos para siempre.",
  ui_story_5020_50200702_24_dialog_content = "Necesitarás usar todo tu poder espeluznante para esto.",
  ui_story_5020_50200702_25_dialog_content = "¿Entender?",
  ui_story_5020_50200702_26_dialog_content = "Entiendo. es solo...",
  ui_story_5020_50200702_27_dialog_content = "¿Por qué estás haciendo esto?",
  ui_story_5020_50200702_28_dialog_content = "...",
  ui_story_5020_50200702_29_dialog_content = "Sacerdotisa, más personas deberían presenciar esta actuación tuya.",
  ui_story_5020_50200702_30_dialog_content = "...",
  ui_story_5020_50200702_31_dialog_content = "Tal como está, Wisp no es lo suficientemente fuerte como para enfrentarse al general.",
  ui_story_5020_50200702_32_dialog_content = "Pero con ustedes tres... Todavía podría haber esperanza.",
  ui_story_5020_50200702_33_dialog_content = "Dado que ya estamos peleando una batalla perdida, prefiero arriesgarme en lugar de esperar a que llegue el final.",
  ui_story_5020_50200702_34_dialog_content = "¡Mantengan la línea, hombres! ¡Muéstrales que no hay cuartel!",
  ui_story_5020_50200702_35_dialog_content = "Pero, ¿qué va a pasar contigo después de que escapemos?",
  ui_story_5020_50200702_36_dialog_content = "<size=45>¡Vete de aquí ya, chico!</size>",
  ui_story_5020_50200702_37_dialog_content = "...",
  ui_story_5020_50200702_38_dialog_content = "Vamos, PlayerName.",
  ui_story_5020_50200702_39_dialog_content = "Han hecho su elección.",
  ui_story_5020_50200702_40_dialog_content = "¡Nos debes una, chico! ¡No lo olvides nunca!",
  ui_story_5020_50200702_41_dialog_content = "Y lo pagarás.",
  ui_story_5020_50200702_42_dialog_content = "¡Wow!",
  ui_story_5020_50200702_43_dialog_content = "¡Es un tambor enorme!",
  ui_story_5020_50200702_44_dialog_content = "¡Es enorme!",
  ui_story_5020_50200702_45_dialog_content = "¿Para qué es, papá?",
  ui_story_5020_50200702_46_dialog_content = "Señala el comienzo del Festival Kasuga.",
  ui_story_5020_50200702_47_dialog_content = "Es lo suficientemente fuerte como para que toda la ciudad de Koufu-jou pueda escucharlo. Así es como todos saben que el Festival Kasuga ha comenzado oficialmente.",
  ui_story_5020_50200702_48_dialog_content = "¡Whoa!",
  ui_story_5020_50200702_49_dialog_content = "Entonces, ¿qué está haciendo aquí? ¿Y dónde está el baterista?",
  ui_story_5020_50200702_50_dialog_content = "Probablemente escondiéndose de los fantasmas, me imagino.",
  ui_story_5020_50200702_51_dialog_content = "Qué pena...",
  ui_story_5020_50200702_52_dialog_content = "Entonces, ¿puedo jugar con él ahora?",
  ui_story_5020_50200702_53_dialog_content = "No ahora, hijo. Tenemos que quedarnos con los demás.",
  ui_story_5020_50200702_54_dialog_content = "Si todavía está aquí mañana, te traeré aquí para jugar.",
  ui_story_5020_50200702_55_dialog_content = "¡Hola, Momo!",
  ui_story_5020_50200702_56_dialog_content = "Sí.",
  ui_story_5020_50200702_57_dialog_content = "Este tambor... Ya no tiene dueño, ¿verdad?",
  ui_story_5020_50200702_58_dialog_content = "¡Me parece así!",
  ui_story_5020_50200702_59_dialog_content = "Si lo lleváramos con nosotros...",
  ui_story_5020_50200702_60_dialog_content = "Y colócalo al lado de nuestro puesto...",
  ui_story_5020_50200702_61_dialog_content = "¡Podríamos generar aún más negocios para nosotros mismos!",
  ui_story_5020_50200702_62_dialog_content = "<size=40>¡Aprovecharlas!</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>¡Rápidamente!</size>",
  ui_story_5020_50200702_64_dialog_content = "¿Eh? ¿Qué ocurre?",
  ui_story_5020_50200702_65_dialog_content = "Se siente como...",
  ui_story_5020_50200702_66_dialog_content = "¡Alguien está corriendo hacia nosotros ahora mismo!",
  ui_story_5020_50200702_67_dialog_content = "Anzu! Momo! ¡Ayuda!",
  ui_story_5020_50200702_68_dialog_content = "Ay...",
  ui_story_5020_50200702_69_dialog_content = "Dios...",
  ui_story_5020_50200702_70_dialog_content = "Lo siento, no frené a tiempo.",
  ui_story_5020_50200702_71_dialog_content = "De todos modos, ¡estamos en un gran problema! ¡Un montón de samuráis están tratando de matarnos!",
  ui_story_5020_50200702_72_dialog_content = "¿Samurai? ¿Matarte?",
  ui_story_5020_50200702_73_dialog_content = "Qué has hecho, PlayerName?",
  ui_story_5020_50200702_74_dialog_content = "¡No hay tiempo para explicaciones! ¿Sabes dónde podemos escondernos por el momento?",
  ui_story_5020_50200702_75_dialog_content = "¡Apurarse! ¡Nos están ganando!",
  ui_story_5020_50200702_76_dialog_content = "¿Un escondite? ¡Todo esto es tan repentino!",
  ui_story_5020_50200702_77_dialog_content = "Bueno, ya que preguntas...",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>Mmm...</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName, moverse...",
  ui_story_5020_50200702_81_dialog_content = "Aquí no hay espacio...",
  ui_story_5020_50200702_82_dialog_content = "Me gustaría, pero... ¡aquí adentro es completamente redondo!",
  ui_story_5020_50200702_83_dialog_content = "¡Mi cuerpo sigue deslizándose hacia abajo!",
  ui_story_5020_50200702_84_dialog_content = "Suspiro... Es tan propio de ti sugerir un pésimo escondite como el interior de un tambor...",
  ui_story_5020_50200702_85_dialog_content = "¿Qué? ¡Esta fue idea de Anzu y Momo! ¡Yo no tuve nada que ver con eso!",
  ui_story_5020_50200702_86_dialog_content = "Je... Desafortunadamente, parece que esta fue nuestra mejor elección dadas nuestras circunstancias.",
  ui_story_5020_50200702_87_dialog_content = "Tendremos que aguantarlo por ahora.",
  ui_story_5020_50200702_88_dialog_content = "Mmm...",
  ui_story_5020_50200702_89_dialog_content = "Shh, están aquí.",
  ui_story_5020_50200702_90_dialog_content = "¡Tú allí! ¿Viste a tres personas de aspecto frenético correr por aquí hace un momento?",
  ui_story_5020_50200702_91_dialog_content = "Uno de ellos vestía el atuendo rojo de una sacerdotisa. No podrías haberla perdido.",
  ui_story_5020_50200702_92_dialog_content = "¿Eh? ¿Por qué específicamente tres personas?",
  ui_story_5020_50200702_93_dialog_content = "Vi a alguien con ropa azul. ¿Eso cuenta?",
  ui_story_5020_50200702_94_dialog_content = "... Solo dime si los has visto o no.",
  ui_story_5020_50200702_95_dialog_content = "¡No los he visto!",
  ui_story_5020_50200702_96_dialog_content = "Muy bien, lo tengo.",
  ui_story_5020_50200702_97_dialog_content = "(Vaya... Él lo compró...)",
  ui_story_5020_50200702_98_dialog_content = "Aunque... ¿Qué están haciendo ustedes dos aquí, de todos modos?",
  ui_story_5020_50200702_99_dialog_content = "¿Por qué no sigues a los demás?",
  ui_story_5020_50200702_100_dialog_content = "Ah, bueno... Ya ves... Uh...",
  ui_story_5020_50200702_101_dialog_content = "Es por este tambor aquí...",
  ui_story_5020_50200702_102_dialog_content = "¿Tambor?",
  ui_story_5020_50200702_103_dialog_content = "(!!!)",
  ui_story_5020_50200702_104_dialog_content = "¿Qué pasa con el tambor?",
  ui_story_5020_50200702_105_dialog_content = "(Estamos jodidos...)",
  ui_story_5020_50200702_106_dialog_content = "¡Sí! ¡Este tambor!",
  ui_story_5020_50200702_107_dialog_content = "¡Somos bateristas, ya ves!",
  ui_story_5020_50200702_108_dialog_content = "¡E-Eso es correcto! ¡Nos estamos preparando para anunciar el inicio del Festival Kasuga!",
  ui_story_5020_50200702_109_dialog_content = "¿Bateristas?",
  ui_story_5020_50200702_110_dialog_content = "Pero ustedes dos son tan pequeños... ¿De verdad están hechos para tocar la batería?",
  ui_story_5020_50200702_111_dialog_content = "Seremos pequeños, pero...",
  ui_story_5020_50200702_112_dialog_content = "¡Trabajamos juntos!",
  ui_story_5020_50200702_113_dialog_content = "¿Trabajar juntos?",
  ui_story_5020_50200702_114_dialog_content = "Suena interesante... ¿Por qué no nos das una pequeña demostración?",
  ui_story_5020_50200702_115_dialog_content = "¿De... De verdad...?",
  ui_story_5020_50200702_116_dialog_content = "¡M-Tal vez en otro momento, mi buen señor! Realmente deberíamos estar alcanzando a los demás...",
  ui_story_5020_50200702_117_dialog_content = "No hay nada de que preocuparse. Vienen más samuráis en camino, así que estamos perfectamente seguros aquí.",
  ui_story_5020_50200702_118_dialog_content = "Vamos entonces, veamos qué tan bien puedes tocar la batería.",
  ui_story_5020_50200702_119_dialog_content = "(...)",
  ui_story_5020_50200702_120_dialog_content = "(... ¿Anzu? ¿Momo? En realidad no vas a...)",
  ui_story_5020_50200702_121_dialog_content = "<size=30>Perdónanos, PlayerName...</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>Solo trata de soportarlo por ahora...</size>",
  ui_story_5020_50200702_123_dialog_content = "(¡E-Espera! Tiene que haber otro...)",
  ui_story_5020_50200702_124_dialog_content = "¡Oye!",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>¡¡¡zas!!!</size></color>",
  ui_story_5020_50200702_126_dialog_content = "¡Oye!",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>¡¡¡zas!!!</size></color>",
  ui_story_5020_50200702_128_dialog_content = "¡Ay! ¡Ustedes dos son prometedores, después de todo!",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>Jajaja...</anim>",
  ui_story_5020_50200702_130_dialog_content = "Es usted demasiado amable, señor...",
  ui_story_5020_50200702_131_dialog_content = "El general dijo que el Festival Kasuga debe continuar sin incidentes... Muy bien, ustedes dos. Lleva tu tambor al castillo principal para que puedas continuar con tus preparativos.",
  ui_story_5020_50200702_132_dialog_content = "Además, si ves a los tres que mencioné antes, solo avísanos.",
  ui_story_5020_50200702_133_dialog_content = "¡Maravilloso!",
  ui_story_5020_50200702_134_dialog_content = "Oh...",
  ui_story_5020_50200702_135_dialog_content = "PlayerName...",
  ui_story_5020_50200702_136_dialog_content = "¿Están bien los tres...?",
  ui_story_5020_50200702_137_dialog_content = "<size=45>¡¿Qué opinas?!</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>¡Nuestros tímpanos están casi reventados!</size>",
  ui_story_5020_50200702_139_dialog_content = "Tu audición parece estar bien...",
  ui_story_5020_50200702_140_dialog_content = "¡Estoy usando mis poderes! ¡Mis oídos están completamente disparados!",
  ui_story_5020_50200702_141_dialog_content = "¿Estás diciendo algo, PlayerName? Puedo ver tus labios moviéndose, pero...",
  ui_story_5020_50200702_142_dialog_content = "¡Lo lamentamos! ¡¡¡Lo sentimos mucho, de verdad, mucho!!!",
  ui_story_5020_50200702_143_dialog_content = "Uf...",
  ui_story_5020_50200702_144_dialog_content = "Olvídalo. No había otra opción.",
  ui_story_5020_50200702_145_dialog_content = "Shh!",
  ui_story_5020_50200702_146_dialog_content = "¡Vienen más samuráis!",
  ui_story_5020_50200702_147_dialog_content = "Simplemente nunca se detiene, ¿verdad?",
  ui_story_5020_50200702_148_dialog_content = "¿Qué hacemos ahora?",
  ui_story_5020_50200702_149_dialog_content = "¡Tendrás que seguir escondiéndote dentro del tambor!",
  ui_story_5020_50200702_150_dialog_content = "¡Anzu y yo te llevaremos a algún lugar con menos gente, para que tengas más posibilidades de escapar!",
  ui_story_5020_50200702_151_dialog_content = "Eso suena como una buena idea... creo.",
  ui_story_5020_50200702_152_dialog_content = "¡Así es!",
  ui_story_5020_50200702_153_dialog_content = "Siempre nos las arreglamos para encontrar una manera!",
  ui_story_5020_50200702_154_dialog_content = "Pero escucha...",
  ui_story_5020_50200702_155_dialog_content = "¡No más tambores! ¡Lo digo en serio!",
  ui_story_5020_50200702_156_dialog_content = "¡Entendido! ¡No más tambores!",
  ui_story_5020_50200702_157_dialog_content = "(¿Qué esperaba lograr Wisp al ayudarnos a escapar?)",
  ui_story_5020_50200702_158_dialog_content = "(Me pregunto cómo están aguantando...)",
  ui_story_5020_50200702_159_dialog_content = "¡Nos rendimos!",
  ui_story_5020_50200702_160_dialog_content = "... ¡Oye, córtalo ya! ¡Dije que nos rindiéramos!",
  ui_story_5020_50200702_161_dialog_content = "¡El general tenía razón todo el tiempo! ¡Finalmente vemos el error de nuestros caminos!",
  ui_story_5020_50200702_162_dialog_content = "¡Los Wisp son culpables! ¡Aceptamos nuestro castigo!",
  ui_story_5020_50200702_163_dialog_content = "...",
  ui_story_5020_50200702_164_dialog_content = "El gran samurái, como el perrito faldero del general... ¡No! ¡Me refiero a la hoja más afilada del general!",
  ui_story_5020_50200702_165_dialog_content = "Ahora manejarás las cosas de acuerdo a la ley... ¿Cierto?",
  ui_story_5020_50200702_166_dialog_content = "Dime, ¿por qué ayudaste a escapar a la sacerdotisa?",
  ui_story_5020_50200702_167_dialog_content = "¿Ayudarla? ¡Se escapó sola! No tuvimos nada que ver con eso.",
  ui_story_5020_50200702_168_dialog_content = "El enemigo de tu enemigo puede no ser tu amigo.",
  ui_story_5020_50200702_169_dialog_content = "El general es su padre adoptivo. No hay mucho que ella pueda hacer.",
  ui_story_5020_50200702_170_dialog_content = "¡Eso está bien para nosotros! ¡Ahora pongamos fin a esto, para que finalmente podamos disfrutar de un poco de paz!",
  ui_story_5020_50200702_171_dialog_content = "...",
  ui_story_5020_50200702_172_dialog_content = "Átalos y llévalos al castillo principal.",
  ui_story_5020_50200801_1_dialog_content = "Escoge una flor roja para la dama...",
  ui_story_5020_50200801_2_dialog_content = "Los pétalos caen como nieve sobre un trozo de jade.",
  ui_story_5020_50200801_3_dialog_content = "¿Qué vas a hacer ahora, maestro?",
  ui_story_5020_50200801_4_dialog_content = "¿Oh? Aún me sigues, ¿verdad?",
  ui_story_5020_50200801_5_dialog_content = "Me sorprende que te hayas mantenido al día todo este tiempo.",
  ui_story_5020_50200801_6_dialog_content = "Por favor, maestro. Deja que te ayude.",
  ui_story_5020_50200801_7_dialog_content = "¿Ayúdame? ¿Con que? No necesito ninguna ayuda.",
  ui_story_5020_50200801_8_dialog_content = "Sólo tengo un asunto personal que tratar.",
  ui_story_5020_50200801_9_dialog_content = "Iré a buscarte una vez que termine. Sé una buena niña.",
  ui_story_5020_50200801_10_dialog_content = "...",
  ui_story_5020_50200801_11_dialog_content = "Maestro... Cuando te fuiste solo, yo...",
  ui_story_5020_50200801_12_dialog_content = "Me prometí a mí mismo que no dejaría que volviera a suceder.",
  ui_story_5020_50200801_13_dialog_content = "He crecido mucho en tu ausencia, maestro. Puedo ayudarte a llevar tu carga.",
  ui_story_5020_50200801_14_dialog_content = "No solo yo... sino todo Wisp también.",
  ui_story_5020_50200801_15_dialog_content = "¿Cuántos años han pasado...?",
  ui_story_5020_50200801_16_dialog_content = "Diez años.",
  ui_story_5020_50200801_17_dialog_content = "¡¿Diez años?! ¡Jajaja! Realmente ha pasado un tiempo, ¿eh?",
  ui_story_5020_50200801_18_dialog_content = "Recuerdo cómo eras en ese entonces... más bajo que mi espada. Siempre me preocupaba que una brisa te llevara lejos.",
  ui_story_5020_50200801_19_dialog_content = "Ahora que eres mayor y más hábil, no puedo deshacerme de ti aunque quisiera.",
  ui_story_5020_50200801_20_dialog_content = "Maestría...",
  ui_story_5020_50200801_21_dialog_content = "Desafortunadamente, parece que esa cabecita tuya no se ha vuelto mucho más inteligente.",
  ui_story_5020_50200801_22_dialog_content = "\"Embarca mi carga\"... ¿Qué crees que significa exactamente?",
  ui_story_5020_50200801_23_dialog_content = "Para... Para ayudarte a lograr lo que siempre quisiste lograr.",
  ui_story_5020_50200801_24_dialog_content = "Para devolver Koufu-jou a su gobernante legítimo.",
  ui_story_5020_50200801_25_dialog_content = "Jajajaja! ¡Veo!",
  ui_story_5020_50200801_26_dialog_content = "¿Así que esa es la razón por la que viniste a rescatarme?",
  ui_story_5020_50200801_27_dialog_content = "Quieres que ponga fin a todo esto, ¿verdad?",
  ui_story_5020_50200801_28_dialog_content = "Con la esperanza de poder guiarte a ti y a los demás a una gloriosa batalla contra el general, empuñar mi espada y reclamar el castillo... ¿Es eso?",
  ui_story_5020_50200801_29_dialog_content = "W-Con su ayuda, maestro, nosotros...",
  ui_story_5020_50200801_30_dialog_content = "Suficiente.",
  ui_story_5020_50200801_31_dialog_content = "Tu visión de tu amo es demasiado poco realista, mi niña.",
  ui_story_5020_50200801_32_dialog_content = "No soy un santo... Lejos de eso, de hecho.",
  ui_story_5020_50200801_33_dialog_content = "No me encadenes con tus esperanzas y sueños y no me hagas representar tu idea de \"justicia\".",
  ui_story_5020_50200801_34_dialog_content = "...",
  ui_story_5020_50200801_35_dialog_content = "Pero maestro, todo lo que has hecho...",
  ui_story_5020_50200801_36_dialog_content = "Sí, me he estado oponiendo al general todo este tiempo.",
  ui_story_5020_50200801_37_dialog_content = "Pero la verdad es... que lo he estado haciendo todo por mí mismo. Ni por el pueblo, ni por la justicia, ni por las nobles razones que creas.",
  ui_story_5020_50200801_38_dialog_content = "Nunca podría llevar ese tipo de peso sobre mis hombros.",
  ui_story_5020_50200801_39_dialog_content = "...",
  ui_story_5020_50200801_40_dialog_content = "Honestamente, siempre pensé que no era digno de ser el comandante de Wisp.",
  ui_story_5020_50200801_41_dialog_content = "Cuando me eligieron para liderar, fue solo porque nadie más era más fuerte que yo.",
  ui_story_5020_50200801_42_dialog_content = "Pero esta responsabilidad no me ha dado más que dolores de cabeza y agotamiento.",
  ui_story_5020_50200801_43_dialog_content = "No... Creo que preferiría entrar en el castillo principal por mi cuenta.",
  ui_story_5020_50200801_44_dialog_content = "Ver a las fuerzas del castillo luchar para defenderse... Aunque ninguno de ellos podría esperar detenerme.",
  ui_story_5020_50200801_45_dialog_content = "Hacer lo que me plazca... Sí, eso es lo que debo hacer.",
  ui_story_5020_50200801_46_dialog_content = "¿Y tú, Amemori?",
  ui_story_5020_50200801_47_dialog_content = "¿Qué es exactamente lo que quiere hacer?",
  ui_story_5020_50200801_48_dialog_content = "Yo...",
  ui_story_5020_50200801_49_dialog_content = "Nunca lo había pensado, ¿eh?",
  ui_story_5020_50200801_50_dialog_content = "...",
  ui_story_5020_50200801_51_dialog_content = "Siempre quise ser como usted, maestro.",
  ui_story_5020_50200801_52_dialog_content = "¿Oh?",
  ui_story_5020_50200801_53_dialog_content = "Todos en Wisp me trataron como tu sucesor.",
  ui_story_5020_50200801_54_dialog_content = "He... estado haciendo lo que esperaban de mí todo este tiempo, tratando de llenar el espacio que dejaste atrás.",
  ui_story_5020_50200801_55_dialog_content = "Pero la responsabilidad es demasiado grande para mí... No importa cuánto lo intente, nunca podría tomar su lugar, maestro.",
  ui_story_5020_50200801_56_dialog_content = "...",
  ui_story_5020_50200801_57_dialog_content = "Por eso... cuando finalmente te liberaron de Sealed Ground, sentí una oleada de alivio.",
  ui_story_5020_50200801_58_dialog_content = "Pensé que finalmente había cumplido mi misión.",
  ui_story_5020_50200801_59_dialog_content = "Oh, mi niña tonta... Eres más que mi sustituto.",
  ui_story_5020_50200801_60_dialog_content = "Wisp no conocía nada más que problemas y derrotas bajo mi mando... Pero los guiaste durante los últimos diez años.",
  ui_story_5020_50200801_61_dialog_content = "Has hecho un trabajo mucho mejor de lo que yo podría esperar hacer yo mismo.",
  ui_story_5020_50200801_62_dialog_content = "C-Cómo puede ser eso...",
  ui_story_5020_50200801_63_dialog_content = "Tu próxima misión... es encontrar lo que quieres hacer por ti mismo.",
  ui_story_5020_50200801_64_dialog_content = "Que es algo que no puedo enseñarte.",
  ui_story_5020_50200801_65_dialog_content = "...",
  ui_story_5020_50200801_66_dialog_content = "Bien ahora. No te quedes ahí como un tonto. Eres mi discípulo, después de todo.",
  ui_story_5020_50200801_67_dialog_content = "Ve y ocúpate de tus propios asuntos.",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_69_dialog_content = "...",
  ui_story_5020_50200801_70_dialog_content = "¿Por qué todavía me sigues?",
  ui_story_5020_50200801_71_dialog_content = "Todavía no he decidido qué es lo que quiero hacer... Así que he decidido seguirte por ahora, maestro.",
  ui_story_5020_50200801_72_dialog_content = "¡Por qué tú...!",
  ui_story_5020_50200801_73_dialog_content = "*Suspiro* ... Está bien. Vamos, entonces.",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_75_dialog_content = "Escoge una flor roja para la dama...",
  ui_story_5020_50200801_76_dialog_content = "Pétalos...",
  ui_story_5020_50200801_77_dialog_content = "Los pétalos caen como nieve sobre un trozo de jade.",
  ui_story_5020_50200801_78_dialog_content = "...",
  ui_story_5020_50200801_79_dialog_content = "Acabo de recordar... Siempre has tenido una bonita voz para cantar, desde que eras pequeña.",
  ui_story_5020_50200801_80_dialog_content = "Y parece haber mejorado con los años.",
  ui_story_5020_50200801_81_dialog_content = "G-Gracias, maestro.",
  ui_story_5020_50200801_82_dialog_content = "En cuanto a la otra… ni siquiera podía recordar la letra de esa canción, y mucho menos cantarla bien.",
  ui_story_5020_50200801_83_dialog_content = "... Ella ha olvidado mucho más desde entonces.",
  ui_story_5020_50200801_84_dialog_content = "Lo sabía. Después de todo, siempre fue mejor aprendiendo con los puños. Cuando se trataba de pelear, ella era un genio por derecho propio.",
  ui_story_5020_50200801_85_dialog_content = "Nunca pudiste vencerla de niña... Pero, ¿y ahora?",
  ui_story_5020_50200801_86_dialog_content = "...",
  ui_story_5020_50200801_87_dialog_content = "Bueno, ya que insistes en seguirme, tengo un trabajo para ti.",
  ui_story_5020_50200801_88_dialog_content = "Ayúdame a tirar de esta cuerda.",
  ui_story_5020_50200801_89_dialog_content = "P-Pero maestro, esto es de otra persona...",
  ui_story_5020_50200801_90_dialog_content = "¡Yo sé eso! ¡Solo lo estoy tomando prestado por un tiempo, no es como si me lo fuera a quedar para siempre!",
  ui_story_5020_50200801_91_dialog_content = "¡Vamos, juntos ahora!",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>¡Chasquido... golpe!</color>",
  ui_story_5020_50200801_93_dialog_content = "Perfecto, ahora ayúdame a llevar este manojo de cuerdas.",
  ui_story_5020_50200801_94_dialog_content = "... Entendido.",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_96_dialog_content = "Por cierto...",
  ui_story_5020_50200801_97_dialog_content = "Después de que desaparezca...",
  ui_story_5020_50200801_98_dialog_content = "¿El general tuvo un funeral?",
  ui_story_5020_50200801_99_dialog_content = "¿Un funeral?",
  ui_story_5020_50200801_100_dialog_content = "no lo creo...",
  ui_story_5020_50200801_101_dialog_content = "Oh ya veo.",
  ui_story_5020_50200801_102_dialog_content = "¿Para quién habría sido este funeral, amo?",
  ui_story_5020_50200801_103_dialog_content = "...",
  ui_story_5020_50200801_104_dialog_content = "Su nombre era Tsuki. ¿Todavía la recuerdas?",
  ui_story_5020_50200801_105_dialog_content = "Ella fue quien los dejó a ustedes dos conmigo hace tantos años.",
  ui_story_5020_50200801_106_dialog_content = "Sí, lo recuerdo.",
  ui_story_5020_50200801_107_dialog_content = "Creo que era su hermana mayor... ¿No es así, amo?",
  ui_story_5020_50200801_108_dialog_content = "Ella nos cuidó cuando éramos muy pequeños.",
  ui_story_5020_50200801_109_dialog_content = "Recuerdo que era una persona amable y cariñosa.",
  ui_story_5020_50200801_110_dialog_content = "Sí... seguro que lo era.",
  ui_story_5020_50200801_111_dialog_content = "¿Cómo falleció?",
  ui_story_5020_50200801_112_dialog_content = "...",
  ui_story_5020_50200801_113_dialog_content = "La maté.",
  ui_story_5020_50200801_114_dialog_content = "!",
  ui_story_5020_50200801_115_dialog_content = "Porque ella era una sacerdotisa.",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_118_dialog_content = "Desde el principio, seguí diciéndole que no se convirtiera en sacerdotisa.",
  ui_story_5020_50200801_119_dialog_content = "Pero Tsuki nunca me escuchó. Era mayor y siempre pensó que era más inteligente que su hermana menor.",
  ui_story_5020_50200801_120_dialog_content = "Ella dijo que una sacerdotisa podría traer paz a toda la Isla de las Nubes.",
  ui_story_5020_50200801_121_dialog_content = "Pero siempre me reía de ella, diciendo que las sacerdotisas eran solo herramientas para el general... Que la única forma de traer la paz a Cloud Island era con espadas.",
  ui_story_5020_50200801_122_dialog_content = "Al final, ninguno de los dos pudo convencer al otro, por lo que elegimos caminos diferentes que cada uno creía que eran los correctos.",
  ui_story_5020_50200801_123_dialog_content = "Ella fue a la isla principal para someterse a un entrenamiento formal, y yo... deambulé, matando innumerables fantasmas para perfeccionar mis habilidades.",
  ui_story_5020_50200801_124_dialog_content = "Unos años más tarde, ella se convirtió en la sacerdotisa del general y yo me convertí en la Espada del Inframundo.",
  ui_story_5020_50200801_125_dialog_content = "...",
  ui_story_5020_50200801_126_dialog_content = "La próxima vez que nos vimos, ella no perdió el tiempo recordando el pasado. Todo lo que dijo fue que quería ver quién era mejor matando fantasmas.",
  ui_story_5020_50200801_127_dialog_content = "Apenas pude contener la risa y acepté con gusto su desafío.",
  ui_story_5020_50200801_128_dialog_content = "Lo último que esperaba era verla sacar su espada con confianza.",
  ui_story_5020_50200801_129_dialog_content = "Era la espada más hermosa que jamás había visto. Exudaba un poder que quemaba como el sol... Como si estuviera hecho para atravesar demonios y oscuridad por igual.",
  ui_story_5020_50200801_130_dialog_content = "No hace falta decir que perdí espectacularmente. Je... Recuerdo que Tsuki estaba tan orgulloso de ganar. Ella bailaba a mi alrededor y decía:",
  ui_story_5020_50200801_131_dialog_content = "\"¡Te lo dije, una sacerdotisa puede traer la paz a la Isla de las Nubes!\"",
  ui_story_5020_50200801_132_dialog_content = "En aquel entonces... realmente creía que ella podría hacerlo.",
  ui_story_5020_50200801_133_dialog_content = "Increíble... Alguien fue capaz de derrotarte incluso a ti, maestro...",
  ui_story_5020_50200801_134_dialog_content = "¡Si no fuera por esa espada, ella nunca podría vencerme!",
  ui_story_5020_50200801_135_dialog_content = "Slice of Heaven, la espada que mata fantasmas... Incluso un niño de tres años puede atravesar la mayoría de los fantasmas con esa espada en la mano, y mucho menos mi hermana.",
  ui_story_5020_50200801_136_dialog_content = "Desafortunadamente, esa fue la última vez que puse mis ojos en el Slice of Heaven.",
  ui_story_5020_50200801_137_dialog_content = "Después de eso, su enfoque cambió de expulsar fantasmas. Simplemente se convirtió en un medio para un fin.",
  ui_story_5020_50200801_138_dialog_content = "...",
  ui_story_5020_50200801_139_dialog_content = "Empezó a usar el Cloud Mirror para que pareciera que estaba expulsando a los fantasmas.",
  ui_story_5020_50200801_140_dialog_content = "Pero yo sabía que todo era sólo un acto.",
  ui_story_5020_50200801_141_dialog_content = "Hace diez años, durante el Festival Kasuga... Ella usó el Espejo de la Nube para invocar fantasmas, solo para dejarlos frente a la gente. Tsuki realmente parecía disfrutar de su pequeña actuación.",
  ui_story_5020_50200801_142_dialog_content = "Vi a través de él... Desafortunadamente, nadie más logró hacer lo mismo. Todos cayeron en su acto.",
  ui_story_5020_50200801_143_dialog_content = "Todos creían que la sacerdotisa traería la paz a Koufu-jou, y que el general que la entrenó era digno de gobernarnos a todos.",
  ui_story_5020_50200801_144_dialog_content = "En ese momento, me di cuenta de que nuestro mayor obstáculo para realizar nuestros sueños de paz... era el uno al otro.",
  ui_story_5020_50200801_145_dialog_content = "Los miembros de Wisp comenzaron a bajar la guardia, y algunos incluso perdieron la voluntad de resistir por completo. Eligieron convertirse en súbditos dóciles y obedientes del general.",
  ui_story_5020_50200801_146_dialog_content = "Comparado con la represión forzosa... Este era un destino mucho más aterrador.",
  ui_story_5020_50200801_147_dialog_content = "¿Por qué?",
  ui_story_5020_50200801_148_dialog_content = "Si el general matara a diez de los nuestros, sus hijos heredarían su odio hacia él y mantendrían la resistencia en el futuro.",
  ui_story_5020_50200801_149_dialog_content = "Pero después de ser engañados por la sacerdotisa, se olvidaron por completo de su odio y de lo que era suyo por derecho... Y así, se convirtieron en el ganado domesticado del general.",
  ui_story_5020_50200801_150_dialog_content = "Wisp no le teme a la derrota. Realmente nunca ganamos ninguna batalla, pero tampoco perdemos la voluntad de resistir.",
  ui_story_5020_50200801_151_dialog_content = "Lo que más tememos es la complacencia... la asimilación... y un cambio de corazón.",
  ui_story_5020_50200801_152_dialog_content = "Poco a poco, estas cosas le quitan la razón a un guerrero para luchar.",
  ui_story_5020_50200801_153_dialog_content = "Y cuando eso suceda, nadie recordará quiénes éramos, o lo que logramos...",
  ui_story_5020_50200801_154_dialog_content = "Esta isla aún puede ser conocida como Isla Nube, pero perdió toda apariencia de lo que alguna vez fue hace mucho tiempo.",
  ui_story_5020_50200801_155_dialog_content = "...",
  ui_story_5020_50200801_156_dialog_content = "Y esa... es la razón por la que les digo a todos, incluyéndote a ti, que la sacerdotisa debe morir.",
  ui_story_5020_50200801_157_dialog_content = "El general nunca podrá derrotarnos de verdad, pero la sacerdotisa es una historia diferente.",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_159_dialog_content = "Muy bien... aquí está.",
  ui_story_5020_50200801_160_dialog_content = "Échame una mano. Solo toma todos los <color=#FFB400>vino</color> aquí",
  ui_story_5020_50200801_161_dialog_content = "Ata todas las botellas con esa cuerda...",
  ui_story_5020_50200801_162_dialog_content = "... Pero maestro, esto es definitivamente...",
  ui_story_5020_50200801_163_dialog_content = "Oh, dale un descanso, ¿quieres? ¡Conozco al dueño de esta tienda! ¡Retrocedemos años y años!",
  ui_story_5020_50200801_164_dialog_content = "Dejé una nota en la mesa diciendo que les pagaremos más tarde.",
  ui_story_5020_50200801_165_dialog_content = "Ahora pongámonos en movimiento.",
  ui_story_5020_50200801_166_dialog_content = "...",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>Mmm...</color>",
  ui_story_5020_50200801_168_dialog_content = "Uf...",
  ui_story_5020_50200801_169_dialog_content = "¡Deberias hacer eso! ¡Agradable y apretado!",
  ui_story_5020_50200801_170_dialog_content = "Ahora recógelos a todos y sígueme.",
  ui_story_5020_50200801_171_dialog_content = "Avísame si son demasiado pesados para ti. Puedo ayudarte a llevarlos.",
  ui_story_5020_50200801_172_dialog_content = "Yo... puedo manejarlo.",
  ui_story_5020_50200801_173_dialog_content = "¿Estás seguro? Solo se va a poner más difícil de ahora en adelante.",
  ui_story_5020_50200801_174_dialog_content = "¿A dónde vamos?",
  ui_story_5020_50200801_175_dialog_content = "Al <color=#FFB400>castillo principal</color>.",
  ui_story_5020_50200801_176_dialog_content = "¿El castillo principal?",
  ui_story_5020_50200801_177_dialog_content = "Sí.",
  ui_story_5020_50200801_178_dialog_content = "¿Has estado alguna vez en el techo del castillo? La vista es increíble... Un lugar perfecto para sentarse a tomar una copa.",
  ui_story_5020_50200801_179_dialog_content = "Asaltar un castillo no debería ser un gran problema para mi querido discípulo, ¿verdad?",
  ui_story_5020_50200801_180_dialog_content = "Seguro...",
  ui_story_5020_50200801_181_dialog_content = "A cualquier lugar al que mi maestro pueda ir, yo también puedo ir.",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_183_dialog_content = "Aquí de nuevo, ¿eh?",
  ui_story_5020_50200801_184_dialog_content = "Hace diez años, caminé por este mismo camino y vi cómo el castillo se hacía más y más grande a medida que me acercaba.",
  ui_story_5020_50200801_185_dialog_content = "Es tan alto que cubre el sol y la luna, y hace que la gente se pregunte si podrían encontrar la salida una vez que ponen un pie en él.",
  ui_story_5020_50200801_186_dialog_content = "Pero nunca quisiste encontrar la salida en ese entonces, ¿verdad?",
  ui_story_5020_50200801_187_dialog_content = "Incluso nos dejaste con la Rebelión y el jade Ryojin.",
  ui_story_5020_50200801_188_dialog_content = "Je... Tienes toda la razón.",
  ui_story_5020_50200801_189_dialog_content = "La Rebelión y el jade de Ryojin son demasiado valiosos como para correr el riesgo de caer en manos del general.",
  ui_story_5020_50200801_190_dialog_content = "A pesar de que conocías los riesgos... ¿Todavía elegiste matarla?",
  ui_story_5020_50200801_191_dialog_content = "Tu propia hermana...",
  ui_story_5020_50200801_192_dialog_content = "Así es... Mi propia hermana.",
  ui_story_5020_50200801_193_dialog_content = "Creo que ambos sabíamos que iba a suceder ese día.",
  ui_story_5020_50200801_194_dialog_content = "Yo estaba preparado para morir, y ella estaba lista para morir por mi mano.",
  ui_story_5020_50200801_195_dialog_content = "Pensé que ambos encontraríamos nuestro fin en el Pabellón de las Nubes ese día, muriendo ambos por nuestra búsqueda de la paz para la Isla de las Nubes.",
  ui_story_5020_50200801_196_dialog_content = "Pero inesperadamente...",
  ui_story_5020_50200801_197_dialog_content = "Ella no quería que yo muriera...",
  ui_story_5020_50200801_198_dialog_content = "Y yo ya no quería morir tampoco.",
  ui_story_5020_50200801_199_dialog_content = "¡¿?!",
  ui_story_5020_50200801_200_dialog_content = "Hay una persona más que debo llevar conmigo.",
  ui_story_5020_50200801_201_dialog_content = "...",
  ui_story_5020_50200801_202_dialog_content = "¿Es... General Fujikumo?",
  ui_story_5020_50200801_203_dialog_content = "Por supuesto que es. ¿Quién más podría ser?",
  ui_story_5020_50200801_204_dialog_content = "El día que murió Tsuki, finalmente me di cuenta de lo que la había hecho cambiar tanto.",
  ui_story_5020_50200801_205_dialog_content = "Ella puso su fe en una persona y confió en ella hasta su último aliento.",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_207_dialog_content = "Quería creer que había perdido la cabeza o se vio obligada a cumplir con sus deberes...",
  ui_story_5020_50200801_208_dialog_content = "Pero... estaba perfectamente cuerda y dispuesta a dejar que Fujikumo la engañara.",
  ui_story_5020_50200801_209_dialog_content = "Aunque sabía que sus acciones estaban mal, siguió creyendo en él y en sus mentiras.",
  ui_story_5020_50200801_210_dialog_content = "Una persona... había tomado como rehén el sentido del bien y del mal de mi hermana.",
  ui_story_5020_50200801_211_dialog_content = "Odio eso.",
  ui_story_5020_50200801_212_dialog_content = "Odio que Fujikumo se haya aprovechado del amor de Tsuki.",
  ui_story_5020_50200801_213_dialog_content = "Creo que lo mencioné antes. Siempre hago lo que quiero.",
  ui_story_5020_50200801_214_dialog_content = "Entre él y yo, al menos uno de nosotros muriendo.",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_216_dialog_content = "Ya estamos acá.",
  ui_story_5020_50200801_217_dialog_content = "Deberías ser bastante bueno escalando ahora, ¿verdad?",
  ui_story_5020_50200801_218_dialog_content = "Sí.",
  ui_story_5020_50200801_219_dialog_content = "¡Bien! ¡A ver quién llega primero a la cima!",
  ui_story_5020_50200801_220_dialog_content = "... Todavía estoy cargando con todo este alcohol, maestro.",
  ui_story_5020_50200801_221_dialog_content = "¡Sólo estaba bromeando! Realmente no tienes ganas de competir con tu maestro en este momento, ¿verdad?",
  ui_story_5020_50200801_222_dialog_content = "...",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>Pozo... Pat... Pozo... Pat...</color>",
  ui_story_5020_50200801_224_dialog_content = "Maestro... ¿Alguna vez te has arrepentido de haber matado a Tsuki?",
  ui_story_5020_50200801_225_dialog_content = "Por supuesto que no. No tengo excusas.",
  ui_story_5020_50200801_226_dialog_content = "Entonces, ¿por qué preguntaste sobre su funeral?",
  ui_story_5020_50200801_227_dialog_content = "...",
  ui_story_5020_50200801_228_dialog_content = "No me arrepiento de haberla matado, pero...",
  ui_story_5020_50200801_229_dialog_content = "Ella era mi hermana, después de todo. Debería haber sido yo quien la enterrara.",
  ui_story_5020_50200801_230_dialog_content = "Entiendo...",
  ui_story_5020_50200801_231_dialog_content = "Y, hay una cosa más.",
  ui_story_5020_50200801_232_dialog_content = "Slice of Heaven le pertenecía. Entonces, si tuviera que adivinar, probablemente fue enterrado con ella.",
  ui_story_5020_50200801_233_dialog_content = "Después de todo, fue hecho para matar fantasmas. El general no tiene necesidad de algo así.",
  ui_story_5020_50200801_234_dialog_content = "¿Desea encontrar el Trozo de cielo, maestro?",
  ui_story_5020_50200801_235_dialog_content = "Es correcto.",
  ui_story_5020_50200801_236_dialog_content = "Tsuki estaría revolcándose en su tumba si supiera que su preciosa espada se oxidó bajo un montón de tierra.",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>Hoyo... Pat...</color>",
  ui_story_5020_50200801_238_dialog_content = "¡Uf! ¡Han pasado años desde la última vez que subí aquí!",
  ui_story_5020_50200801_239_dialog_content = "Muy bien, mi niña, desata esas botellas y pásame una.",
  ui_story_5020_50200801_240_dialog_content = "Veamos si la bebida de mi viejo amigo ha mejorado en la última década.",
  ui_story_5020_50200801_241_dialog_content = "Si...",
  ui_story_5020_50200801_242_dialog_content = "Di... ¿Ya tienes la edad suficiente para beber?",
  ui_story_5020_50200801_243_dialog_content = "Yo... no puedo contener mi licor.",
  ui_story_5020_50200801_244_dialog_content = "Que aburrido.",
  ui_story_5020_50200801_245_dialog_content = "Ah, olvídalo. Sólo dame una de esas botellas, y <color=#FFB400>aplastar</color> el resto.",
  ui_story_5020_50200801_246_dialog_content = "¿Aplastarlos? Pero por qué...?",
  ui_story_5020_50200801_247_dialog_content = "¿Me estás cuestionando? ¡Si te digo que rompas esas botellas, las rompes de inmediato! ¿Lo tengo?",
  ui_story_5020_50200801_248_dialog_content = "... Entendido.",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>¡¡Grieta!!</color>",
  ui_story_5020_50200801_252_dialog_content = "Jajajajaja! ¡Así!",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>Glug... Glug...</anim>",
  ui_story_5020_50200801_254_dialog_content = "Fuaaaahh! ¡Eso es lo bueno!",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>Pozo... Pat... Pozo... Pat...</color>",
  ui_story_5020_50200801_256_dialog_content = "Por favor, trate de no caerse, maestro.",
  ui_story_5020_50200801_257_dialog_content = "¡Ja! ¿Con quién crees que estás hablando, eh?",
  ui_story_5020_50200801_258_dialog_content = "Ahora mira hacia abajo, Amemori.",
  ui_story_5020_50200801_259_dialog_content = "¿Ves a ese hombre caminando por allí? Dime, ¿quién podría ser?",
  ui_story_5020_50200801_260_dialog_content = "...",
  ui_story_5020_50200801_261_dialog_content = "Es Fujikumo.",
  ui_story_5020_50200801_262_dialog_content = "¿Qué está haciendo?",
  ui_story_5020_50200801_263_dialog_content = "Te voy a decir algo. Los enemigos se entienden mejor.",
  ui_story_5020_50200801_264_dialog_content = "Incluso desde esta distancia, en el techo de un edificio completamente diferente... Todavía puedo entender lo que está pasando por su mente en este momento.",
  ui_story_5020_50200801_265_dialog_content = "En este momento, debe estar pensando que está avanzando hacia la paz.",
  ui_story_5020_50200801_266_dialog_content = "¿Por qué?",
  ui_story_5020_50200801_267_dialog_content = "Porque eso es exactamente lo que estaría pensando.",
  ui_story_5020_50200801_268_dialog_content = "!!!",
  ui_story_5020_50200801_269_dialog_content = "Pero maestro...",
  ui_story_5020_50200801_270_dialog_content = "¡Vamos! ¡Beber solo no es divertido!",
  ui_story_5020_50200801_271_dialog_content = "Si mi propio alumno no bebe conmigo, ¡tendré que pedírselo a todos los Koufu-jou!",
  ui_story_5020_50200901_1_dialog_content = "¡General! Las fuerzas principales de Wisp han sido capturadas. Están en camino al castillo mientras hablamos.",
  ui_story_5020_50200901_2_dialog_content = "Seguro.",
  ui_story_5020_50200901_3_dialog_content = "Hoy, la bandera de la rebelión será reducida a cenizas.",
  ui_story_5020_50200901_4_dialog_content = "¡Avísale a la gente! ¡Dígales que vengan al castillo y sean testigos de cómo se hace justicia contra los traidores!",
  ui_story_5020_50200901_5_dialog_content = "Después de una noche de inquietud, alguien debe rendir cuentas por el caos que amenazó a nuestra bella ciudad.",
  ui_story_5020_50200901_6_dialog_content = "Todavía tenemos el Festival Kasuga al amanecer.",
  ui_story_5020_50200901_7_dialog_content = "¡Sí señor!",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50200901_9_dialog_content = "¡Oye! ¿Realmente vamos a algún lugar con menos gente?",
  ui_story_5020_50200901_10_dialog_content = "¿Por qué parece que las cosas se están poniendo cada vez más agitadas aquí?",
  ui_story_5020_50200901_11_dialog_content = "No se puede evitar PlayerName.",
  ui_story_5020_50200901_12_dialog_content = "Empujar ese enorme tambor habría sido demasiado llamativo. Nuestra mejor apuesta es escondernos entre la multitud y seguirlos.",
  ui_story_5020_50200901_13_dialog_content = "Muy bien, entonces... ¿Dónde estamos exactamente ahora?",
  ui_story_5020_50200901_14_dialog_content = "Deberíamos ser...",
  ui_story_5020_50200901_15_dialog_content = "Justo fuera del castillo.",
  ui_story_5020_50200901_16_dialog_content = "¡¿Qué?! ¡¿Estás tratando de llevarnos a nuestra muerte?!",
  ui_story_5020_50200901_17_dialog_content = "¡No te preocupes, ya encontraremos algo!",
  ui_story_5020_50200901_18_dialog_content = "En el peor de los casos, tendrás que esconderte hasta el final del Festival Kasuga...",
  ui_story_5020_50200901_19_dialog_content = "Realmente estás tratando de hacer que nos maten, ¿no es así?",
  ui_story_5020_50200901_20_dialog_content = "<size=45>¡Despeja un camino!</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>¡No se interponga en nuestro camino!</size>",
  ui_story_5020_50200901_22_dialog_content = "¿Ahora qué?",
  ui_story_5020_50200901_23_dialog_content = "¡Los samuráis están liderando un gran grupo de personas aquí!",
  ui_story_5020_50200901_24_dialog_content = "Espera, ¿no son ellos...?",
  ui_story_5020_50200901_25_dialog_content = "¡Ellos son! ¡Es Wisp!",
  ui_story_5020_50200901_26_dialog_content = "¡¿Jirón?!",
  ui_story_5020_50200901_27_dialog_content = "¿Han sido todos capturados?",
  ui_story_5020_50200901_28_dialog_content = "Seguro que se ve así...",
  ui_story_5020_50200901_29_dialog_content = "También se dirigen al castillo.",
  ui_story_5020_50200901_30_dialog_content = "El castillo... ¿Qué les hará el general?",
  ui_story_5020_50200901_31_dialog_content = "Los va a usar como chivos expiatorios. Alguien para que el público dirija su ira y miedo.",
  ui_story_5020_50200901_32_dialog_content = "¡Pero no fue su culpa!",
  ui_story_5020_50200901_33_dialog_content = "¿La gente realmente le creerá?",
  ui_story_5020_50200901_34_dialog_content = "El general tiene el control total de los fantasmas y puede convocarlos y despedirlos a voluntad.",
  ui_story_5020_50200901_35_dialog_content = "Ahora que Wisp ha sido capturado, puede detener fácilmente los ataques y hacer que la gente crea que los rebeldes fueron los responsables.",
  ui_story_5020_50200901_36_dialog_content = "Todo lo que pueden hacer es creerle.",
  ui_story_5020_50200901_37_dialog_content = "Pero si eso sucede...",
  ui_story_5020_50200901_38_dialog_content = "Si eso pasa...",
  ui_story_5020_50200901_39_dialog_content = "¿Ah?",
  ui_story_5020_50200901_40_dialog_content = "Entonces no habrá más fantasmas para luchar en Koufu-jou...",
  ui_story_5020_50200901_41_dialog_content = "¿No sería eso... algo bueno?",
  ui_story_5020_50200901_42_dialog_content = "Tienes razon, si...",
  ui_story_5020_50200901_43_dialog_content = "Estas son las tácticas de un gobernante frío y despiadado.",
  ui_story_5020_50200901_44_dialog_content = "Se sacrifica y traiciona a los demás sin dudarlo.",
  ui_story_5020_50200901_45_dialog_content = "Pero al final... las cosas parecerán mejores, al menos en la superficie.",
  ui_story_5020_50200901_46_dialog_content = "...",
  ui_story_5020_50200901_47_dialog_content = "Pero solo en la superficie, ¿no?",
  ui_story_5020_50200901_48_dialog_content = "La gente de Cloud Island cree en la existencia del alma con todo su corazón.",
  ui_story_5020_50200901_49_dialog_content = "Si las cosas salen como predije, todos vivirán en el mundo ilusorio del general, felices y sin preocupaciones.",
  ui_story_5020_50200901_50_dialog_content = "Pero un alma que vive en la ignorancia pecaminosa de una verdad tan terrible no es diferente de la muerte.",
  ui_story_5020_50200901_51_dialog_content = "Creo que cualquiera que sepa la verdad no se quedaría de brazos cruzados y aceptaría las cosas como son.",
  ui_story_5020_50200901_52_dialog_content = "¡Así es! ¿Cómo podía una ciudad entera vivir bajo la ilusión de tal mentira?",
  ui_story_5020_50200901_53_dialog_content = "¡Todos necesitan escuchar la verdad!",
  ui_story_5020_50200901_54_dialog_content = "...",
  ui_story_5020_50200901_55_dialog_content = "Ustedes dos tienen toda la razón.",
  ui_story_5020_50200901_56_dialog_content = "Una paz construida sobre una montaña de mentiras no es paz en absoluto.",
  ui_story_5020_50200901_57_dialog_content = "Tenemos que mostrarles a todos la verdad.",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>Pit-pat... Pit-pat...</color>",
  ui_story_5020_50200901_59_dialog_content = "Anzu, Momo... ¿Creen que podrán alcanzar a ese equipo de Wisp?",
  ui_story_5020_50200901_60_dialog_content = "¿Alcanzarlos?",
  ui_story_5020_50200901_61_dialog_content = "Si lo hacemos, entonces realmente no tenemos ninguna posibilidad de escapar, ya sabes.",
  ui_story_5020_50200901_62_dialog_content = "No estamos escapando. Ya no.",
  ui_story_5020_50200901_63_dialog_content = "¡No me gustaría perderme el Festival Kasuga por nada!",
  ui_story_5020_50200901_64_dialog_content = "Escuché que van a llevar a juicio a algunos criminales... ¿Es verdad?",
  ui_story_5020_50200901_65_dialog_content = "¡Está! ¡El general lo dijo él mismo!",
  ui_story_5020_50200901_66_dialog_content = "¡Finalmente, los traidores que convocaron a los fantasmas son llevados ante la justicia!",
  ui_story_5020_50200901_67_dialog_content = "¡Oye, mira para allá! ¡Están siendo escoltados a la plaza ahora mismo!",
  ui_story_5020_50200901_68_dialog_content = "Espera, ¿realmente fueron ellos? ¡Conozco a muchos de ellos!",
  ui_story_5020_50200901_69_dialog_content = "Quién sabe, tal vez solo estén siendo utilizados como chivos expiatorios...",
  ui_story_5020_50200901_70_dialog_content = "¡Hmph! El general seguro sabe cómo asegurar su posición.",
  ui_story_5020_50200901_71_dialog_content = "Bueno, quienquiera que sea el responsable de todo esto tendrá que pagar mucho...",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>¡Bang...!</color>",
  ui_story_5020_50200901_73_dialog_content = "¡General!",
  ui_story_5020_50200901_74_dialog_content = "¡Todos los rebeldes Wisp han sido capturados!",
  ui_story_5020_50200901_75_dialog_content = "¡Le pedimos humildemente que los juzgue por sus crímenes atroces!",
  ui_story_5020_50200901_76_dialog_content = "Han pasado varias décadas desde que pisé Koufu-jou por primera vez.",
  ui_story_5020_50200901_77_dialog_content = "Me he cansado de la lucha constante y antiestética que me ha rodeado desde entonces.",
  ui_story_5020_50200901_78_dialog_content = "Todo eso termina hoy. Aquí mismo. Ahora mismo.",
  ui_story_5020_50200901_79_dialog_content = "Puedo ver el amanecer de la paz acercándose...",
  ui_story_5020_50200901_80_dialog_content = "Paz...",
  ui_story_5020_50200901_81_dialog_content = "Cuando la guerra amenazó a todo Koufu-jou, fui yo quien puso fin a la lucha.",
  ui_story_5020_50200901_82_dialog_content = "Cuando los fantasmas amenazaron nuestra forma de vida, comencé a entrenar sacerdotisas para suprimir la amenaza de los muertos vivientes.",
  ui_story_5020_50200901_83_dialog_content = "Bajo mi gobierno, todo Koufu-jou ha disfrutado de un nivel de paz y tranquilidad sin precedentes.",
  ui_story_5020_50200901_84_dialog_content = "Pero siempre hay quienes nunca estarán satisfechos.",
  ui_story_5020_50200901_85_dialog_content = "Pisotearon el orden que había estado manteniendo, ¡y descaradamente exigieron más!",
  ui_story_5020_50200901_86_dialog_content = "Ahora, están arrodillados frente a todos nosotros.",
  ui_story_5020_50200901_87_dialog_content = "...",
  ui_story_5020_50200901_88_dialog_content = "Wisp rebeldes, ¿eres consciente de tus pecados?",
  ui_story_5020_50200901_89_dialog_content = "¿Pecados?",
  ui_story_5020_50200901_90_dialog_content = "Honestamente, no tengo idea.",
  ui_story_5020_50200901_91_dialog_content = "Suenas como si supieras, ¿por qué no te doy el honor de decírnoslo?",
  ui_story_5020_50200901_92_dialog_content = "Por supuesto. Entonces lo haré.",
  ui_story_5020_50200901_93_dialog_content = "Te uniste a fantasmas viciosos para perturbar la paz y el orden de Koufu-jou.",
  ui_story_5020_50200901_94_dialog_content = "¡Esto se castiga con la muerte!",
  ui_story_5020_50200901_95_dialog_content = "jaja.",
  ui_story_5020_50200901_96_dialog_content = "Fujikumo, viejo...",
  ui_story_5020_50200901_97_dialog_content = "(Uh, disculpe. Odio interrumpir su apasionado discurso).",
  ui_story_5020_50200901_98_dialog_content = "(Pero, ¿podría jugar suave para ganarnos más tiempo?)",
  ui_story_5020_50200901_99_dialog_content = "(Será difícil salvarte si te ejecutan de inmediato).",
  ui_story_5020_50200901_100_dialog_content = "...",
  ui_story_5020_50200901_101_dialog_content = "(Anzu y Momo te desatarán más tarde. Será nuestra única oportunidad.)",
  ui_story_5020_50200901_102_dialog_content = "(Debes someter a todos los samuráis a la vez, o todos estamos jodidos).",
  ui_story_5020_50200901_103_dialog_content = "(Tose si entiendes.)",
  ui_story_5020_50200901_104_dialog_content = "*Tose*",
  ui_story_5020_50200901_105_dialog_content = "(Está bien. Continúa, mantenlo ocupado.)",
  ui_story_5020_50200901_106_dialog_content = "Er... mi señor, alquile escúcheme.",
  ui_story_5020_50200901_107_dialog_content = "Adelante, corta una o dos extremidades, pero ¿podrías mantener mi cabeza en mi cuello?",
  ui_story_5020_50200901_108_dialog_content = "...",
  ui_story_5020_50200901_109_dialog_content = "Tengo dos brazos y dos piernas. Elige lo que quieras.",
  ui_story_5020_50200901_110_dialog_content = "Pero todavía tengo uso para mi cabeza, así que me gustaría conservarla.",
  ui_story_5020_50200901_111_dialog_content = "Vale, tenemos tres samuráis aquí... y cinco más allá. Hay otros dos cruzando la calle.",
  ui_story_5020_50200901_112_dialog_content = "Vice, puedes recordar todo eso?",
  ui_story_5020_50200901_113_dialog_content = "Tres... Y cinco... Y dos más...",
  ui_story_5020_50200901_114_dialog_content = "Tienes que recordarlo. ¡No tendremos una segunda oportunidad!",
  ui_story_5020_50200901_115_dialog_content = "Anzu y Momo han aflojado el parche. Sólo tenemos que bucear a través de él.",
  ui_story_5020_50200901_116_dialog_content = "Una vez que salgamos del tambor, ¡tenemos que noquear a todos los samuráis!",
  ui_story_5020_50200901_117_dialog_content = "Esta es la única forma en que Anzu y Momo pueden desatar el Wisp.",
  ui_story_5020_50200901_118_dialog_content = "¡Sí! Tres... y cinco...",
  ui_story_5020_50200901_119_dialog_content = "Y mi papel es detener al general, ¿verdad?",
  ui_story_5020_50200901_120_dialog_content = "Sí, haz el mayor caos posible.",
  ui_story_5020_50200901_121_dialog_content = "Una vez que el general ordene a los fantasmas que nos detengan, ¡la verdad saldrá a la luz!",
  ui_story_5020_50200901_122_dialog_content = "¿Y luego? ¿Cómo salimos después?",
  ui_story_5020_50200901_123_dialog_content = "No puedo planear con tanta antelación. ¡Tendremos que improvisar después de eso!",
  ui_story_5020_50200901_124_dialog_content = "Anzu y Momo, ¿están listos?",
  ui_story_5020_50200901_125_dialog_content = "¡Sí!",
  ui_story_5020_50200901_126_dialog_content = "Cortaremos las cuerdas y luego correremos con el Wisp.",
  ui_story_5020_50200901_127_dialog_content = "¡Exactamente!",
  ui_story_5020_50200901_128_dialog_content = "No parece que estén en buen estado...",
  ui_story_5020_50200901_129_dialog_content = "¿Será peligroso?",
  ui_story_5020_50200901_130_dialog_content = "Háganos saber si está en peligro.",
  ui_story_5020_50200901_131_dialog_content = "Me gusta...",
  ui_story_5020_50200901_132_dialog_content = "Usa este tambor.",
  ui_story_5020_50200901_133_dialog_content = "¡Correcto! Entendido.",
  ui_story_5020_50200901_134_dialog_content = "¡Me encanta tocar la batería!",
  ui_story_5020_50200901_135_dialog_content = "ahora solo nos queda esperar Vice para memorizarlo todo...",
  ui_story_5020_50200901_136_dialog_content = "¡Lo tengo!",
  ui_story_5020_50200901_137_dialog_content = "¡Está bien!",
  ui_story_5020_50200901_138_dialog_content = "Prepararse. Tres...",
  ui_story_5020_50200901_139_dialog_content = "<size=40>Dos...</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>Una...</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>¡Ir!</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>Auge...</size></color>",
  ui_story_5020_50200901_143_dialog_content = "¡Torrente rápido!",
  ui_story_5020_50200901_144_dialog_content = "¡Rescata al Wisp! ¡Apurarse!",
  ui_story_5020_50200901_145_dialog_content = "¡Sé que sé!",
  ui_story_5020_50200901_146_dialog_content = "¡Ayuda! ¡Hay una pelea!",
  ui_story_5020_50200901_147_dialog_content = "¡Hermanos, recojan sus armas!",
  ui_story_5020_50200901_148_dialog_content = "¡Rebeldes! ¡Protege al general!",
  ui_story_5020_50200901_149_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50200901_150_dialog_content = "...",
  ui_story_5020_50200901_151_dialog_content = "...",
  ui_story_5020_50200901_152_dialog_content = "Rinne, has cometido un gran error.",
  ui_story_5020_50200901_153_dialog_content = "¿Por qué?",
  ui_story_5020_50200901_154_dialog_content = "Porque esto está mal.",
  ui_story_5020_50200901_155_dialog_content = "El bien y el mal que me enseñaste parecen bastante diferentes de tus creencias reales.",
  ui_story_5020_50200901_156_dialog_content = "No puedo enseñarte todo lo que sé. Tomará tiempo para que lo entiendas.",
  ui_story_5020_50200901_157_dialog_content = "No hay necesidad. Lo he descubierto yo mismo.",
  ui_story_5020_50200901_158_dialog_content = "Todas las sacerdotisas antes que yo, las que hicieron lo que pensabas que era correcto, ¿dónde están ahora?",
  ui_story_5020_50200901_159_dialog_content = "Construyeron el Koufu-jou que ves hoy.",
  ui_story_5020_50200901_160_dialog_content = "¿En serio?",
  ui_story_5020_50200901_161_dialog_content = "Me gustaría ver un Koufu-jou diferente.",
  ui_story_5020_50200901_162_dialog_content = "¿Y así es como eliges hacerlo?",
  ui_story_5020_50200901_163_dialog_content = "He visto demasiados levantamientos en mi vida. Nunca trajeron cambio, solo destrucción.",
  ui_story_5020_50200901_164_dialog_content = "Seguro que hay cosas que no has visto.",
  ui_story_5020_50200901_165_dialog_content = "Como una sacerdotisa apuntándote con una espada.",
  ui_story_5020_50200901_166_dialog_content = "No me importa hacia dónde apuntes tu espada.",
  ui_story_5020_50200901_167_dialog_content = "Sólo quiero que lo pienses bien.",
  ui_story_5020_50200901_168_dialog_content = "Pensé que los fantasmas eran mi único enemigo.",
  ui_story_5020_50200901_169_dialog_content = "Pero ahora, estoy frente a ti.",
  ui_story_5020_50200901_170_dialog_content = "Y por primera vez siento un odio intenso hacia una persona viva.",
  ui_story_5020_50200901_171_dialog_content = "Deberías tener miedo de este odio.",
  ui_story_5020_50200901_172_dialog_content = "Jeje.",
  ui_story_5020_50200901_173_dialog_content = "Estoy más emocionado que asustado.",
  ui_story_5020_50200902_1_dialog_content = "¡Mátalos!",
  ui_story_5020_50200902_2_dialog_content = "¡Rebeldes imprudentes!",
  ui_story_5020_50200902_3_dialog_content = "¡Ahhh! ¡Están matando gente!",
  ui_story_5020_50200902_4_dialog_content = "¡No entres en pánico!",
  ui_story_5020_50200902_5_dialog_content = "¡Reagruparse! ¡Rodead a los rebeldes!",
  ui_story_5020_50200902_6_dialog_content = "¿Nos rodean? ¡Hmph!",
  ui_story_5020_50200902_7_dialog_content = "Samurai, no creo que entiendas la situación.",
  ui_story_5020_50200902_8_dialog_content = "¡Sin los fantasmas que te ayuden, no puedes comandar este campo de batalla!",
  ui_story_5020_50200902_9_dialog_content = "Que broma.",
  ui_story_5020_50200902_10_dialog_content = "¿Cuándo ganaste Wisp alguna vez una pelea, ya sea contra fantasmas o personas vivas?",
  ui_story_5020_50200902_11_dialog_content = "Esta vez.",
  ui_story_5020_50200902_12_dialog_content = "¿Deberíamos correr? no quiero morir...",
  ui_story_5020_50200902_13_dialog_content = "¿A donde? Si nos vamos, podríamos encontrarnos con fantasmas...",
  ui_story_5020_50200902_14_dialog_content = "Primero los fantasmas matan gente, ahora la gente también mata gente...",
  ui_story_5020_50200902_15_dialog_content = "¿Cuántas vidas se tomarán hoy?",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_5020_50200902_17_dialog_content = "!!!",
  ui_story_5020_50200902_18_dialog_content = "!",
  ui_story_5020_50200902_19_dialog_content = "Eso fue...",
  ui_story_5020_50200902_20_dialog_content = "Oh, no.",
  ui_story_5020_50200902_21_dialog_content = "La nube dorada ha emergido, proyectando su brillo sobre el mundo. Todos los fantasmas y espíritus se inclinan ante su rey.",
  ui_story_5020_50200902_22_dialog_content = "...",
  ui_story_5020_50200902_23_dialog_content = "General, finalmente es hora de que me enseñe a usar el espejo de nube.",
  ui_story_5020_50200902_24_dialog_content = "Todo lo que siempre quise fue paz.",
  ui_story_5020_50200902_25_dialog_content = "Te beneficias de la paz pero no la entiendes.",
  ui_story_5020_50200902_26_dialog_content = "No tengo tiempo para enseñarte nada más.",
  ui_story_5020_50200902_27_dialog_content = "Hoy, Koufu-jou conocerá la paz.",
  ui_story_5020_50200902_28_dialog_content = "Te guste o no.",
  ui_story_5020_50200902_29_dialog_content = "...",
  ui_story_5020_50200902_30_dialog_content = "...",
  ui_story_5020_50200902_31_dialog_content = "Fantasmas... ¡Vienen los fantasmas!",
  ui_story_5020_50200902_32_dialog_content = "¡Deja de pelear! ¡Trata primero con los fantasmas!",
  ui_story_5020_50200902_33_dialog_content = "¿Detener? ¡Mmm!",
  ui_story_5020_50200902_34_dialog_content = "Los samuráis finalmente tienen ganas de luchar, ahora que sus refuerzos están aquí.",
  ui_story_5020_50200902_35_dialog_content = "...",
  ui_story_5020_50200902_36_dialog_content = "¡Soldados!",
  ui_story_5020_50200902_37_dialog_content = "Bloquear todas las calles.",
  ui_story_5020_50200902_38_dialog_content = "¡Por orden del general, nadie sale de este lugar!",
  ui_story_5020_50200902_39_dialog_content = "¿Qué?",
  ui_story_5020_50200902_40_dialog_content = "¿Qué quieres decir con que nadie se va? ¡Vienen los fantasmas!",
  ui_story_5020_50200902_41_dialog_content = "Eres tú...",
  ui_story_5020_50200902_42_dialog_content = "¡Mis compañeros! ¡El Wisp no recibe órdenes del general!",
  ui_story_5020_50200902_43_dialog_content = "¡Abre un camino y escolta a los civiles a un lugar seguro!",
  ui_story_5020_50200902_44_dialog_content = "¡Sí!",
  ui_story_5020_50200902_45_dialog_content = "¡Apurarse! ¡Sigue al Wisp!",
  ui_story_5020_50200902_46_dialog_content = "Eso es lo que he estado diciendo, ¡siempre puedes confiar en la gente de Cloud Island!",
  ui_story_5020_50200902_47_dialog_content = "¡Claramente, ese general está en connivencia con los fantasmas!",
  ui_story_5020_50200902_48_dialog_content = "¡Hmph! ¡Una persona con corazón de lobo!",
  ui_story_5020_50200902_49_dialog_content = "¿Estás bloqueando las calles? ¿Qué pasa con los civiles?",
  ui_story_5020_50200902_50_dialog_content = "Estoy manteniendo el orden para ellos.",
  ui_story_5020_50200902_51_dialog_content = "Aquellos que observan el orden disfrutan de la paz. Y los que desafían el orden serán castigados.",
  ui_story_5020_50200902_52_dialog_content = "¿Estás usando fantasmas para mantener el orden?",
  ui_story_5020_50200902_53_dialog_content = "Estas loco.",
  ui_story_5020_50200902_54_dialog_content = "Fantasmas, personas... No son tan diferentes.",
  ui_story_5020_50200902_55_dialog_content = "Rinne, te has vuelto superficial.",
  ui_story_5020_50200902_56_dialog_content = "¡Por qué tú...!",
  ui_story_5020_50200902_57_dialog_content = "Rinneolvídalo por ahora.",
  ui_story_5020_50200902_58_dialog_content = "El Wisp está tratando de abrirse paso entre los civiles, pero...",
  ui_story_5020_50200902_59_dialog_content = "Están superados en número, es posible que no lo logren.",
  ui_story_5020_50200902_60_dialog_content = "... ¿Tiene un plan?",
  ui_story_5020_50200902_61_dialog_content = "Sí.",
  ui_story_5020_50200902_62_dialog_content = "Les das una mano.",
  ui_story_5020_50200902_63_dialog_content = "¿Me? Entonces, ¿qué pasa con la situación aquí?",
  ui_story_5020_50200902_64_dialog_content = "Vice y yo me ocuparé del general.",
  ui_story_5020_50200902_65_dialog_content = "¿Eh? ¿Lo haremos?",
  ui_story_5020_50200902_66_dialog_content = "Si. No estoy seguro de cuánto tiempo podemos aguantar aquí. No hay tiempo que perder.",
  ui_story_5020_50200902_67_dialog_content = "Rinne, nadie puede luchar contra los fantasmas mejor que tú. Tenías que ser tú.",
  ui_story_5020_50200902_68_dialog_content = "No estoy seguro de que puedas...",
  ui_story_5020_50200902_69_dialog_content = "¡No te preocupes! ¡Tenemos esto!",
  ui_story_5020_50200902_70_dialog_content = "¡Date prisa!",
  ui_story_5020_50200902_71_dialog_content = "...Okey.",
  ui_story_5020_50200902_72_dialog_content = "Sólo ten cuidado, ¿de acuerdo?",
  ui_story_5020_50200902_73_dialog_content = "... PlayerName, ¿estás seguro de que es una buena idea?",
  ui_story_5020_50200902_74_dialog_content = "¿Tú y yo contra el general?",
  ui_story_5020_50200902_75_dialog_content = "No tenemos oportunidad.",
  ui_story_5020_50200902_76_dialog_content = "<size=45>¡Pensé que tenías un plan!</size>",
  ui_story_5020_50200902_77_dialog_content = "Cálmate. Tenemos ayudantes.",
  ui_story_5020_50200902_78_dialog_content = "Están en camino.",
  ui_story_5020_50200902_79_dialog_content = "¡Ay! ¡Otro callejón sin salida!",
  ui_story_5020_50200902_80_dialog_content = "¿Quién pensó que era una buena idea construir una casa tan complicada?",
  ui_story_5020_50200902_81_dialog_content = "Tal vez tenga que pasar la noche aquí...",
  ui_story_5020_50200902_82_dialog_content = "Sin comida ni agua...",
  ui_story_5020_50200902_83_dialog_content = "Y en el calor humeante...",
  ui_story_5020_50200902_84_dialog_content = "¿Mmm? ¿Ha hecho tanto calor todo este tiempo?",
  ui_story_5020_50200902_85_dialog_content = "¡Whoa!",
  ui_story_5020_50200902_86_dialog_content = "F-fuego! ¿Hay alguien aquí?",
  ui_story_5020_50200902_87_dialog_content = "No puedo quedarme aquí más... ¡Ahora tengo que salir!",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>Golpear...</color>",
  ui_story_5020_50200902_89_dialog_content = "¡Ay! ¡No es otro callejón sin salida!",
  ui_story_5020_50200902_90_dialog_content = "¿Qué tengo que hacer? ¿Qué tal esta ventana?",
  ui_story_5020_50200902_91_dialog_content = "¡Esta muy alto!",
  ui_story_5020_50200902_92_dialog_content = "De ninguna manera... Si salto aquí...",
  ui_story_5020_50200902_93_dialog_content = "¡Aaaahhhh!",
  ui_story_5020_50200902_94_dialog_content = "¡Supongo que no es tan alto después de todo!",
  ui_story_5020_50200902_95_dialog_content = "Está bien. ¡Mientras no caiga de cabeza, estaré bien!",
  ui_story_5020_50200902_96_dialog_content = "Listo...",
  ui_story_5020_50200902_97_dialog_content = "Uno dos...",
  ui_story_5020_50200902_98_dialog_content = "Tres!",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>¡Wahhhhhhhhhhhhhhhhh!</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>Estallido...</color>",
  ui_story_5020_50200902_101_dialog_content = "¡Ay! mi trasero...",
  ui_story_5020_50200902_102_dialog_content = "Es eso... Yao?",
  ui_story_5020_50200902_103_dialog_content = "¡Sí!",
  ui_story_5020_50200902_104_dialog_content = "¡Guau! Vice! PlayerName!",
  ui_story_5020_50200902_105_dialog_content = "¡Ha sido para siempre!",
  ui_story_5020_50200902_106_dialog_content = "... ¿Me puedes dar una mano?",
  ui_story_5020_50200902_107_dialog_content = "... Ven aquí. Agárrate fuerte.",
  ui_story_5020_50200902_108_dialog_content = "PlayerName, ¿es este uno de los ayudantes de los que hablaste?",
  ui_story_5020_50200902_109_dialog_content = "Creo que a ella le vendría bien un poco de ayuda.",
  ui_story_5020_50200902_110_dialog_content = "Err... Ella es una de ellas.",
  ui_story_5020_50200902_111_dialog_content = "¡Fuera del camino!",
  ui_story_5020_50200902_112_dialog_content = "Fujikumo, es hora de que pagues.",
  ui_story_5020_50200902_113_dialog_content = "¿Quién es usted? No puedo recordar deberle nada.",
  ui_story_5020_50200902_114_dialog_content = "Le debes la vida a Cloud Island.",
  ui_story_5020_50200902_115_dialog_content = "Amemori! ¡Que bueno verte!",
  ui_story_5020_50200902_116_dialog_content = "He estado observando desde la torre de la puerta.",
  ui_story_5020_50200902_117_dialog_content = "Estaba planeando disfrutar de un espectáculo, pero ustedes no dieron mucha pelea.",
  ui_story_5020_50200902_118_dialog_content = "que divertido",
  ui_story_5020_50200902_119_dialog_content = "¿De verdad pensaste que reunir algunas ratas más sería suficiente para derrocarme?",
  ui_story_5020_50200902_120_dialog_content = "¡Jajajajajaja!",
  ui_story_5020_50200902_121_dialog_content = "No mires hacia abajo a las ratas. ¡Tienen dientes!",
  ui_story_5020_50200902_122_dialog_content = "Dales una década o, mejor aún, un siglo...",
  ui_story_5020_50200902_123_dialog_content = "¡Y pueden derribar hasta el castillo más alto!",
  ui_story_5020_50200902_124_dialog_content = "¡La ciudad entera está en llamas!",
  ui_story_5020_50200902_125_dialog_content = "Bueno, sí. Por eso salté...",
  ui_story_5020_50200902_126_dialog_content = "Fujikumo, ¿alguna vez has visto una torre de entrada más hermosa?",
  ui_story_5020_50200902_127_dialog_content = "Es tan alto que oculta una parte considerable del cielo.",
  ui_story_5020_50200902_128_dialog_content = "Pero esta es la primera vez que se ve realmente bonita, envuelta en la fragancia del vino y el calor del fuego.",
  ui_story_5020_50200902_129_dialog_content = "Creo que todo en el mundo existe para ese momento glorioso.",
  ui_story_5020_50200902_130_dialog_content = "Y este es el mejor final que podría tener.",
  ui_story_5020_50200902_131_dialog_content = "Espada del Inframundo...",
  ui_story_5020_50200902_132_dialog_content = "Sabía que no huirías. La libertad no puede satisfacerte.",
  ui_story_5020_50200902_133_dialog_content = "Sigues siendo la misma hoja malvada que una vez vino por mí desde el infierno...",
  ui_story_5020_50200902_134_dialog_content = "Fujikumo, ¿cuándo crees que Tsuki era más hermosa?",
  ui_story_5020_50200902_135_dialog_content = "... ¡No eres digno de pronunciar su nombre!",
  ui_story_5020_50200902_136_dialog_content = "Cuando era pequeña, pensaba que era tan hermosa cuando me enseñó a cantar.",
  ui_story_5020_50200902_137_dialog_content = "A medida que fui creciendo, sentí que era aún más hermosa cuando me dijo que las sacerdotisas podían traer paz a este mundo.",
  ui_story_5020_50200902_138_dialog_content = "Adivina cuándo creo que era más hermosa ahora.",
  ui_story_5020_50200902_139_dialog_content = "¡Basta!",
  ui_story_5020_50200902_140_dialog_content = "Era la más hermosa cuando falleció en mis brazos.",
  ui_story_5020_50200902_141_dialog_content = "...",
  ui_story_5020_50200902_142_dialog_content = "Era tan hermosa que no pude contener mi rabia y mi odio.",
  ui_story_5020_50200902_143_dialog_content = "Porque eras dueño de cada parte de su belleza.",
  ui_story_5020_50200902_144_dialog_content = "Han pasado diez años, gobernante de Koufu-jou.",
  ui_story_5020_50200902_145_dialog_content = "Hagamos una prueba de determinación.",
  ui_story_5020_50200902_146_dialog_content = "¿Estás más decidido a deshacerte de mí o yo estoy más decidido a matarte?",
  ui_story_5020_50201001_1_dialog_content = "¡Cómo te atreves a hablar de ella así!",
  ui_story_5020_50201001_2_dialog_content = "¡Cómo te atreves a decir su nombre!",
  ui_story_5020_50201001_3_dialog_content = "Tu ignorancia arruinó el mundo perfecto que ella creó.",
  ui_story_5020_50201001_4_dialog_content = "¡Deberías pedirle perdón en el infierno!",
  ui_story_5020_50201001_5_dialog_content = "!!!",
  ui_story_5020_50201001_6_dialog_content = "... Fujikumo, realmente te volviste loco.",
  ui_story_5020_50201001_7_dialog_content = "No tengo nada que perder.",
  ui_story_5020_50201001_8_dialog_content = "...",
  ui_story_5020_50201001_9_dialog_content = "Hola, ustedes dos. No te quedes ahí parado y mires.",
  ui_story_5020_50201001_10_dialog_content = "¡Maestría! ¡Estoy listo para ayudarte!",
  ui_story_5020_50201001_11_dialog_content = "No estoy pidiendo ayuda.",
  ui_story_5020_50201001_12_dialog_content = "Necesito que huyas, tan rápido como puedas.",
  ui_story_5020_50201001_13_dialog_content = "Pero... Maestro...",
  ui_story_5020_50201001_14_dialog_content = "¡Dije correr!",
  ui_story_5020_50201001_15_dialog_content = "¡No tengo tiempo para esto!",
  ui_story_5020_50201001_16_dialog_content = "¡No me empeore las cosas!",
  ui_story_5020_50201001_17_dialog_content = "Maestría...",
  ui_story_5020_50201001_18_dialog_content = "¡E-está bien!",
  ui_story_5020_50201001_19_dialog_content = "Vamos, Amemori. ¡El maestro tiene esto!",
  ui_story_5020_50201001_20_dialog_content = "...",
  ui_story_5020_50201001_21_dialog_content = "Si señor.",
  ui_story_5020_50201001_22_dialog_content = "¡Así es, los buenos aprendices hacen lo que les dice su maestro!",
  ui_story_5020_50201001_23_dialog_content = "Bueno, bueno, Sword of the Underworld, nunca esperé ver el autosacrificio en ti.",
  ui_story_5020_50201001_24_dialog_content = "Ja. Simplemente quiero continuar con la leyenda de la Espada del Inframundo.",
  ui_story_5020_50201001_25_dialog_content = "Como maestro de la espada conocido por cazar fantasmas, no podía perder la oportunidad de luchar contra el hombre que eligió convertirse en uno...",
  ui_story_5020_50201001_26_dialog_content = "y morir en su mano.",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5020_50201001_28_dialog_content = "Su voz da mucho miedo...",
  ui_story_5020_50201001_29_dialog_content = "¿Es esto realmente una pelea de dos personas?",
  ui_story_5020_50201001_30_dialog_content = "Huir es definitivamente la decisión correcta... Incluso todos nosotros juntos todavía no somos rival para él.",
  ui_story_5020_50201001_31_dialog_content = "¿Qué está pasando en la ciudad?",
  ui_story_5020_50201001_32_dialog_content = "donde esta Rinne? ¿Por qué no está contigo?",
  ui_story_5020_50201001_33_dialog_content = "Err... Es una larga historia.",
  ui_story_5020_50201001_34_dialog_content = "El general conjuró fantasmas para restaurar el orden. Unieron fuerzas con los samuráis, intentando mantener el control de todos los ciudadanos de Koufu-jou.",
  ui_story_5020_50201001_35_dialog_content = "Afortunadamente, la mayoría de los civiles se han reunido. el fuego fatuo y Rinne los están escoltando a un lugar seguro.",
  ui_story_5020_50201001_36_dialog_content = "¿Avispa?",
  ui_story_5020_50201001_37_dialog_content = "¡Jirón!",
  ui_story_5020_50201001_38_dialog_content = "Una fuerza compuesta por lugareños de Cloud Island. El Maestro y yo somos parte de ellos.",
  ui_story_5020_50201001_39_dialog_content = "¡Correcto!",
  ui_story_5020_50201001_40_dialog_content = "Solías ser uno de nosotros.",
  ui_story_5020_50201001_41_dialog_content = "¿Entonces los Wisp son buenos?",
  ui_story_5020_50201001_42_dialog_content = "Claro.",
  ui_story_5020_50201001_43_dialog_content = "Pero, ¿por qué está la sacerdotisa con el Wisp?",
  ui_story_5020_50201001_44_dialog_content = "¿La secuestraron?",
  ui_story_5020_50201001_45_dialog_content = "Secuestradores! ¡Los Wisp son malos!",
  ui_story_5020_50201001_46_dialog_content = "No, no... Pasaron cosas, y Rinne luchó codo con codo con el Wisp.",
  ui_story_5020_50201001_47_dialog_content = "Por ahora digamos que están de nuestro lado.",
  ui_story_5020_50201001_48_dialog_content = "¿El Wisp y la sacerdotisa están del mismo lado?",
  ui_story_5020_50201001_49_dialog_content = "Todo esto es muy difícil de digerir...",
  ui_story_5020_50201001_50_dialog_content = "Eh... como Rinne dicho antes, los fantasmas son el único enemigo de la sacerdotisa.",
  ui_story_5020_50201001_51_dialog_content = "Así que está cumpliendo con su deber.",
  ui_story_5020_50201001_52_dialog_content = "... Bien, ya veo.",
  ui_story_5020_50201001_53_dialog_content = "Ella mantendrá a salvo a los civiles, al menos por un tiempo.",
  ui_story_5020_50201001_54_dialog_content = "Tengo que ir a buscar algo.",
  ui_story_5020_50201001_55_dialog_content = "¿Qué es?",
  ui_story_5020_50201001_56_dialog_content = "La espada que mata fantasmas—<color=#FFB400>Pedazo de cielo</color>.",
  ui_story_5020_50201001_57_dialog_content = "Según el maestro... Podría ser capaz de cambiar el rumbo.",
  ui_story_5020_50201001_58_dialog_content = "¡Creo que Wisp también lo mencionó! Es un arma legendaria, ¿verdad?",
  ui_story_5020_50201001_59_dialog_content = "Pero su paradero es un misterio...",
  ui_story_5020_50201001_60_dialog_content = "Fue enterrada con la anterior sacerdotisa.",
  ui_story_5020_50201001_61_dialog_content = "¡Ay! ¡Eso es una pista!",
  ui_story_5020_50201001_62_dialog_content = "Pero necesitaremos más que eso...",
  ui_story_5020_50201001_63_dialog_content = "Podemos desenterrar todas las tumbas cerca de la ciudad.",
  ui_story_5020_50201001_64_dialog_content = "¡Esperar! ¡Eso es un poco excesivo!",
  ui_story_5020_50201001_65_dialog_content = "¿Qué sugieres entonces? Sólo el cielo sabe qué tumba pertenece a la anterior sacerdotisa...",
  ui_story_5020_50201001_66_dialog_content = "Err...",
  ui_story_5020_50201001_67_dialog_content = "¿No era Tsuki la sacerdotisa anterior?",
  ui_story_5020_50201001_68_dialog_content = "Correcto.",
  ui_story_5020_50201001_69_dialog_content = "¿La recuerdas?",
  ui_story_5020_50201001_70_dialog_content = "Sí.",
  ui_story_5020_50201001_71_dialog_content = "Yo... recuerdo dónde fue enterrada.",
  ui_story_5020_50201001_72_dialog_content = "¿¡Qué!?",
  ui_story_5020_50201001_73_dialog_content = "¿Tú haces?",
  ui_story_5020_50201001_73X1_dialog_content = "¿¡Qué!?",
  ui_story_5020_50201001_73X2_dialog_content = "T-tú... Si puedes recordar eso... ¿Significa eso...?",
  ui_story_5020_50201001_73X3_dialog_content = "¿Has recuperado tu memoria?",
  ui_story_5020_50201001_73X4_dialog_content = "Si. Ahora lo recuerdo todo.",
  ui_story_5020_50201001_73X5_dialog_content = "¡Eso es maravilloso!",
  ui_story_5020_50201001_73X6_dialog_content = "No esperaba que sucediera ahora, pero...",
  ui_story_5020_50201001_73X7_dialog_content = "¡Finalmente hemos logrado nuestro objetivo de venir a Cloud Island!",
  ui_story_5020_50201001_73X8_dialog_content = "Jaja, sí, ¡definitivamente lo hemos logrado!",
  ui_story_5020_50201001_73X9_dialog_content = "Por otra parte... Realmente no puedo decir que estoy feliz...",
  ui_story_5020_50201001_73X10_dialog_content = "Sí, especialmente con Koufu-jou en el estado en que se encuentra...",
  ui_story_5020_50201001_73X11_dialog_content = "¿Cómo recuperaste la memoria?",
  ui_story_5020_50201001_73X12_dialog_content = "Encontré un guardarropa en Cloud Pavilion, donde el maestro estaba encarcelado.",
  ui_story_5020_50201001_73X13_dialog_content = "Los recuerdos regresaron a raudales. Ahí es donde perdí la memoria hace diez años.",
  ui_story_5020_50201001_73X14_dialog_content = "Estaba escondido en el armario y vi que el maestro mató a Tsuki.",
  ui_story_5020_50201001_73X15_dialog_content = "Estaba aterrorizado y confundido, y yo...",
  ui_story_5020_50201001_73X16_dialog_content = "Supongo que mi cerebro enterró todo...",
  ui_story_5020_50201001_73X17_dialog_content = "Sí, eso no es algo que pueda llamar un recuerdo feliz...",
  ui_story_5020_50201001_73X18_dialog_content = "Todo este tiempo estuve buscando el dolor que quisiera olvidar...",
  ui_story_5020_50201001_73X19_dialog_content = "Ahora todo parece... sin sentido.",
  ui_story_5020_50201001_73X20_dialog_content = "Trate de pensar en ello de una manera diferente.",
  ui_story_5020_50201001_73X21_dialog_content = "Todo lo que hiciste fue confiar el recuerdo a una versión más madura de ti mismo.",
  ui_story_5020_50201001_73X22_dialog_content = "El recuerdo te ha estado esperando para crecer y volver a enfrentar el destino que evitaste hace diez años.",
  ui_story_5020_50201001_73X23_dialog_content = "¿Ah?",
  ui_story_5020_50201001_73X24_dialog_content = "Yo... no sabía que eras tan bueno consolando a la gente.",
  ui_story_5020_50201001_73X25_dialog_content = "...",
  ui_story_5020_50201001_73X26_dialog_content = "¿Los escuchaste decir dónde enterraron a Tsuki?",
  ui_story_5020_50201001_74_dialog_content = "Mmm...",
  ui_story_5020_50201001_75_dialog_content = "El general dijo que enterraría a Tsuki en el <color=#FFB400>montañas al oeste de Koufu-jou.</color>",
  ui_story_5020_50201001_76_dialog_content = "Las montañas al oeste Koufu-jou...",
  ui_story_5020_50201001_77_dialog_content = "Comprendo.",
  ui_story_5020_50201001_78_dialog_content = "Sígueme, fuera de la ciudad.",
  ui_story_5020_50201001_79_dialog_content = "¿Fuera de la ciudad? No será fácil salir...",
  ui_story_5020_50201001_80_dialog_content = "Nos encontraron.",
  ui_story_5020_50201001_81_dialog_content = "!!!",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>...</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>¡Nadie se va!</anim>",
  ui_story_5020_50201002_1_dialog_content = "Padre...",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50201002_3_dialog_content = "*Llanto*",
  ui_story_5020_50201002_4_dialog_content = "¡Hah!",
  ui_story_5020_50201002_5_dialog_content = "¡A la carga!",
  ui_story_5020_50201002_6_dialog_content = "¡Wow!",
  ui_story_5020_50201002_7_dialog_content = "¡No corras, chico! ¡Es peligroso ahí fuera!",
  ui_story_5020_50201002_8_dialog_content = "¡Vuelve con los demás!",
  ui_story_5020_50201002_9_dialog_content = "¡Está bien!",
  ui_story_5020_50201002_10_dialog_content = "¿Y tú?",
  ui_story_5020_50201002_11_dialog_content = "¡Tenemos cosas que hacer!",
  ui_story_5020_50201002_12_dialog_content = "Eso es suficiente, Anzu. ¡Darse prisa!",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50201002_14_dialog_content = "¡Oh!",
  ui_story_5020_50201002_15_dialog_content = "¡Este tambor es enorme!",
  ui_story_5020_50201002_16_dialog_content = "Impresionante, ¿no?",
  ui_story_5020_50201002_17_dialog_content = "¿Por qué lo traes contigo?",
  ui_story_5020_50201002_18_dialog_content = "¡Porque es nuestro!",
  ui_story_5020_50201002_19_dialog_content = "¿Pero no es peligroso ahí fuera?",
  ui_story_5020_50201002_20_dialog_content = "Es tan grande que parece una carga...",
  ui_story_5020_50201002_21_dialog_content = "¡Para nada! ¡Simplemente salvó al Wisp antes!",
  ui_story_5020_50201002_22_dialog_content = "Así es. ¡Podría salvar más vidas pronto!",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>Clic clic...</color>",
  ui_story_5020_50201002_24_dialog_content = "¡Jefe, me temo que no podemos pasar por aquí!",
  ui_story_5020_50201002_25_dialog_content = "Estamos demasiado agotados para enfrentarlos...",
  ui_story_5020_50201002_26_dialog_content = "¿Deberíamos intentarlo de otra manera?",
  ui_story_5020_50201002_27_dialog_content = "No tenemos elección. Pronto el enemigo nos tendrá rodeados.",
  ui_story_5020_50201002_28_dialog_content = "Tenemos que crear una apertura, y rápido.",
  ui_story_5020_50201002_29_dialog_content = "Pero...",
  ui_story_5020_50201002_30_dialog_content = "Sé que todos estamos exhaustos después de toda una noche de lucha.",
  ui_story_5020_50201002_31_dialog_content = "Pero esta batalla es diferente a las que hemos peleado antes.",
  ui_story_5020_50201002_32_dialog_content = "No solo estamos luchando por nuestras vidas. Tenemos a toda Cloud Island detrás de nosotros.",
  ui_story_5020_50201002_33_dialog_content = "Rendirse no es una opcion.",
  ui_story_5020_50201002_34_dialog_content = "¡Si morimos, seguiremos luchando como fantasmas!",
  ui_story_5020_50201002_35_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5020_50201002_36_dialog_content = "¿Quién les dio permiso para convertirse en fantasmas?",
  ui_story_5020_50201002_37_dialog_content = "Ya tengo suficientes cosas con las que lidiar.",
  ui_story_5020_50201002_38_dialog_content = "¿La sacerdotisa?",
  ui_story_5020_50201002_39_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5020_50201002_40_dialog_content = "PlayerName te debe un favor...",
  ui_story_5020_50201002_41_dialog_content = "Estoy aquí para vengarte.",
  ui_story_5020_50201002_42_dialog_content = "...",
  ui_story_5020_50201002_43_dialog_content = "Seguro.",
  ui_story_5020_50201002_44_dialog_content = "Entonces confiaré en ti para que te ocupes de los fantasmas.",
  ui_story_5020_50201002_45_dialog_content = "Y espero que tengas las tácticas cubiertas.",
  ui_story_5020_50201002_46_dialog_content = "Aprenderás que el Wisp es más confiable que ese general.",
  ui_story_5020_50201002_47_dialog_content = "¡Todo el mundo! ¡Prepárate para un ataque total! ¡Salgamos del cerco!",
  ui_story_5020_50201002_48_dialog_content = "¡Protege a los civiles! Nos dirigimos hacia el <color=#FFB400>Puerto</color>!",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>Tos...</anim>",
  ui_story_5020_50201002_50_dialog_content = "¿Te arrepientes de quedarte atrás, Nagi?",
  ui_story_5020_50201002_51_dialog_content = "¿Arrepentirse? Esa es una palabra nueva para mí.",
  ui_story_5020_50201002_52_dialog_content = "Eres un guerrero. ¿Alguna vez has imaginado tu muerte?",
  ui_story_5020_50201002_53_dialog_content = "Sólo una vez, hace diez años.",
  ui_story_5020_50201002_54_dialog_content = "Pensé que Tsuki y yo moriríamos juntos.",
  ui_story_5020_50201002_55_dialog_content = "Pero Tsuki quería que vivieras.",
  ui_story_5020_50201002_56_dialog_content = "Tu deuda con ella es mayor de lo que jamás podrías pagar.",
  ui_story_5020_50201002_57_dialog_content = "Solo rezo para que no seas su hermana en la próxima vida.",
  ui_story_5020_50201002_58_dialog_content = "tos... jajaja...",
  ui_story_5020_50201002_59_dialog_content = "La próxima vida... Suena bastante patético, viniendo de ti.",
  ui_story_5020_50201002_60_dialog_content = "¿Cuánto más puede durar tu corazón, Fujikumo?",
  ui_story_5020_50201002_61_dialog_content = "¿Quién podría guiar tu alma podrida al renacimiento?",
  ui_story_5020_50201002_62_dialog_content = "...",
  ui_story_5020_50201002_63_dialog_content = "Sé lo que me espera en la muerte.",
  ui_story_5020_50201002_64_dialog_content = "Pero perdí mi corazón hace mucho tiempo, cuando la perdí a ella.",
  ui_story_5020_50201002_65_dialog_content = "Entonces, ¿por qué tendría miedo de convertirme en un fantasma? No hay nada en este mundo mortal que me resista a dejar atrás.",
  ui_story_5020_50201002_66_dialog_content = "Eso suena bien...",
  ui_story_5020_50201002_67_dialog_content = "Morir de viejo en el Pabellón de Nieve... no es para ti.",
  ui_story_5020_50201002_68_dialog_content = "No te mereces un final pacífico.",
  ui_story_5020_50201002_69_dialog_content = "No me veo patético en absoluto.",
  ui_story_5020_50201002_70_dialog_content = "Soy un guerrero y acabo de derrotar a un rival muy poderoso.",
  ui_story_5020_50201002_71_dialog_content = "Pero Fujikumo...",
  ui_story_5020_50201002_72_dialog_content = "Nuestra batalla terminó hace diez años...",
  ui_story_5020_50201002_73_dialog_content = "Tienes que agradecer a Tsuki por estos diez años extra de vida.",
  ui_story_5020_50201002_74_dialog_content = "No olvides por qué esta batalla volvió a suceder...",
  ui_story_5020_50201002_75_dialog_content = "...",
  ui_story_5020_50201002_76_dialog_content = "¡Es porque nuevos luchadores están listos para dominar el campo de batalla!",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>Jajaja... eh...</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>¡Jajajaja!</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201101_2_dialog_content = "Uff.",
  ui_story_5020_50201101_3_dialog_content = "Tantos samuráis fantasmas...",
  ui_story_5020_50201101_4_dialog_content = "Fujikumo realmente está haciendo todo lo posible esta vez.",
  ui_story_5020_50201101_5_dialog_content = "¡A quien le importa! ¡Nos encargaremos de todos ellos, uno a la vez!",
  ui_story_5020_50201101_6_dialog_content = "¡Haaa! mazo de piedra!",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>¡Graaaagh!</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "¡E-Estos fantasmas son imposibles de matar!",
  ui_story_5020_50201101_10_dialog_content = "Solo Rinne puede tratar con ellos.",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>Graaaaaah!</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "¡Haaa!",
  ui_story_5020_50201101_13_dialog_content = "¡Es posible que no podamos destruirlos, pero aún podemos hacerlos retroceder!",
  ui_story_5020_50201101_14_dialog_content = "¡Naturaleza divina: puntas de bambú!",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>Gruñido...</anim>",
  ui_story_5020_50201101_16_dialog_content = "Pero...",
  ui_story_5020_50201101_17_dialog_content = "PlayerName, mira el castillo...",
  ui_story_5020_50201101_18_dialog_content = "!!!",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "¡¿C-Cómo pudo...?!",
  ui_story_5020_50201101_21_dialog_content = "Todos los samuráis fantasmas están huyendo del fuego en el castillo.",
  ui_story_5020_50201101_22_dialog_content = "Fujikumo convocó a tantos de ellos en un día...",
  ui_story_5020_50201101_23_dialog_content = "Realmente no se está conteniendo esta vez.",
  ui_story_5020_50201101_24_dialog_content = "¡Ninjutsu para siempre!",
  ui_story_5020_50201101_25_dialog_content = "Debemos salir de Sakai ahora y deshacernos de estos desagradables perseguidores.",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>Cerca de un cementerio en el campo a las afueras de Koufu-jou</color>",
  ui_story_5020_50201101_27_dialog_content = "¡Oh!",
  ui_story_5020_50201101_28_dialog_content = "PlayerName¡Algunos de mis viejos recuerdos acaban de regresar!",
  ui_story_5020_50201101_29_dialog_content = "¡He estado aqui antes!",
  ui_story_5020_50201101_30_dialog_content = "De hecho, has estado aquí antes...",
  ui_story_5020_50201101_31_dialog_content = "Aquí es donde nos conocimos Rinne y Amemori ¡por primera vez!",
  ui_story_5020_50201101_32_dialog_content = "Así es. El Colossus realizó un aterrizaje de emergencia después de nuestra llegada a la Isla de las Nubes...",
  ui_story_5020_50201101_32X_dialog_content = "Nos conocimos Rinne en el bosque de bambú más adelante, y...",
  ui_story_5020_50201101_33_dialog_content = "Amemori, ¡que tuvo que luchar contra nosotros antes de ser nuestra amiga!",
  ui_story_5020_50201101_34_dialog_content = "...",
  ui_story_5020_50201101_35_dialog_content = "¡Ja! ¡No es de extrañar que todo se sienta tan familiar!",
  ui_story_5020_50201101_36_dialog_content = "… \"Sigue este río hacia el oeste a través de Rice Paddy Village y llegarás al cementerio en las montañas\".",
  ui_story_5020_50201101_37_dialog_content = "Según mi memoria, ¡vamos por buen camino!",
  ui_story_5020_50201101_38_dialog_content = "Ey, Amemori. Quédate fuera de mi camino más tarde, ¿de acuerdo?",
  ui_story_5020_50201101_39_dialog_content = "¡Ja! Esa es mi linea.",
  ui_story_5020_50201101_40_dialog_content = "Rebanada del cielo: la espada que mata fantasmas es nuestra única esperanza contra los samuráis fantasmas de Fujikumo.",
  ui_story_5020_50201101_41_dialog_content = "No espero que me ayudes. Simplemente no se interponga en el camino.",
  ui_story_5020_50201101_42_dialog_content = "¡Esperar! ¿Qué quieres decir?",
  ui_story_5020_50201101_43_dialog_content = "¿Estás tratando de tomar Slice of Heaven para ti?",
  ui_story_5020_50201101_44_dialog_content = "Eso es correcto.",
  ui_story_5020_50201101_45_dialog_content = "Pero... Pero no es tuyo... Slice of Heaven es...",
  ui_story_5020_50201101_46_dialog_content = "¡Pertenece a la sacerdotisa, la que falleció!",
  ui_story_5020_50201101_47_dialog_content = "No me importa nada de eso. Lo necesito para proteger a las personas inocentes de Koufu-jou.",
  ui_story_5020_50201101_48_dialog_content = "¡Guau! ¿Cuándo te convertiste en el tipo de discursos grandiosos?",
  ui_story_5020_50201101_49_dialog_content = "¿Harías lo mismo si el maestro no odiara a esa sacerdotisa?",
  ui_story_5020_50201101_50_dialog_content = "(Estas hermanas son exactamente opuestas...)",
  ui_story_5020_50201101_51_dialog_content = "Ustedes dos... ¡Por favor, dejen de discutir!",
  ui_story_5020_50201101_52_dialog_content = "... ¿Ah?",
  ui_story_5020_50201101_53_dialog_content = "¿Mm...?",
  ui_story_5020_50201101_54_dialog_content = "Guau... ¿Está nevando?",
  ui_story_5020_50201101_55_dialog_content = "No, no nieve. Estos son...",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>flores de cerezo blancas</color>?",
  ui_story_5020_50201101_57_dialog_content = "Estos diminutos pétalos blancos caen tan suavemente... ¡Parecen copos de nieve!",
  ui_story_5020_50201101_58_dialog_content = "\"Los lugareños de Cloud Island prefieren las flores de cerezo regordetas y de colores brillantes...\"",
  ui_story_5020_50201101_59_dialog_content = "¡Eh, esto es completamente diferente de la guía!",
  ui_story_5020_50201101_60_dialog_content = "Este podría ser el único lugar en la Isla de las Nubes con este tipo de flores de cerezo...",
  ui_story_5020_50201101_61_dialog_content = "Estamos llegando al cementerio.",
  ui_story_5020_50201101_62_dialog_content = "Hmm... No es de extrañar que esté tan tranquilo aquí...",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201101_64_dialog_content = "Eh... De ninguna manera...",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>Gaaah!!</anim>",
  ui_story_5020_50201101_66_dialog_content = "¡No hay ningún lugar al que esas cosas no vayan!",
  ui_story_5020_50201101_67_dialog_content = "Bueno, es un cementerio, así que supongo que no es del todo inesperado...",
  ui_story_5020_50201101_68_dialog_content = "Basta de hablar. ¡Es hora de que lance algunos golpes!",
  ui_story_5020_50201201_1_dialog_content = "¡Torrente rápido!",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201201_3_dialog_content = "Uf... ¡Esas cosas son una molestia!",
  ui_story_5020_50201201_4_dialog_content = "Pero ya sabes lo que dicen, ¡no puedes sacar una zanahoria sin ensuciarte también!",
  ui_story_5020_50201201_5_dialog_content = "... ¿Quién dice eso, exactamente?",
  ui_story_5020_50201201_6_dialog_content = "¡Mi hermana jurada! ¡Tiene un dicho para cada ocasión y gana todas las discusiones en la familia Lin!",
  ui_story_5020_50201201_7_dialog_content = "¡Por supuesto, ella también gana todas las peleas!",
  ui_story_5020_50201201_8_dialog_content = "Me parece todo un personaje...",
  ui_story_5020_50201201_9_dialog_content = "Veo. No es de extrañar.",
  ui_story_5020_50201201_10_dialog_content = "¿Hmm? No es de extrañar qué? ¿No es de extrañar que sea tan genial?",
  ui_story_5020_50201201_11_dialog_content = "No es de extrañar que resultaras tan grosero.",
  ui_story_5020_50201201_12_dialog_content = "Es una pena ver que el entrenamiento del Maestro se desperdicia así.",
  ui_story_5020_50201201_13_dialog_content = "¿Qué fue eso? ¡Repitelo!",
  ui_story_5020_50201201_14_dialog_content = "PlayerName, ¿escuchas cómo habla con sus juniors?",
  ui_story_5020_50201201_15_dialog_content = "Bueno, Yao. Eso es suficiente.",
  ui_story_5020_50201201_16_dialog_content = "Tú también, Amemori. No tenías que burlarte de ella.",
  ui_story_5020_50201201_17_dialog_content = "¿Qué? ¡No estaba bromeando!",
  ui_story_5020_50201201_18_dialog_content = "¡¿Y qué si lo fueras?!",
  ui_story_5020_50201201_19_dialog_content = "¿Estás diciendo que me tienes demasiado miedo para burlarte de mí?",
  ui_story_5020_50201201_20_dialog_content = "(¡Oh, no, realmente no debería haber dicho nada!)",
  ui_story_5020_50201201_21_dialog_content = "Permítanme aclarar una cosa.",
  ui_story_5020_50201201_22_dialog_content = "No me iré de este cementerio sin Slice of Heaven.",
  ui_story_5020_50201201_23_dialog_content = "Puedes inventar tantas excusas como quieras...",
  ui_story_5020_50201201_24_dialog_content = "Pero al final, apenas podías recordar al maestro. De lo único que hablaste fue de esa hermana jurada tuya.",
  ui_story_5020_50201201_25_dialog_content = "Fui criado por el maestro.",
  ui_story_5020_50201201_26_dialog_content = "Debo conseguir Slice of Heaven para ayudar al maestro a derrotar a Fujikumo.",
  ui_story_5020_50201201_27_dialog_content = "(Aunque el maestro nunca me pidió que hiciera nada por ella...)",
  ui_story_5020_50201201_28_dialog_content = "¿A pesar de que la maestra no te contó su plan de prender fuego a toda la ciudad?",
  ui_story_5020_50201201_29_dialog_content = "Oh...",
  ui_story_5020_50201201_30_dialog_content = "¡La Maestra tiene sus razones!",
  ui_story_5020_50201201_31_dialog_content = "Por supuesto que sí. Pero, ¿cuánto sabes realmente sobre ella?",
  ui_story_5020_50201201_32_dialog_content = "¡¿?!",
  ui_story_5020_50201201_33_dialog_content = "Tú... ¿Recuerdas algo de ella que yo no sepa?",
  ui_story_5020_50201201_34_dialog_content = "... He compartido todo lo que sé contigo.",
  ui_story_5020_50201201_35_dialog_content = "Pero la persona que poseía Slice of Heaven ciertamente significaba mucho para dominar.",
  ui_story_5020_50201201_36_dialog_content = "...",
  ui_story_5020_50201201_37_dialog_content = "Sí... no lo entiendo.",
  ui_story_5020_50201201_37X_dialog_content = "A la Maestra le importa mucho su reputación... ¿Por qué se ensuciaría las manos?",
  ui_story_5020_50201201_38_dialog_content = "je. Es más...",
  ui_story_5020_50201201_39_dialog_content = "Estoy seguro de que la sacerdotisa era una persona muy importante. Puedo decir de mi memoria.",
  ui_story_5020_50201201_40_dialog_content = "¿Cómo puedes estar tan seguro?",
  ui_story_5020_50201201_41_dialog_content = "... Intuición!",
  ui_story_5020_50201201_42_dialog_content = "...",
  ui_story_5020_50201201_43_dialog_content = "¿Qué pasa con la cara? ¡Mi intuición nunca se equivoca!",
  ui_story_5020_50201201_44_dialog_content = "Puedo dar fe de ello.",
  ui_story_5020_50201201_45_dialog_content = "Nos guste o no, me quedo con Slice of Heaven.",
  ui_story_5020_50201201_46_dialog_content = "Seguro que me ayudará a recordar más cosas.",
  ui_story_5020_50201201_47_dialog_content = "¡Cosas del maestro!",
  ui_story_5020_50201201_48_dialog_content = "De todos modos, no estoy esperando ninguna ayuda de usted. ¡No te interpongas en mi camino!",
  ui_story_5020_50201201_49_dialog_content = "...",
  ui_story_5020_50201201_50_dialog_content = "... ¿Puaj?",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>Silbido...</color>",
  ui_story_5020_50201201_52_dialog_content = "¡Kunai!",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201201_54_dialog_content = "Yao, necesitarías diez de ustedes para tomarme por sorpresa.",
  ui_story_5020_50201201_55_dialog_content = "Jeje! ¡Así es!",
  ui_story_5020_50201201_55X_dialog_content = "Espera… Eso no suena bien…",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>¡Gaaah!</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "Puede que no quieras ayudarme, pero ahora mismo...",
  ui_story_5020_50201201_59_dialog_content = "¡Haaa!",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>Urgh...</anim>",
  ui_story_5020_50201201_61_dialog_content = "¡Nuestra prioridad debería ser deshacernos de estos viciosos fantasmas!",
  ui_story_5020_50201201_62_dialog_content = "je. Como si necesitara que me dijeras eso.",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>Jajaja...</anim>",
  ui_story_5020_50201202_2_dialog_content = "¡Mmm! ¡Pan comido!",
  ui_story_5020_50201202_3_dialog_content = "Manténganse alerta todos. Habrá más fantasmas vagando dentro del cementerio.",
  ui_story_5020_50201202_4_dialog_content = "Me colaré para echar un vistazo.",
  ui_story_5020_50201202_5_dialog_content = "¡Gracias!",
  ui_story_5020_50201202_6_dialog_content = "¡Ninjutsu para siempre!",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>Silbido... Silbido...</color>",
  ui_story_5020_50201202_8_dialog_content = "Mi corazón late con fuerza... Este silencio de muerte me está asustando.",
  ui_story_5020_50201202_9_dialog_content = "No tengas miedo. ¡No hay problema que no se pueda resolver con un puño!",
  ui_story_5020_50201202_10_dialog_content = "¿Mmm?",
  ui_story_5020_50201202_11_dialog_content = "... Amemori?",
  ui_story_5020_50201202_12_dialog_content = "Algo no está bien...",
  ui_story_5020_50201202_13_dialog_content = "¿De qué estás hablando? Amemori... ¿Estás bien?",
  ui_story_5020_50201202_14_dialog_content = "... Por favor entren todos.",
  ui_story_5020_50201202_15_dialog_content = "No hay un solo fantasma dentro del cementerio.",
  ui_story_5020_50201202_16_dialog_content = "¿Qué?",
  ui_story_5020_50201202_17_dialog_content = "Puedes bajar la guardia. Este lugar es absolutamente seguro.",
  ui_story_5020_50201202_18_dialog_content = "Todo lo que pude escuchar...",
  ui_story_5020_50201202_19_dialog_content = "No era más que el sonido de los cerezos en flor al caer.",
  ui_story_5020_50201202_20_dialog_content = "No solo florecen como otras flores...",
  ui_story_5020_50201202_21_dialog_content = "Extienden sus pétalos lentamente, soportando la mezcla de dolor y alegría que provoca su florecimiento.",
  ui_story_5020_50201202_22_dialog_content = "Y cuando llega el momento, se marchitan silenciosamente en silencio.",
  ui_story_5020_50201202_23_dialog_content = "Las flores de cerezo soportan todo con paciencia. Ahora entiendo por qué el maestro los ama tanto.",
  ui_story_5020_50201202_24_dialog_content = "Oh, wow... ¡Mi guía no menciona nada de esto!",
  ui_story_5020_50201202_25_dialog_content = "No sé por qué, pero me entristece pensar en...",
  ui_story_5020_50201202_26_dialog_content = "Eh... Eso es extraño...",
  ui_story_5020_50201202_27_dialog_content = "Este lugar no parece desierto después de todo...",
  ui_story_5020_50201202_28_dialog_content = "¡Mira, PlayerName!",
  ui_story_5020_50201202_29_dialog_content = "Ah...",
  ui_story_5020_50201202_30_dialog_content = "Alguien ha abierto un camino en los pétalos de cerezo caídos.",
  ui_story_5020_50201202_31_dialog_content = "... ¿Alguien estuvo aquí antes que nosotros?",
  ui_story_5020_50201202_32_dialog_content = "¡Oh, no! Pedazo de cielo...",
  ui_story_5020_50201202_33_dialog_content = "Ah...",
  ui_story_5020_50201202_34_dialog_content = "¡Guau! Eso es...",
  ui_story_5020_50201202_35_dialog_content = "No es de extrañar que se llame una espada legendaria para matar fantasmas...",
  ui_story_5020_50201202_36_dialog_content = "Su curva es suave... Y la hoja es un clásico puro...",
  ui_story_5020_50201202_37_dialog_content = "Incluso después de tantos años, todavía está en perfectas condiciones...",
  ui_story_5020_50201202_38_dialog_content = "¿Pero quién hizo todo esto?",
  ui_story_5020_50201202_39_dialog_content = "La forma en que se coloca Slice of Heaven...",
  ui_story_5020_50201202_40_dialog_content = "¡Parece una especie de ofrenda!",
  ui_story_5020_50201202_41_dialog_content = "¡Ay! PlayerName, ¡Mira!",
  ui_story_5020_50201202_42_dialog_content = "Hay algo debajo de Slice of Heaven...",
  ui_story_5020_50201202_43_dialog_content = "... Déjame echar un vistazo primero.",
  ui_story_5020_50201202_44_dialog_content = "Aunque no es probable que alguien coloque una trampa aquí, es mejor prevenir que curar...",
  ui_story_5020_50201202_45_dialog_content = "¡Guau! ¿Qué estás haciendo?",
  ui_story_5020_50201202_46_dialog_content = "¿...?",
  ui_story_5020_50201202_47_dialog_content = "¿Quién te crees que eres para empuñar Slice of Heaven?",
  ui_story_5020_50201202_48_dialog_content = "... Por favor. No tengo tiempo para esto ahora.",
  ui_story_5020_50201202_49_dialog_content = "Oye, PlayerName!",
  ui_story_5020_50201202_50_dialog_content = "¿Qué? Uh, por favor déjame fuera de tu argumento...",
  ui_story_5020_50201202_51_dialog_content = "Ve a recogerlo.",
  ui_story_5020_50201202_52_dialog_content = "¿Y-Yo?",
  ui_story_5020_50201202_53_dialog_content = "...",
  ui_story_5020_50201202_54_dialog_content = "si eso va a cerrar Yao arriba, estoy bien con eso.",
  ui_story_5020_50201202_55_dialog_content = "PlayerName, por favor no me hagas perder el tiempo.",
  ui_story_5020_50201202_56_dialog_content = "...Ya veo.",
  ui_story_5020_50201202_57_dialog_content = "¿Mmm?",
  ui_story_5020_50201202_58_dialog_content = "Aquí...",
  ui_story_5020_50201202_59_dialog_content = "Esa cosa al lado de Slice of Heaven es...",
  ui_story_5020_50201202_60_dialog_content = "A... <color=#FFB400>computadora portátil</color>?",
  ui_story_5020_50201202_61_dialog_content = "Pertenece a...",
  ui_story_5020_50201202_62_dialog_content = "... <color=#FFB400>Tsuki</color>?",
  ui_story_5020_50201202_63_dialog_content = "¡¿?!",
  ui_story_5020_50201202_64_dialog_content = "... Ese es su nombre.",
  ui_story_5020_50201202_65_dialog_content = "Ese es el cuaderno de la sacerdotisa anterior.",
  ui_story_5020_50201202_66_dialog_content = "Parece estar en perfectas condiciones. Apuesto a que no ha estado en el cementerio por mucho tiempo.",
  ui_story_5020_50201202_67_dialog_content = "El último visitante podría haberlo dejado aquí.",
  ui_story_5020_50201202_68_dialog_content = "¿Quién diablos vino aquí antes que nosotros?",
  ui_story_5020_50201202_69_dialog_content = "...",
  ui_story_5020_50201202_70_dialog_content = "no puedo estar seguro...",
  ui_story_5020_50201202_71_dialog_content = "Quienquiera que sea esa persona, existe un estrecho vínculo entre él y la sacerdotisa anterior.",
  ui_story_5020_50201202_72_dialog_content = "Y este cuaderno...",
  ui_story_5020_50201202_73_dialog_content = "¡Lo leeremos!",
  ui_story_5020_50201202_74_dialog_content = "Debe haber información sobre el pasado del maestro.",
  ui_story_5020_50201202_75_dialog_content = "¡Debe haber algo que he olvidado!",
  ui_story_5020_50201202_76_dialog_content = "Vamos a abrirlo con mucho cuidado, PlayerName.",
  ui_story_5020_50201202_77_dialog_content = "¡Pase primero a la última entrada! ¡Darse prisa!",
  ui_story_5020_50201202_78_dialog_content = "Bien bien. Acércate...",
  ui_story_5020_50201301_1_dialog_content = "Su Santidad la Sacerdotisa, ¿está lista?",
  ui_story_5020_50201301_2_dialog_content = "Sí... Pero por favor espera.",
  ui_story_5020_50201301_3_dialog_content = "Por favor llévale esto al sacerdote del festival...",
  ui_story_5020_50201301_4_dialog_content = "Ahórrales un viaje a los sirvientes, Tsuki.",
  ui_story_5020_50201301_5_dialog_content = "Tengo esto.",
  ui_story_5020_50201301_6_dialog_content = "Ah... Kubou-sama, pensé que ya estabas en el Festival Kasuga.",
  ui_story_5020_50201301_7_dialog_content = "... Hay un pequeño problema en el festival.",
  ui_story_5020_50201301_8_dialog_content = "Regresé por el espejo de la nube.",
  ui_story_5020_50201301_9_dialog_content = "... ¿Qué pasó?",
  ui_story_5020_50201301_10_dialog_content = "No te preocupes por eso. Concéntrate en tu ceremonia.",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>Explosión... sonido...</color>",
  ui_story_5020_50201301_12_dialog_content = "Ahh...",
  ui_story_5020_50201301_13_dialog_content = "¿Qué es ese sonido afuera?",
  ui_story_5020_50201301_14_dialog_content = "Tsuki, no te preocupes...",
  ui_story_5020_50201301_15_dialog_content = "Je...",
  ui_story_5020_50201301_16_dialog_content = "...",
  ui_story_5020_50201301_17_dialog_content = "¿No es esta la traidora de la Isla de las Nubes, la Sacerdotisa?",
  ui_story_5020_50201301_18_dialog_content = "Mírate, tan bien vestida. No quiero que me llamen matón.",
  ui_story_5020_50201301_19_dialog_content = "Hmm... Pero el Festival Kasuga de este año no va a suceder.",
  ui_story_5020_50201301_20_dialog_content = "¿Exactamente, que es lo que quieres?",
  ui_story_5020_50201301_21_dialog_content = "... Tsuki!",
  ui_story_5020_50201301_22_dialog_content = "¿Oh?",
  ui_story_5020_50201301_23_dialog_content = "Eso es muy sencillo...",
  ui_story_5020_50201301_24_dialog_content = "Al menos eres más inteligente que Fujikumo.",
  ui_story_5020_50201301_25_dialog_content = "Quiero poner fin al Festival Kasuga.",
  ui_story_5020_50201301_26_dialog_content = "¡Debe detenerse cualquier cosa que fomente las fuerzas de la isla principal!",
  ui_story_5020_50201301_27_dialog_content = "Un don nadie extralimitado. Tsuki, no pierdas tu tiempo con ellos...",
  ui_story_5020_50201301_28_dialog_content = "Entendido.",
  ui_story_5020_50201301_29_dialog_content = "No querrás ver cómo se difunden la cultura y las costumbres de la isla principal.",
  ui_story_5020_50201301_30_dialog_content = "Hasta cierto punto, ¡sí!",
  ui_story_5020_50201301_31_dialog_content = "Pero hemos entrado en una nueva era desde el día en que Cloud Island abrió su puerto a la isla principal.",
  ui_story_5020_50201301_32_dialog_content = "Es perfectamente normal que algunos de nosotros nos hayamos adaptado rápidamente a las nuevas reglas, mientras que otros se niegan a aceptar la realidad.",
  ui_story_5020_50201301_33_dialog_content = "Si Cloud Island pudiera tener una voz para expresar sus propios sentimientos, estoy seguro de que se maravillaría de lo rápido que han cambiado las cosas...",
  ui_story_5020_50201301_34_dialog_content = "Pero mientras Koufu-jou siga en pie, tú y yo compartiremos esta tierra juntos.",
  ui_story_5020_50201301_35_dialog_content = "Podrías evitar que se lleve a cabo el Festival Kasuga. Podrías deshacerte de un general. Pero nada de esto cambiaría el futuro de la isla.",
  ui_story_5020_50201301_36_dialog_content = "...",
  ui_story_5020_50201301_37_dialog_content = "En lugar de poner fin al festival, te aconsejo que pienses en...",
  ui_story_5020_50201301_38_dialog_content = "Cómo convertir el Festival Kasuga en tu propia celebración.",
  ui_story_5020_50201301_39_dialog_content = "...",
  ui_story_5020_50201301_40_dialog_content = "Su Santidad la sacerdotisa, la multitud no causó más disturbios en el festival.",
  ui_story_5020_50201301_41_dialog_content = "Jejeje... ¿Dónde está su comandante?",
  ui_story_5020_50201301_42_dialog_content = "¿Te refieres a la mujer Nagi?",
  ui_story_5020_50201301_43_dialog_content = "Se desconoce su paradero, pero todos siguen buscándola.",
  ui_story_5020_50201301_43X_dialog_content = "Si es necesario, enviaremos más tropas...",
  ui_story_5020_50201301_44_dialog_content = "Eso no será necesario.",
  ui_story_5020_50201301_45_dialog_content = "Si organizan otra revuelta, Kubou-sama estaría preocupado.",
  ui_story_5020_50201301_46_dialog_content = "Deja que Nagi disfrute de los cerezos en flor en el Festival Kasuga.",
  ui_story_5020_50201301_47_dialog_content = "Su Santidad la sacerdotisa... Por favor, perdóneme si me he pasado de la raya...",
  ui_story_5020_50201301_48_dialog_content = "Lo que dijiste antes parecía haber molestado a Kubou-sama.",
  ui_story_5020_50201301_49_dialog_content = "Ahh... Tienes razón.",
  ui_story_5020_50201301_49X_dialog_content = "Kubou-sama aún se habría ocupado de ellos incluso si me hubiera ido sin decir nada.",
  ui_story_5020_50201301_50_dialog_content = "Supongo que en este día de alegría y celebración, no quería...",
  ui_story_5020_50201301_51_dialog_content = "Ver Kubou-sama tener una ola de asesinatos.",
  ui_story_5020_50201301_52_dialog_content = "... ¿Una ola de asesinatos?",
  ui_story_5020_50201301_53_dialog_content = "Sí, era bastante obvio cuando Kubou-sama regresó al castillo principal por el espejo de nubes...",
  ui_story_5020_50201301_54_dialog_content = "Tenía la intención de manipular fantasmas con el espejo de nubes para reprimir a esos rebeldes.",
  ui_story_5020_50201301_55_dialog_content = "Esto realmente no es algo bueno...",
  ui_story_5020_50201301_56_dialog_content = "¿Qué te preocupa? ¡Tienes Slice of Heaven, la espada que mata fantasmas!",
  ui_story_5020_50201301_57_dialog_content = "Podrías matarlos a todos después.",
  ui_story_5020_50201301_58_dialog_content = "...",
  ui_story_5020_50201301_59_dialog_content = "Slice of Heaven y Cloud Mirror están bendecidos por los dioses, uno para expulsar espíritus malignos y el otro para exorcizar fantasmas...",
  ui_story_5020_50201301_60_dialog_content = "Está bien usarlos para la ceremonia, pero nunca se supone que sean herramientas de dominación...",
  ui_story_5020_50201301_61_dialog_content = "Me preocupa profundamente que se puedan desencadenar otras fuerzas... Algo que la gente común no puede manejar.",
  ui_story_5020_50201301_62_dialog_content = "¿Pero no es este tu deber?",
  ui_story_5020_50201301_63_dialog_content = "Empuñar Slice of Heaven contra todos los espíritus malignos siempre ha sido el deber de una sacerdotisa de la isla principal durante generaciones.",
  ui_story_5020_50201301_64_dialog_content = "Esto es como clavar tu escudo con tu propia lanza.",
  ui_story_5020_50201301_65_dialog_content = "Slice of Heaven mata, y Cloud Mirror los devuelve a la vida...",
  ui_story_5020_50201301_66_dialog_content = "Cuando estas dos fuerzas están en equilibrio, la voluntad del portador se vuelve extremadamente importante.",
  ui_story_5020_50201301_67_dialog_content = "Pero no puedo cambiar la mente de Kubou-sama en absoluto...",
  ui_story_5020_50201301_68_dialog_content = "Solo soy otra herramienta para ayudar a Cloud Island a progresar hacia una paz duradera.",
  ui_story_5020_50201301_69_dialog_content = "Su Santidad la Sacerdotisa... Yo...",
  ui_story_5020_50201301_70_dialog_content = "No creo que te esté siguiendo!",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_72_dialog_content = "Jejeje ¡Mirar! ¡Kubou-sama está en un palanquín adornado con tantas campanas!",
  ui_story_5020_50201301_73_dialog_content = "¡Ah... Kubou-sama!",
  ui_story_5020_50201301_74_dialog_content = "Su Santidad la sacerdotisa, si pudiera disculparme... ¡Debo ir y proteger a Kubou-sama!",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_76_dialog_content = "¡No me persigas! ¡no!",
  ui_story_5020_50201301_77_dialog_content = "Uf... Chica mala. ¡Devuélvele la Kagura Bell a Tsuki!",
  ui_story_5020_50201301_78_dialog_content = "¡Hermana Tsuki, persígueme! ¡Te lo devolveré si puedes conseguirme!",
  ui_story_5020_50201301_79_dialog_content = "Tú... ¿Cuántas veces tengo que decírtelo? ¡No puede dirigirse a Su Santidad por su nombre personal!",
  ui_story_5020_50201301_80_dialog_content = "¡Bien, hermana Tsuki!",
  ui_story_5020_50201301_81_dialog_content = "No te preocupes por eso, Nagi. Ella es solo una niña.",
  ui_story_5020_50201301_82_dialog_content = "Yao solo me llama su hermana porque le gusto.",
  ui_story_5020_50201301_83_dialog_content = "... Pero te gusta una hermana para mí. Yao es su hijo adoptivo.",
  ui_story_5020_50201301_84_dialog_content = "Si ella también te llama hermana, ¿en qué me convierte?",
  ui_story_5020_50201301_85_dialog_content = "Jejeje.",
  ui_story_5020_50201301_86_dialog_content = "¡No es gracioso!",
  ui_story_5020_50201301_87_dialog_content = "Bien. Sé Yao es travieso, pero Amemori es una buena chica",
  ui_story_5020_50201301_88_dialog_content = "Te pedí que me ayudaras a cuidar de ellos dos y me diste la vuelta. Amemori en una versión en miniatura de ti.",
  ui_story_5020_50201301_89_dialog_content = "Hmm... Ella realmente está dotada.",
  ui_story_5020_50201301_90_dialog_content = "No puedo evitar enseñarle algunas cosas.",
  ui_story_5020_50201301_91_dialog_content = "... Nagi!",
  ui_story_5020_50201301_92_dialog_content = "No te preocupes. No les enseñaré nada de eso sin tu permiso.",
  ui_story_5020_50201301_93_dialog_content = "Además, creo Amemori ya lleva mucho peso sobre sus pequeños hombros...",
  ui_story_5020_50201301_94_dialog_content = "A una edad tan joven, ella ya está actuando deliberadamente como severamente fría y apática...",
  ui_story_5020_50201301_95_dialog_content = "Sé con certeza que aún no tiene la edad para reprimir sentimientos.",
  ui_story_5020_50201301_96_dialog_content = "Así es.",
  ui_story_5020_50201301_97_dialog_content = "Desde que los acogí, los he estado criando como si fueran míos.",
  ui_story_5020_50201301_98_dialog_content = "Todavía no se acerca a mí y no muestra interés en jugar con Yao...",
  ui_story_5020_50201301_99_dialog_content = "Pero por alguna razón, realmente le gustas, Nagi.",
  ui_story_5020_50201301_100_dialog_content = "¿Le gusto a ella?",
  ui_story_5020_50201301_101_dialog_content = "Si. No habla mucho pero le encanta seguirte e imitar todo lo que haces...",
  ui_story_5020_50201301_102_dialog_content = "¡Mirar! Incluso su flor favorita es la misma que la tuya.",
  ui_story_5020_50201301_103_dialog_content = "¿Qué clase de niña puede entender la belleza de las flores de cerezo que caen?",
  ui_story_5020_50201301_104_dialog_content = "¿Ah?",
  ui_story_5020_50201301_105_dialog_content = "Ah... Las flores de cerezo ya están cayendo.",
  ui_story_5020_50201301_106_dialog_content = "<size=33>... El tiempo vuela. Pronto me iré a la isla principal.</size>",
  ui_story_5020_50201301_107_dialog_content = "¿Qué fue eso?",
  ui_story_5020_50201301_108_dialog_content = "Nada.",
  ui_story_5020_50201301_109_dialog_content = "Nagi, tengo que irme de Cloud Island por un tiempo.",
  ui_story_5020_50201301_110_dialog_content = "Cuando regrese, serás el verdadero comandante de las fuerzas locales.",
  ui_story_5020_50201301_111_dialog_content = "¿Adónde vas? ¿Y para qué? ¿Por qué no dijiste nada antes?",
  ui_story_5020_50201301_112_dialog_content = "... ¿Es por eso que estás confiando Amemori y Yao a mi cuidado?",
  ui_story_5020_50201301_113_dialog_content = "Jejeje... Te han ensuciado la cabeza y la cara con mugre...",
  ui_story_5020_50201301_114_dialog_content = "Pero no me odias, ¿verdad?",
  ui_story_5020_50201301_115_dialog_content = "... ¡Por supuesto que no!",
  ui_story_5020_50201301_116_dialog_content = "Esto es realmente encantador...",
  ui_story_5020_50201301_117_dialog_content = "Espero que las cosas sigan así...",
  ui_story_5020_50201301_118_dialog_content = "¡Hermana! Que esta pasando? ¿Por qué alguna vez...",
  ui_story_5020_50201301_119_dialog_content = "No te preocupes.",
  ui_story_5020_50201301_120_dialog_content = "No puedo decirte mucho por el momento. Pero confía en mí. Tengo mis razones.",
  ui_story_5020_50201301_121_dialog_content = "Cuando estoy fuera, puedes enseñarles la canción que solíamos cantar.",
  ui_story_5020_50201301_122_dialog_content = "Vamos. ¡No me digas que te has olvidado!",
  ui_story_5020_50201301_123_dialog_content = "¡Nunca!",
  ui_story_5020_50201301_124_dialog_content = "Esa canción... es bastante perfecta para esta temporada.",
  ui_story_5020_50201301_125_dialog_content = "Escoge una flor roja para la dama...",
  ui_story_5020_50201301_126_dialog_content = "Los pétalos caen como la nieve sobre un trozo de jade...",
  ui_story_5020_50201301_127_dialog_content = "Nagi, realmente hay un pétalo de cereza en tu frente.",
  ui_story_5020_50201301_128_dialog_content = "Aw... Hermana, ayúdame...",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201401_1_dialog_content = "...",
  ui_story_5020_50201401_2_dialog_content = "...",
  ui_story_5020_50201401_3_dialog_content = "La hermana sacerdotisa registró tal historia.",
  ui_story_5020_50201401_4_dialog_content = "Ahora entiendo por qué me sentí tan cerca de Rinne en el momento en que la vi...",
  ui_story_5020_50201401_5_dialog_content = "Todo tiene sentido ahora.",
  ui_story_5020_50201401_6_dialog_content = "Una sacerdotisa que pareces haber conocido antes... Y las campanas familiares que suenan en lo profundo de tu cabeza...",
  ui_story_5020_50201401_7_dialog_content = "¡Esta es la memoria perdida de Yao!",
  ui_story_5020_50201401_8_dialog_content = "Pero yo...",
  ui_story_5020_50201401_9_dialog_content = "... Yao?",
  ui_story_5020_50201401_10_dialog_content = "Mi corazón me duele...",
  ui_story_5020_50201401_11_dialog_content = "¿No debería ser algo feliz cuando uno encuentra su memoria perdida?",
  ui_story_5020_50201401_12_dialog_content = "Todavía no puedo entender por qué la decisión del maestro.",
  ui_story_5020_50201401_13_dialog_content = "Pero, ¿qué haría yo si estuviera en la posición de maestro?",
  ui_story_5020_50201401_14_dialog_content = "La sacerdotisa que regresó de la isla principal fue ampliamente considerada una traidora imperdonable de la Isla de las Nubes...",
  ui_story_5020_50201401_15_dialog_content = "Se suponía que esto era una simple elección entre el bien y el mal, pero...",
  ui_story_5020_50201401_16_dialog_content = "¿Por qué estoy aún más triste que el maestro en ese entonces?",
  ui_story_5020_50201401_17_dialog_content = "... Demasiadas cosas en este mundo no son tan simples como el blanco o el negro.",
  ui_story_5020_50201401_18_dialog_content = "Es lo mismo desde Astra hasta el Lejano Oriente...",
  ui_story_5020_50201401_19_dialog_content = "Las personas tienen diferentes posiciones y creencias y experimentan impotencia por varias razones.",
  ui_story_5020_50201401_20_dialog_content = "... ¿Es eso así?",
  ui_story_5020_50201401_21_dialog_content = "Y al final de la historia...",
  ui_story_5020_50201401_22_dialog_content = "Déjame ver... Debería estar por aquí...",
  ui_story_5020_50201401_22X_dialog_content = "¿Ah?",
  ui_story_5020_50201401_23_dialog_content = "Hay una <color=#FFB400>letra</color> entre las paginas!",
  ui_story_5020_50201401_24_dialog_content = "ah Todavía está sellado.",
  ui_story_5020_50201401_25_dialog_content = "Para la próxima sacerdotisa...",
  ui_story_5020_50201401_26_dialog_content = "¡Guau! la sacerdotisa se fue Rinne ¡una carta!",
  ui_story_5020_50201401_27_dialog_content = "PlayerName, llevemos esto a Rinne.",
  ui_story_5020_50201401_28_dialog_content = "Hmm... Verás, ¡el pasaje que estoy buscando está justo aquí al comienzo de la nota!",
  ui_story_5020_50201401_29_dialog_content = "¿Qué quiso decir la hermana sacerdotisa cuando se despidió del maestro antes de su partida?",
  ui_story_5020_50201401_30_dialog_content = "¿Ya sabía que iba a convertirse en sacerdotisa?",
  ui_story_5020_50201401_31_dialog_content = "¿Ya previó un futuro lleno de odio por parte del maestro y todos los residentes de Cloud Island?",
  ui_story_5020_50201401_32_dialog_content = "Después de todo... Fue su propia elección.",
  ui_story_5020_50201401_33_dialog_content = "¿Fue realmente su propia elección?",
  ui_story_5020_50201401_34_dialog_content = "Hablando de eso... Mmm...",
  ui_story_5020_50201401_35_dialog_content = "Amemori! ¡Sabía que la sacerdotisa no era una mala persona!",
  ui_story_5020_50201401_36_dialog_content = "¡Era una guerrera que realmente se preocupaba por la paz y la seguridad de Cloud Island!",
  ui_story_5020_50201401_37_dialog_content = "... Amemori?",
  ui_story_5020_50201401_38_dialog_content = "Amemori, ¿Estás llorando?",
  ui_story_5020_50201401_39_dialog_content = "No.",
  ui_story_5020_50201401_40_dialog_content = "(¡Por favor, no expongas su dolor y su pena de manera tan directa!)",
  ui_story_5020_50201401_41_dialog_content = "Nunca antes había visto al maestro desde este ángulo...",
  ui_story_5020_50201401_42_dialog_content = "Nunca escuché al maestro hablar de mí frente a otros.",
  ui_story_5020_50201401_43_dialog_content = "Pensé que era como el maestro.",
  ui_story_5020_50201401_44_dialog_content = "Incluso el Wisp hizo tales comentarios.",
  ui_story_5020_50201401_45_dialog_content = "Pero solo el maestro puede comentar sobre esto.",
  ui_story_5020_50201401_46_dialog_content = "Después de tantos años de cultivo, la maestra ha templado su cuerpo y su corazón más que los de Fujikumo...",
  ui_story_5020_50201401_47_dialog_content = "Era tan fuerte que ninguna fuerza bruta podía dañarla, incluido el fuerte golpe de Fujikumo...",
  ui_story_5020_50201401_48_dialog_content = "Ella desafió todos los golpes, la admiración y los chismes...",
  ui_story_5020_50201401_49_dialog_content = "Pero no pudo soportar el suave empujón del moribundo Tsuki, que la envió al suelo sellado.",
  ui_story_5020_50201401_50_dialog_content = "Cuando el maestro me volvió a ver una década después, las primeras palabras que dijo...",
  ui_story_5020_50201401_51_dialog_content = "A veces, finges ser tan genial y despiadado... Y, sin embargo, no puedes superar tu compasión y cobardía hacia los demás.",
  ui_story_5020_50201401_52_dialog_content = "Para vivir en un mundo como este, es mejor que abandones tus emociones por completo.",
  ui_story_5020_50201401_53_dialog_content = "Creo que las palabras también eran para ella.",
  ui_story_5020_50201401_54_dialog_content = "... ¿Qué estás tratando de decir? Por supuesto que no eres lo mismo que maestro.",
  ui_story_5020_50201401_55_dialog_content = "Ya sabía esto cuando vi al maestro por primera vez.",
  ui_story_5020_50201401_56_dialog_content = "¿Qué?",
  ui_story_5020_50201401_57_dialog_content = "Dejame decirte mas. Tos...",
  ui_story_5020_50201401_58_dialog_content = "El Maestro sabe claramente lo que quiere.",
  ui_story_5020_50201401_59_dialog_content = "No solo maestro. Lo mismo hizo la hermana sacerdotisa...",
  ui_story_5020_50201401_60_dialog_content = "Ambos sabían lo que debían hacer en este momento.",
  ui_story_5020_50201401_61_dialog_content = "Entonces, Amemori... Si tuvieras que dejar de lado la influencia del Maestro y toda la presión que te pones a ti mismo...",
  ui_story_5020_50201401_62_dialog_content = "que sera <color=#FFB400>tu elección</color> ¿ser?",
  ui_story_5020_50201401_63_dialog_content = "¡¿...?!",
  ui_story_5020_50201401_64_dialog_content = "Dejando todo eso de lado, yo...",
  ui_story_5020_50201401_65_dialog_content = "No lo sé...",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>Ruido sordo...</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>¡Pum... Pum!</color>",
  ui_story_5020_50201401_68_dialog_content = "¡Guau! ¿Qué es ese sonido?",
  ui_story_5020_50201401_69_dialog_content = "<color=#FFB400>Taiko</color>... ¡Este es el taiko de Momo y Anzu!",
  ui_story_5020_50201401_70_dialog_content = "¿Pero por qué? Koufu-jou ya está en un estado tan caótico...",
  ui_story_5020_50201401_71_dialog_content = "es una señal Rinne ¡está en peligro!",
  ui_story_5020_50201401_72_dialog_content = "Rinne!",
  ui_story_5020_50201401_73_dialog_content = "¿Dónde está?",
  ui_story_5020_50201401_74_dialog_content = "... ¡Enviaré el Wisp para ayudar!",
  ui_story_5020_50201401_75_dialog_content = "¡Supongo que ya no necesitaremos esto!",
  ui_story_5020_50201401_75X_dialog_content = "Rinne ha estado con el Wisp desde Rinne nos dejó.",
  ui_story_5020_50201401_76_dialog_content = "Supongo que están peleando una nueva batalla juntos.",
  ui_story_5020_50201401_77_dialog_content = "¿Juntos? ¿Cómo sucedió eso?",
  ui_story_5020_50201401_78_dialog_content = "Amemori... A veces, tu única opción sigue siendo una opción.",
  ui_story_5020_50201401_79_dialog_content = "¡En este momento crucial, debes saber lo que realmente quieres hacer!",
  ui_story_5020_50201401_80_dialog_content = "...",
  ui_story_5020_50201401_81_dialog_content = "Hacia el puerto.",
  ui_story_5020_50201401_82_dialog_content = "Yao, Dame tu mano.",
  ui_story_5020_50201401_83_dialog_content = "Dado que esto lleva nuestra memoria desde hace diez años, usemos esto para llegar a una conclusión.",
  ui_story_5020_50201401_84_dialog_content = "¡Mmm! ¡Grandes mentes piensan igual!",
  ui_story_5020_50201401_85_dialog_content = "Vamos, siguiendo el taiko. Hacia el <color=#FFB400>Puerto</color>!",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>En una calle de la ciudad del castillo de Koufu-jou</color>",
  ui_story_5020_50201401_87_dialog_content = "¡Apurarse! ¡Mantenga!",
  ui_story_5020_50201401_88_dialog_content = "Sigue este río hacia abajo y llegaremos al puerto.",
  ui_story_5020_50201401_89_dialog_content = "¡Darse prisa! ¡Debemos retirarnos rápidamente!",
  ui_story_5020_50201401_90_dialog_content = "La gente del puerto te pondrá a salvo.",
  ui_story_5020_50201401_91_dialog_content = "¡Huye del castillo principal de Koufu-jou, tan lejos como puedas!",
  ui_story_5020_50201401_92_dialog_content = "Esto es una locura...",
  ui_story_5020_50201401_93_dialog_content = "Las tropas del excomandante han unido fuerzas con la sacerdotisa del general...",
  ui_story_5020_50201401_93X_dialog_content = "... ¡¿Eh?!",
  ui_story_5020_50201401_94_dialog_content = "¡mi trasero!",
  ui_story_5020_50201401_95_dialog_content = "¡Cuida tu lenguaje! ¡No será la empuñadura la próxima vez!",
  ui_story_5020_50201401_96_dialog_content = "Padre... ¡Vamos con la hermana sacerdotisa! Todos nos miran...",
  ui_story_5020_50201401_97_dialog_content = "El fuego sigue ardiendo... No quiero morir...",
  ui_story_5020_50201401_98_dialog_content = "¿Por qué debemos seguirla?",
  ui_story_5020_50201401_99_dialog_content = "Ella es una traidora de la isla. ¡Nos venderá a la isla principal!",
  ui_story_5020_50201401_100_dialog_content = "¡¿Eso significa que habrá cien Fujikumos esperando para torturarnos?!",
  ui_story_5020_50201401_100X_dialog_content = "... ¡¡Nooo!!",
  ui_story_5020_50201401_101_dialog_content = "¡Ay... Errrr! Mi hombro...",
  ui_story_5020_50201401_102_dialog_content = "¡Padre!",
  ui_story_5020_50201401_103_dialog_content = "¡Lacayos armados! ¿Estás evacuando a los residentes de Cloud Island o ayudando a destruir nuestra isla?",
  ui_story_5020_50201401_104_dialog_content = "¿Ah?",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>Gaa... ¡¡Gaaaaahh!!</anim>",
  ui_story_5020_50201401_106_dialog_content = "Fantasmas... Hay fantasmas en Sakai...",
  ui_story_5020_50201401_107_dialog_content = "Quédate con el grupo. ¡No entres en pánico!",
  ui_story_5020_50201401_108_dialog_content = "Sacerdotisa, tú lideras el camino. ¡Yo traeré la retaguardia!",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>¡Gaaah!</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>¡Gaaah!</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "¡Hermanos, saquen sus armas!",
  ui_story_5020_50201401_113_dialog_content = "¡Corta estos espíritus inmundos!",
  ui_story_5020_50201401_114_dialog_content = "¡Haaa!",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>Cerca del puerto de Koufu-jou</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>¡Pum... Pum!</color>",
  ui_story_5020_50201501_3_dialog_content = "Tanta gente... ¿Dónde diablos está Rinne?",
  ui_story_5020_50201501_4_dialog_content = "¡Diablos!",
  ui_story_5020_50201501_5_dialog_content = "Rinne!",
  ui_story_5020_50201501_6_dialog_content = "Rinne! ¿Puedes oírme?",
  ui_story_5020_50201501_7_dialog_content = "... Yao?",
  ui_story_5020_50201501_8_dialog_content = "Yao!",
  ui_story_5020_50201501_9_dialog_content = "¡Ay! Y Amemori, Vice, y PlayerName!",
  ui_story_5020_50201501_10_dialog_content = "¡Has oído el taiko!",
  ui_story_5020_50201501_11_dialog_content = "PlayerName tengo oídos afilados! Vinimos lo más rápido que pudimos.",
  ui_story_5020_50201501_12_dialog_content = "¿Cómo va todo? ¿Estás herido?",
  ui_story_5020_50201501_13_dialog_content = "Estoy bien. La mayoría de los residentes de Koufu-jou han sido evacuados.",
  ui_story_5020_50201501_14_dialog_content = "El Wisp se ha marchado en barco con unos civiles...",
  ui_story_5020_50201501_15_dialog_content = "¿Y usted? ¿Te hicieron pasar un mal rato?",
  ui_story_5020_50201501_16_dialog_content = "Jejeje. Es bueno saber que te preocupas por mí, Yao.",
  ui_story_5020_50201501_17_dialog_content = "No te preocupes. Estoy bien. ¿Cómo están todos?",
  ui_story_5020_50201501_18_dialog_content = "Tantos de nosotros juntos, ¡nada malo podría pasar! PlayerName, rápidamente. Show <color=#FFB400>eso</color> ¡a ella!",
  ui_story_5020_50201501_19_dialog_content = "¿Mmm?",
  ui_story_5020_50201501_20_dialog_content = "¿Eso? ¡Ay! Ahora recuerdo.",
  ui_story_5020_50201501_21_dialog_content = "Rinne, Esto es para ti.",
  ui_story_5020_50201501_22_dialog_content = "¡Ay! ¿Una carta en un cuaderno?",
  ui_story_5020_50201501_23_dialog_content = "¿Esto es para mi? Pero creo que no conozco a nadie con este nombre...",
  ui_story_5020_50201501_24_dialog_content = "Tsuki es la sacerdotisa anterior de Koufu-jou.",
  ui_story_5020_50201501_25_dialog_content = "...Ya veo.",
  ui_story_5020_50201501_26_dialog_content = "Para la próxima sacerdotisa...",
  ui_story_5020_50201501_27_dialog_content = "Decido escribir algo mientras espero.",
  ui_story_5020_50201501_28_dialog_content = "Me siento inquieto por el futuro que no viviré para ver...",
  ui_story_5020_50201501_29_dialog_content = "Cuanto más pienso, más me preocupo por ti, mi sucesor.",
  ui_story_5020_50201501_30_dialog_content = "No es justo que acepte este puesto sin un mentor principal.",
  ui_story_5020_50201501_31_dialog_content = "Ya hay tantas cosas injustas e injustas que vienen con este estatus de sacerdotisa.",
  ui_story_5020_50201501_32_dialog_content = "No sé en qué temporada abrirás esta carta en la Isla de las Nubes...",
  ui_story_5020_50201501_33_dialog_content = "Cloud Island es bien conocida por sus flores de cerezo que florecen como nubes rosadas—",
  ui_story_5020_50201501_33X_dialog_content = "Y caen como la nieve—",
  ui_story_5020_50201501_34_dialog_content = "Para la mayoría de los residentes de la Isla de las Nubes, las sacerdotisas somos hermosas pero transitorias como los cerezos en flor.",
  ui_story_5020_50201501_35_dialog_content = "Pero para mí, la sacerdotisa de la Isla de las Nubes debe brillar como el sol, sola pero perfectamente espléndida, protegiendo esta tierra...",
  ui_story_5020_50201501_36_dialog_content = "Mientras luchamos contra la noche oscura, no podemos permitir que las nubes de la isla principal bloqueen nuestros rayos.",
  ui_story_5020_50201501_37_dialog_content = "Sin embargo, si ya conoces esta parte de la historia, probablemente debería contarte algunas cosas, de una sacerdotisa a otra.",
  ui_story_5020_50201501_38_dialog_content = "Kubou-sama no es una nube oscura que bloquea el cielo azul, al menos no en mi opinión.",
  ui_story_5020_50201501_39_dialog_content = "Él no está tan lejos, más como un paraguas sobre nuestras cabezas.",
  ui_story_5020_50201501_40_dialog_content = "No es un buen hombre, y no puede decir que haya hecho muchas cosas buenas. De hecho, ha traído innumerables sufrimientos y desgracias a esta ciudad...",
  ui_story_5020_50201501_41_dialog_content = "Pero este ya es el mejor futuro que puede tener Koufu-jou, y luchó duro por ello.",
  ui_story_5020_50201501_42_dialog_content = "Por favor, perdóname por escribirte esta carta como un completo extraño.",
  ui_story_5020_50201501_43_dialog_content = "Dudé durante bastante tiempo sobre el destinatario...",
  ui_story_5020_50201501_44_dialog_content = "Después de todo, sé que esta será una despedida pesada y dolorosa.",
  ui_story_5020_50201501_45_dialog_content = "Decidí mantenerlo sellado hasta un día en el futuro.",
  ui_story_5020_50201501_46_dialog_content = "Por favor, vive como el sol, con mis mejores deseos.",
  ui_story_5020_50201501_47_dialog_content = "Tu antecesor.",
  ui_story_5020_50201501_48_dialog_content = "...",
  ui_story_5020_50201501_49_dialog_content = "esto es magico...",
  ui_story_5020_50201501_50_dialog_content = "La sacerdotisa de Koufu-jou está condenada a estar sola.",
  ui_story_5020_50201501_51_dialog_content = "Pero siento que he ganado fuerza con el senior...",
  ui_story_5020_50201501_52_dialog_content = "Todas las sacerdotisas de Koufu-jou solían estar solas...",
  ui_story_5020_50201501_53_dialog_content = "Pero Rinne, has cambiado eso. ¿No ves?",
  ui_story_5020_50201501_54_dialog_content = "¿Yo?",
  ui_story_5020_50201501_55_dialog_content = "Su Santidad la Sacerdotisa... Por favor acepte esto antes de abordar el barco...",
  ui_story_5020_50201501_56_dialog_content = "¡Todo este bolso es para la hermana!",
  ui_story_5020_50201501_57_dialog_content = "es una bolsa de <color=#FFB400>fukumame</color> para mantener alejados a los demonios y atraer la buena suerte?",
  ui_story_5020_50201501_58_dialog_content = "Estos son todos los que tenemos. ¡Toda nuestra buena suerte está empaquetada en esta bolsa!",
  ui_story_5020_50201501_59_dialog_content = "¡Hermana, espero que estos frijoles puedan ayudarte a vencer a esos tipos malos!",
  ui_story_5020_50201501_60_dialog_content = "Espero que nuestra buena suerte pueda mantenerte a salvo...",
  ui_story_5020_50201501_61_dialog_content = "Su Santidad la sacerdotisa, quédese con estos frijoles y manténgase a salvo en la batalla.",
  ui_story_5020_50201501_62_dialog_content = "Yo...",
  ui_story_5020_50201501_63_dialog_content = "¡Por favor confia en mi!",
  ui_story_5020_50201501_64_dialog_content = "Sacerdotisa, otro bote está listo. Deberíamos poder acomodar a todos esta vez.",
  ui_story_5020_50201501_65_dialog_content = "Gracias. Por favor, mantenlos a salvo.",
  ui_story_5020_50201501_66_dialog_content = "Amemori, has estado muy callado.",
  ui_story_5020_50201501_67_dialog_content = "Haz algo antes de que el Wisp cambie a un nuevo comandante.",
  ui_story_5020_50201501_68_dialog_content = "... No tengo mucho que decirle a Rinne.",
  ui_story_5020_50201501_69_dialog_content = "Ay... Eso es frío.",
  ui_story_5020_50201501_70_dialog_content = "Amemori, ha sido un tiempo. ¿Me extrañaste?",
  ui_story_5020_50201501_71_dialog_content = "No ha pasado tanto tiempo.",
  ui_story_5020_50201501_72_dialog_content = "¡No es apropiado hablar de los viejos tiempos en una situación tan terrible!",
  ui_story_5020_50201501_73_dialog_content = "¡Ay! ¡Comandante!",
  ui_story_5020_50201501_74_dialog_content = "<size=45>Dama Amemori!</size>",
  ui_story_5020_50201501_75_dialog_content = "¡No me llames comandante!",
  ui_story_5020_50201501_76_dialog_content = "Comandante Amemori, has entrenado muy bien al Wisp.",
  ui_story_5020_50201501_77_dialog_content = "Trabajamos muy bien juntos.",
  ui_story_5020_50201501_78_dialog_content = "¡Vamos, vamos! Rinne y Amemori debe tener un enfrentamiento adecuado!",
  ui_story_5020_50201501_79_dialog_content = "¡La lucha por la nave comandante del Wisp ha comenzado!",
  ui_story_5020_50201501_80_dialog_content = "¡Ay! ¡Mi cabeza!",
  ui_story_5020_50201501_81_dialog_content = "¿Qué clase de broma es esta?",
  ui_story_5020_50201501_82_dialog_content = "Bueno. Ya basta de bromas.",
  ui_story_5020_50201501_83_dialog_content = "Los fantasmas se mueven rápidamente. No les llevará mucho tiempo llegar al puerto.",
  ui_story_5020_50201501_84_dialog_content = "PlayerName, ¡separémonos y preparémonos antes de que puedan llegar!",
  ui_story_5020_50201501_85_dialog_content = "Así que...",
  ui_story_5020_50201501_86_dialog_content = "Amemori y Yao llevará al Wisp a proteger el paso entre Sakai y el puerto.",
  ui_story_5020_50201501_87_dialog_content = "Vice y PlayerName, quédese aquí para cuidar a cualquiera que logre atravesar el paso.",
  ui_story_5020_50201501_88_dialog_content = "Me enfrentaré a esos samuráis en el puerto.",
  ui_story_5020_50201501_89_dialog_content = "¿Solo? ¿Está seguro?",
  ui_story_5020_50201501_90_dialog_content = "¿De verdad crees que este es un buen momento para cuestionar mis habilidades, PlayerName?",
  ui_story_5020_50201501_91_dialog_content = "(Rinne ha cambiado mucho...)",
  ui_story_5020_50201501_92_dialog_content = "¡Vámonos!",
  ui_story_5020_50201501_93_dialog_content = "¡Sí!",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201501_95_dialog_content = "Se están acercando.",
  ui_story_5020_50201501_96_dialog_content = "¡Mmm! ¡Mis puños no pueden esperar!",
  ui_story_5020_50201501_97_dialog_content = "Debo partir hacia el puerto ahora.",
  ui_story_5020_50201501_98_dialog_content = "Estén seguros, todos. ¡Saldremos de esta guerra juntos!",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>Entrada al puerto de Koufu-jou</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>Sss... Sss...</color>",
  ui_story_5020_50201601_3_dialog_content = "Huff... Huff...",
  ui_story_5020_50201601_4_dialog_content = "Urgh... ¡Tos!",
  ui_story_5020_50201601_5_dialog_content = "Dama Amemori!",
  ui_story_5020_50201601_6_dialog_content = "¡Está herida! ¡Cubre su retirada!",
  ui_story_5020_50201601_7_dialog_content = "No hay necesidad. Continúas hacia Sakai...",
  ui_story_5020_50201601_8_dialog_content = "Quedarse quieto es invitar al fracaso.",
  ui_story_5020_50201601_9_dialog_content = "Mantén las fuerzas unidas. No muestres piedad al enemigo.",
  ui_story_5020_50201601_10_dialog_content = "Si te encuentras con alguien que es demasiado para ti, déjalo pasar...",
  ui_story_5020_50201601_11_dialog_content = "¡Nuestro Trozo de Cielo acabará con todos!",
  ui_story_5020_50201601_12_dialog_content = "pero señora Amemori, estas listo...",
  ui_story_5020_50201601_13_dialog_content = "¿Me he dejado claro?",
  ui_story_5020_50201601_14_dialog_content = "¡Sí!",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>Ton, ton, ton...</color>",
  ui_story_5020_50201601_16_dialog_content = "Huff... Huff...",
  ui_story_5020_50201601_17_dialog_content = "¡Cuidado! Amemori—",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201601_19_dialog_content = "Ninjutsu - Sin rastro... Urgh...",
  ui_story_5020_50201601_20_dialog_content = "Amemori!",
  ui_story_5020_50201601_21_dialog_content = "Debería haber sido más cuidadoso.",
  ui_story_5020_50201601_22_dialog_content = "Yao... Ven y párate espalda con espalda conmigo.",
  ui_story_5020_50201601_23_dialog_content = "¡Por supuesto! Pero por qué...",
  ui_story_5020_50201601_24_dialog_content = "Ah, ya veo...",
  ui_story_5020_50201601_25_dialog_content = "Los Lin me enseñaron que un verdadero guerrero siempre se enfrenta al enemigo de frente.",
  ui_story_5020_50201601_26_dialog_content = "¿Los ninjas usan la misma estrategia?",
  ui_story_5020_50201601_27_dialog_content = "Darle la espalda a tu enemigo es un gran no-no.",
  ui_story_5020_50201601_28_dialog_content = "Los ninjas no temen los ataques furtivos desde ninguna dirección.",
  ui_story_5020_50201601_29_dialog_content = "Sin embargo, en este momento no soy tan fuerte como desearía ser.",
  ui_story_5020_50201601_30_dialog_content = "¿Puedo confiar en ti para cuidar mi espalda?",
  ui_story_5020_50201601_31_dialog_content = "¡Ja! ¿Tienes que preguntar?",
  ui_story_5020_50201601_32_dialog_content = "Incluso si no estuvieras herido... Incluso si no estuviéramos unidos por Rebellion y Ryojin...",
  ui_story_5020_50201601_33_dialog_content = "Eres mi hermana de brazos...",
  ui_story_5020_50201601_34_dialog_content = "¡Y te ayudaré con todo lo que tengo!",
  ui_story_5020_50201601_35_dialog_content = "Jejeje... Bien dicho.",
  ui_story_5020_50201601_36_dialog_content = "Vienen más enemigos...",
  ui_story_5020_50201601_37_dialog_content = "Listo, <color=#FFB400>júnior</color>?",
  ui_story_5020_50201601_38_dialog_content = "¡Muy! ¡Me quedan muchas fuerzas!",
  ui_story_5020_50201601_39_dialog_content = "¡Haaa!",
  ui_story_5020_50201601_40_dialog_content = "Jaa... Ja...",
  ui_story_5020_50201601_41_dialog_content = "Amemori, debes aguantar ahí...",
  ui_story_5020_50201601_42_dialog_content = "Buf... yo soy...",
  ui_story_5020_50201601_43_dialog_content = "... Yao¡Toma un trozo de cielo!",
  ui_story_5020_50201601_44_dialog_content = "Algo no está bien...",
  ui_story_5020_50201601_45_dialog_content = "¡Está bien!",
  ui_story_5020_50201601_46_dialog_content = "¿Qué no está bien? ¿Qué debemos hacer?",
  ui_story_5020_50201601_47_dialog_content = "... Avancemos hacia Sakai. Tenemos que ganar tiempo para Rinne y los civiles en el puerto.",
  ui_story_5020_50201601_48_dialog_content = "Vigila tu entorno.",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_51_dialog_content = "(El Wisp está luchando contra algunos fantasmas menores en la dirección de las 2 en punto...)",
  ui_story_5020_50201601_52_dialog_content = "(Y hay pasos humanos a las 10 en punto...)",
  ui_story_5020_50201601_53_dialog_content = "(Seis pájaros acaban de volar en el bosque a las 7 en punto...)",
  ui_story_5020_50201601_54_dialog_content = "(Extraño, no puedo escuchar ningún sonido inusual. ¿Qué está pasando?)",
  ui_story_5020_50201601_55_dialog_content = "...",
  ui_story_5020_50201601_56_dialog_content = "¡Guau! Amemori, ¡allí!",
  ui_story_5020_50201601_57_dialog_content = "Esa figura...",
  ui_story_5020_50201601_58_dialog_content = "¿Un residente de Koufu dejado atrás?",
  ui_story_5020_50201601_59_dialog_content = "Pero, ¿cómo podría quedar alguien en la ciudad?",
  ui_story_5020_50201601_60_dialog_content = "... Yao! ¡Ten cuidado!",
  ui_story_5020_50201601_61_dialog_content = "¿Qué?",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>... Gaa...</anim>",
  ui_story_5020_50201601_63_dialog_content = "¿Que dijo el?",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "¿Ese es... Fujikumo?",
  ui_story_5020_50201601_67_dialog_content = "... ¡No!",
  ui_story_5020_50201601_68_dialog_content = "(¿Cómo escapó Fujikumo del maestro y llegó al puerto de una sola pieza?)",
  ui_story_5020_50201601_69_dialog_content = "(Podría ser el maestro...)",
  ui_story_5020_50201601_70_dialog_content = "¿Qué... qué clase de monstruo es ese?",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>Establecer...</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>Recuéstalo...</anim>",
  ui_story_5020_50201601_73_dialog_content = "Yao, agárrate fuerte a Slice of Heaven...",
  ui_story_5020_50201601_74_dialog_content = "Puede que no ganemos...",
  ui_story_5020_50201601_75_dialog_content = "¡Pero no podemos ceder Slice of Heaven a nadie!",
  ui_story_5020_50201601_76_dialog_content = "¡¿Dónde está mi amo?!",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>Matar...</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>Matar...</anim>",
  ui_story_5020_50201601_79_dialog_content = "¿Qué?",
  ui_story_5020_50201601_80_dialog_content = "...",
  ui_story_5020_50201601_81_dialog_content = "¡Te mataré! Ninjutsu - Rastrear...",
  ui_story_5020_50201601_82_dialog_content = "Ugh... *Tos*",
  ui_story_5020_50201601_83_dialog_content = "(... ¿Qué más puedo hacer? ¿Es esto...?)",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>¡Chasquido... golpe!</color>",
  ui_story_5020_50201601_85_dialog_content = "¡Torrente rápido!",
  ui_story_5020_50201601_86_dialog_content = "Barrera... ¡Desplegar!",
  ui_story_5020_50201601_87_dialog_content = "¡Ustedes!",
  ui_story_5020_50201601_88_dialog_content = "¡Ustedes dos han luchado duro!",
  ui_story_5020_50201601_89_dialog_content = "¡Todo aclarado aquí! ¡Ahora, concentrémonos en defender el pase!",
  ui_story_5020_50201601_90_dialog_content = "Escóndete detrás de la barrera. Déjame...",
  ui_story_5020_50201601_91_dialog_content = "Ah...",
  ui_story_5020_50201601_92_dialog_content = "Bueno.",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>Rinne...</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>Te atreves...</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "¿Ese es el general Fujikumo? ¿Lo que le sucedió?",
  ui_story_5020_50201601_98_dialog_content = "*Tos* ¡Eso no es importante ahora!",
  ui_story_5020_50201601_99_dialog_content = "¡Apurarse! Mátalo con Slice of Heaven...",
  ui_story_5020_50201601_100_dialog_content = "Rinne! ¡Atrapar!",
  ui_story_5020_50201601_101_dialog_content = "¡Sí!",
  ui_story_5020_50201601_102_dialog_content = "(Esta es la espada sagrada que las sacerdotisas han transmitido de generación en generación...)",
  ui_story_5020_50201601_103_dialog_content = "(Las sacerdotisas lo usarían para matar fantasmas, pero el general lo ha mantenido alejado de ellas...)",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>Golpe... Golpe... Golpe...</color>",
  ui_story_5020_50201601_105_dialog_content = "(Ah... General... Kubou-sama... Tal vez debería llamarte padre por última vez...)",
  ui_story_5020_50201601_106_dialog_content = "(Mis manos no pueden dejar de temblar mientras sostengo Slice of Heaven...)",
  ui_story_5020_50201601_107_dialog_content = "(Estoy asustada, nerviosa y emocionada a la vez...)",
  ui_story_5020_50201601_108_dialog_content = "(Nunca me enseñaste a usar esto...)",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>¡Rugido!</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "Padre...",
  ui_story_5020_50201601_111_dialog_content = "Por favor... ¡Toma eso!",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>gaar...</anim>",
  ui_story_5020_50201602_2_dialog_content = "Jaja... eh...",
  ui_story_5020_50201602_3_dialog_content = "Rinne, ¡ahora!",
  ui_story_5020_50201602_4_dialog_content = "¡Haaa!",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>¡Uraaaagh!</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>Silbido...</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>Eh... Eh... Eh...</anim>",
  ui_story_5020_50201602_8_dialog_content = "¿General?",
  ui_story_5020_50201602_9_dialog_content = "¡Lo hicimos!",
  ui_story_5020_50201602_10_dialog_content = "Mata a los fantasmas y conviértelos en humanos...",
  ui_story_5020_50201602_11_dialog_content = "¿Es este el verdadero poder de Slice of Heaven?",
  ui_story_5020_50201602_12_dialog_content = "Rinne... Ustedes realmente tomaron Slice of Heaven ...",
  ui_story_5020_50201602_13_dialog_content = "Lo has hecho bien…",
  ui_story_5020_50201602_14_dialog_content = "Ven a mi…",
  ui_story_5020_50201602_15_dialog_content = "General, usted...",
  ui_story_5020_50201602_16_dialog_content = "Por todas las cosas imperdonables que has hecho...",
  ui_story_5020_50201602_17_dialog_content = "Es posible que a veces te sientas frustrado e impotente, pero eso no justifica tu despiadada búsqueda del poder.",
  ui_story_5020_50201602_18_dialog_content = "El fuego en Koufu-jou se ha extinguido.",
  ui_story_5020_50201602_19_dialog_content = "… Y es hora de que descanses.",
  ui_story_5020_50201602_20_dialog_content = "¿Frustrado e indefenso? Jajaja…",
  ui_story_5020_50201602_21_dialog_content = "Después de todo, leíste la carta.",
  ui_story_5020_50201602_22_dialog_content = "Más allá de lo que viste, hay otras cosas que nunca entenderás.",
  ui_story_5020_50201602_23_dialog_content = "Pero los niños no deberían tener que sentirse frustrados e indefensos.",
  ui_story_5020_50201602_24_dialog_content = "Rinne, has crecido.",
  ui_story_5020_50201602_25_dialog_content = "¿No me llamarás Kubou-sama por última vez?",
  ui_story_5020_50201602_26_dialog_content = "...",
  ui_story_5020_50201602_27_dialog_content = "¡Mmm! ¡No te mereces ese título!",
  ui_story_5020_50201602_28_dialog_content = "Fujikumo, tus días han terminado.",
  ui_story_5020_50201602_29_dialog_content = "Mira alrededor.",
  ui_story_5020_50201602_30_dialog_content = "¡Je, ptui! Eso es lo que yo llamo karma.",
  ui_story_5020_50201602_31_dialog_content = "Arrodíllate... Sí, arrodíllate... ¡Jajajaja! ¡El majestuoso General Fujikumo ha sido reducido a un prisionero!",
  ui_story_5020_50201602_32_dialog_content = "¿Por qué perdemos el tiempo hablando con él? ¡Hermanos, acabad con él! ¡Una ofrenda extra para el Festival Kasuga!",
  ui_story_5020_50201602_33_dialog_content = "¡Así es! Mátalo…",
  ui_story_5020_50201602_34_dialog_content = "Jajaja... Jajajajaja...",
  ui_story_5020_50201602_35_dialog_content = "¡No te atrevas!",
  ui_story_5020_50201602_36_dialog_content = "¡Atrás, tontos! ¡Lastimar a Kubou-sama es convertir en enemigos a toda la isla principal!",
  ui_story_5020_50201602_37_dialog_content = "¡Ptui! ¿A quién diablos le importa la isla principal?",
  ui_story_5020_50201602_38_dialog_content = "¡Date la vuelta y búscate! ¿Cuántos de tus samuráis aún respiran? ¡Fujikumo, te mereces esto!",
  ui_story_5020_50201602_39_dialog_content = "¡Hermanos, cargad!",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>Tintinar...</color>",
  ui_story_5020_50201602_41_dialog_content = "¡Quedarse atrás!",
  ui_story_5020_50201602_42_dialog_content = "Retrocede... *tos* Retrocede...",
  ui_story_5020_50201602_43_dialog_content = "¿La Isla de las Nubes sería un lugar mejor si mataras al general Fujikumo?",
  ui_story_5020_50201602_44_dialog_content = "...",
  ui_story_5020_50201602_45_dialog_content = "Incluso si matas al general actual...",
  ui_story_5020_50201602_46_dialog_content = "Se asignará un nuevo general de la isla principal para que reanude el mando de Cloud Island dentro de medio mes.",
  ui_story_5020_50201602_47_dialog_content = "¿A quién dirigirás entonces tu ira?",
  ui_story_5020_50201602_48_dialog_content = "Para ustedes, rebeldes, Kubou-sama es un forastero al que arrojan el desfiladero.",
  ui_story_5020_50201602_49_dialog_content = "Pero en realidad, Kubou-sama también es una herramienta utilizada por fuerzas externas.",
  ui_story_5020_50201602_50_dialog_content = "Guardias... Saquen a este hombre...",
  ui_story_5020_50201602_51_dialog_content = "(Fujikumo... está luchando por hablar...)",
  ui_story_5020_50201602_52_dialog_content = "¡Mi señor, permítame terminar!",
  ui_story_5020_50201602_53_dialog_content = "… Los compromisos que Kubou-sama ha hecho para apaciguar a la isla principal…",
  ui_story_5020_50201602_54_dialog_content = "Los esfuerzos que ha hecho para mantener la Isla de las Nubes en paz... ¡Nunca podrás entenderlo!",
  ui_story_5020_50201602_55_dialog_content = "Puedes llamarlo brutal... Puedes decir que está retorcido...",
  ui_story_5020_50201602_56_dialog_content = "Pero, ¿de verdad crees que está equivocado?",
  ui_story_5020_50201602_57_dialog_content = "...",
  ui_story_5020_50201602_58_dialog_content = "no me gusta lo que dice...",
  ui_story_5020_50201602_59_dialog_content = "Pero creo que tiene razón...",
  ui_story_5020_50201602_60_dialog_content = "Siempre lo dije pero nadie más entiende lo complicada que es la situación política...",
  ui_story_5020_50201602_61_dialog_content = "¡Podría manejar Cloud Island cien veces mejor que este Fujikumo!",
  ui_story_5020_50201602_62_dialog_content = "¿Qué estás diciendo? ¿Estás comprando sus excusas?",
  ui_story_5020_50201602_63_dialog_content = "Antes de pasarte al enemigo, tendrás que tratar conmigo primero. ¡No odio nada más que a los traidores!",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>Chirrido... Twitter...</color>",
  ui_story_5020_50201602_65_dialog_content = "Je... Kubou-sama no necesita sus sabias palabras en retrospectiva.",
  ui_story_5020_50201602_66_dialog_content = "¡Para él, tu simpatía es una humillación!",
  ui_story_5020_50201602_67_dialog_content = "Cállate...",
  ui_story_5020_50201602_68_dialog_content = "¡Sí! ¡Cierren la boca!",
  ui_story_5020_50201602_69_dialog_content = "Solo unos pocos pueden entender a Kubou-sama...",
  ui_story_5020_50201602_70_dialog_content = "Kubou-sama, ¡nadie en este mundo lo entiende mejor que yo!",
  ui_story_5020_50201602_71_dialog_content = "¡Basta!",
  ui_story_5020_50201602_72_dialog_content = "Basta de tonterías.",
  ui_story_5020_50201602_73_dialog_content = "¿Quién demonios eres?",
  ui_story_5020_50201602_74_dialog_content = "...",
  ui_story_5020_50201602_75_dialog_content = "Estás aquí…",
  ui_story_5020_50201701_1_dialog_content = "Esta mujer…",
  ui_story_5020_50201701_2_dialog_content = "¿Sigue viva?",
  ui_story_5020_50201701_3_dialog_content = "Padre... ¿Quién es ella?",
  ui_story_5020_50201701_4_dialog_content = "¡Silencio!",
  ui_story_5020_50201701_5_dialog_content = "No hagas preguntas. ¡Manten tu boca cerrada!",
  ui_story_5020_50201701_6_dialog_content = "(Maestría!)",
  ui_story_5020_50201701_7_dialog_content = "Je...",
  ui_story_5020_50201701_8_dialog_content = "Ese discurso fue bastante conmovedor.",
  ui_story_5020_50201701_9_dialog_content = "Como subordinado, realmente sabes cómo humillar a tu general.",
  ui_story_5020_50201701_10_dialog_content = "¿De qué estás hablando?",
  ui_story_5020_50201701_11_dialog_content = "¡Urgh!",
  ui_story_5020_50201701_12_dialog_content = "Fuera de mi camino.",
  ui_story_5020_50201701_13_dialog_content = "...",
  ui_story_5020_50201701_14_dialog_content = "Fujikumo, has esperado este momento demasiado tiempo.",
  ui_story_5020_50201701_15_dialog_content = "Finalmente.",
  ui_story_5020_50201701_16_dialog_content = "llego un poco temprano",
  ui_story_5020_50201701_17_dialog_content = "Puede que no sea malo dejar que sufras el abuso de este samurái un poco más.",
  ui_story_5020_50201701_18_dialog_content = "No necesitas simpatía ni comprensión. Quieres la muerte.",
  ui_story_5020_50201701_19_dialog_content = "¿Verdad?",
  ui_story_5020_50201701_20_dialog_content = "... Jejeje.",
  ui_story_5020_50201701_21_dialog_content = "Morir en acción nunca es una tragedia. El campo de batalla es donde pertenece un héroe.",
  ui_story_5020_50201701_22_dialog_content = "Termina esto por mi...",
  ui_story_5020_50201701_23_dialog_content = "No está mal morir en tu mano.",
  ui_story_5020_50201701_24_dialog_content = "Fujikumo, después de todos los tratos sucios e inmundos que has hecho en tu vida...",
  ui_story_5020_50201701_25_dialog_content = "Ahora, demorándote en tu último aliento, de repente te preocupas por la decencia y la dignidad.",
  ui_story_5020_50201701_26_dialog_content = "¡Jajajaja! Tos...",
  ui_story_5020_50201701_27_dialog_content = "Nagi, sé lo rápida que es tu espada...",
  ui_story_5020_50201701_28_dialog_content = "Si dudas en empuñarlo, no te lo mereces.",
  ui_story_5020_50201701_29_dialog_content = "je. No necesitas preocuparte.",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>Tintinar...</color>",
  ui_story_5020_50201701_31_dialog_content = "...",
  ui_story_5020_50201701_32_dialog_content = "Te permito decir tus últimas palabras.",
  ui_story_5020_50201701_33_dialog_content = "...",
  ui_story_5020_50201701_34_dialog_content = "Tsuki...",
  ui_story_5020_50201701_35_dialog_content = "¿Es este Koufu-jou como querías que fuera?",
  ui_story_5020_50201701_36_dialog_content = "...",
  ui_story_5020_50201701_37_dialog_content = "...",
  ui_story_5020_50201701_38_dialog_content = "¿Él está muerto?",
  ui_story_5020_50201701_39_dialog_content = "Creo...",
  ui_story_5020_50201701_40_dialog_content = "no creo que este respirando...",
  ui_story_5020_50201701_41_dialog_content = "¡Muerto! ¡De verdad!",
  ui_story_5020_50201701_42_dialog_content = "¡Fujikumo está muerto! ¡No más general para Cloud Island!",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>¡Si!</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>¡El general está muerto!</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>¡Viva la isla de las nubes!</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>Si...</anim>",
  ui_story_5020_50201701_47_dialog_content = "...",
  ui_story_5020_50201701_48_dialog_content = "Comandante!",
  ui_story_5020_50201701_49_dialog_content = "¡Estás vivo!",
  ui_story_5020_50201701_50_dialog_content = "¿Eres realmente Nagi-sama?",
  ui_story_5020_50201701_51_dialog_content = "¿Comandante? ¡Comandante! ¿Adónde vas?",
  ui_story_5020_50201701_52_dialog_content = "¡Espere por favor!",
  ui_story_5020_50201701_53_dialog_content = "¿...?",
  ui_story_5020_50201701_54_dialog_content = "Eres tú.",
  ui_story_5020_50201701_55_dialog_content = "No me gusta decir adiós. Hazlo rápido.",
  ui_story_5020_50201701_56_dialog_content = "¡Maestro, por favor espere!",
  ui_story_5020_50201701_57_dialog_content = "¡Yao está aquí inclinándose ante el maestro!",
  ui_story_5020_50201701_58_dialog_content = "¿Para qué?",
  ui_story_5020_50201701_59_dialog_content = "Yao vino a Cloud Island y pasó por muchos problemas, ¡todo gracias al maestro!",
  ui_story_5020_50201701_60_dialog_content = "(¡Eso no suena bien!)",
  ui_story_5020_50201701_61_dialog_content = "Gracias al maestro, pude experimentar el conflicto y las luchas de tu generación.",
  ui_story_5020_50201701_62_dialog_content = "Nunca he tenido algo como esto antes.",
  ui_story_5020_50201701_63_dialog_content = "Permíteme llamarte maestro una vez más.",
  ui_story_5020_50201701_64_dialog_content = "Maestro, si necesita ayuda en el futuro, comuníquese con Lin Guild en Umbraton, Astra.",
  ui_story_5020_50201701_65_dialog_content = "¡Yao vendrá en tu ayuda sin importar lo lejos que deba viajar!",
  ui_story_5020_50201701_66_dialog_content = "Jejeje... Gracias, Yao.",
  ui_story_5020_50201701_67_dialog_content = "Pero durante el resto de este viaje, debo estar solo.",
  ui_story_5020_50201701_68_dialog_content = "Necesito acabar con el dominio de la isla principal sobre la Isla de las Nubes. Esta es la única forma de dejar atrás todas estas viejas partituras.",
  ui_story_5020_50201701_69_dialog_content = "¿Vas a la isla principal?",
  ui_story_5020_50201701_70_dialog_content = "Maestro, por favor...",
  ui_story_5020_50201701_71_dialog_content = "Cuídate. Y lleva a Cloud Island a un futuro más brillante.",
  ui_story_5020_50201701_72_dialog_content = "The Wisp y yo siempre estamos listos para luchar por ti.",
  ui_story_5020_50201701_73_dialog_content = "¿Oh? Amemori...",
  ui_story_5020_50201701_74_dialog_content = "Has crecido.",
  ui_story_5020_50201701_75_dialog_content = "Eres mejor comandante del Wisp que yo.",
  ui_story_5020_50201701_76_dialog_content = "Nagi-sama, tenga cuidado. May ¡la victoria sea contigo!",
  ui_story_5020_50201701_77_dialog_content = "...",
  ui_story_5020_50201701_78_dialog_content = "Supongo que te veré por ahí.",
  ui_story_5020_50201701_79_dialog_content = "¡Ay! Por favor, espere un segundo más. Que...",
  ui_story_5020_50201701_80_dialog_content = "PlayerName, deberíamos darle eso.",
  ui_story_5020_50201701_81_dialog_content = "¡Estás en lo correcto!",
  ui_story_5020_50201701_82_dialog_content = "¿Qué?",
  ui_story_5020_50201701_83_dialog_content = "Nagi, por favor acepta este cuaderno.",
  ui_story_5020_50201701_84_dialog_content = "Ella no dio ninguna orden...",
  ui_story_5020_50201701_85_dialog_content = "Pero su reliquia podría ser importante para ti.",
  ui_story_5020_50201701_86_dialog_content = "Esto debe ser guardado por usted.",
  ui_story_5020_50201701_87_dialog_content = "Tsuki tenía un diario...",
  ui_story_5020_50201701_88_dialog_content = "Nunca la vi escribir...",
  ui_story_5020_50201701_89_dialog_content = "He decidido dejar todo a un lado y dirigirme a la isla principal.",
  ui_story_5020_50201701_90_dialog_content = "Por favor, guárdamelo.",
  ui_story_5020_50201701_91_dialog_content = "¿Estás seguro de que no quieres tener una lectura?",
  ui_story_5020_50201701_92_dialog_content = "Para avanzar, necesitamos dejar atrás el pasado, no huir de él.",
  ui_story_5020_50201701_93_dialog_content = "Algunas de sus preguntas pueden encontrar respuesta y algunos nudos en su corazón pueden abrirse.",
  ui_story_5020_50201701_94_dialog_content = "...",
  ui_story_5020_50201701_95_dialog_content = "Seguro.",
  ui_story_5020_50201701_96_dialog_content = "...",
  ui_story_5020_50201701_97_dialog_content = "...",
  ui_story_5020_50201701_98_dialog_content = "<size=30>Hermana…</size>",
  ui_story_5020_50201701_99_dialog_content = "Tsuki...",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>En una calle de la ciudad del castillo de Koufu-jou</color>",
  ui_story_5020_50201701_101_dialog_content = "¡Ah! ¡Qué escena armónica!",
  ui_story_5020_50201701_102_dialog_content = "El escenario está decorado con tantas banderas de colores. Los taiko están listos. La gente saca pescado bajo los cerezos...",
  ui_story_5020_50201701_103_dialog_content = "Y este ninja-sama está sentado aquí a mi lado en lugar de causar problemas.",
  ui_story_5020_50201701_104_dialog_content = "Por favor, no me llames así.",
  ui_story_5020_50201701_105_dialog_content = "No defraudes a Momo y Anzu. Este té es muy sabroso.",
  ui_story_5020_50201701_106_dialog_content = "… Odio las cosas sabrosas. No comeré nada de este puesto.",
  ui_story_5020_50201701_107_dialog_content = "(Refunfuñando...)",
  ui_story_5020_50201701_108_dialog_content = "¡Ugh...!",
  ui_story_5020_50201701_109_dialog_content = "¡Viniendo! ¡Perdón por la espera!",
  ui_story_5020_50201701_110_dialog_content = "¡Prueba nuestro nuevo plato, Kaniya Veggie Ramen!",
  ui_story_5020_50201701_111_dialog_content = "Hemos perfeccionado la receta después de innumerables pruebas de sabor con nuestro intrépido Guerrero. Yao!",
  ui_story_5020_50201701_112_dialog_content = "Eructar... Estoy completamente satisfecho...",
  ui_story_5020_50201701_113_dialog_content = "(Yao está en coma alimenticio!)",
  ui_story_5020_50201701_114_dialog_content = "En ese caso.",
  ui_story_5020_50201701_115_dialog_content = "Tomaré algunos bocados.",
  ui_story_5020_50201701_116_dialog_content = "¡Debemos darnos prisa con alguna nueva historia para este nuevo plato!",
  ui_story_5020_50201701_117_dialog_content = "¡Los nuevos clientes no volverán por viejas historias!",
  ui_story_5020_50201701_118_dialog_content = "PlayerName-sama, ¿qué historia crees que es adecuada?",
  ui_story_5020_50201701_119_dialog_content = "¿Me estás preguntando?",
  ui_story_5020_50201701_120_dialog_content = "En mi humilde opinión…",
  ui_story_5020_50201701_121_option_content = "Puedes contar la historia de tres viejos amigos.",
  ui_story_5020_50201701_122_dialog_content = "Tres viejos amigos dedicaron sus vidas a proteger esta tierra a su manera.",
  ui_story_5020_50201701_123_dialog_content = "Las dos hermanas estaban condenadas a separarse y tomar caminos diferentes, pero su canción todavía se puede escuchar aquí.",
  ui_story_5020_50201701_124_dialog_content = "La sacerdotisa y el general incomprendidos superaron sus diferentes posiciones y desarrollaron confianza mutua.",
  ui_story_5020_50201701_125_dialog_content = "Los dos luchadores lucharon hasta el último segundo, pero finalmente llegaron a un entendimiento mutuo y se despidieron mal.",
  ui_story_5020_50201701_126_dialog_content = "Esta tierra progresó hacia la paz tal como lo habían anticipado...",
  ui_story_5020_50201701_127_dialog_content = "¿De verdad crees que esta es una buena historia paralela?",
  ui_story_5020_50201701_128_option_content = "Puedes contar la historia de tres niños pequeños.",
  ui_story_5020_50201701_129_dialog_content = "Tres niños inusuales emprenden un viaje contra el mal y los monstruos por diferentes razones...",
  ui_story_5020_50201701_130_dialog_content = "En el camino, todos aprendieron cosas mucho más valiosas que la victoria.",
  ui_story_5020_50201701_131_dialog_content = "El soldado de plomo enmascarado llenó su corazón de amistad.",
  ui_story_5020_50201701_132_dialog_content = "El espantapájaros empapado en agua de mar llenó su cabeza de recuerdos.",
  ui_story_5020_50201701_133_dialog_content = "El león disfrazado encontró coraje para luchar contra su destino...",
  ui_story_5020_50201701_134_dialog_content = "¡No plagies el cuento para dormir de los niños del norte! ¡Eso es demasiado!",
  ui_story_5020_50201701_135_dialog_content = "Mmm... Suena bien.",
  ui_story_5020_50201701_136_dialog_content = "Trabajaremos en un guión alrededor PlayerName-¡Idea de sama!",
  ui_story_5020_50201701_137_dialog_content = "Primero, necesitamos un final adecuado para nuestra historia de Cloud Island...",
  ui_story_5020_50201701_138_dialog_content = "¿Un final adecuado? ¿Hay algo de lo que no somos conscientes?",
  ui_story_5020_50201701_139_dialog_content = "Mmm... ¡Acabamos de recibir esta información de nuestro trabajador a tiempo parcial!",
  ui_story_5020_50201701_140_dialog_content = "Si realmente quieres escuchar…",
  ui_story_5020_50201701_141_dialog_content = "Uno más por favor.",
  ui_story_5020_50201701_142_dialog_content = "Cariño, eres el mejor. La última vez que nuestra historia cerró con...",
  ui_story_5020_50201701_143_dialog_content = "Se dice que Fujikumo es indestructible con un corazón duro como la roca y frío como el hielo. Nadie en la Isla de las Nubes conoce su punto débil, excepto...",
  ui_story_5020_50201701_144_dialog_content = "Tada... Nuestro Kayano!",
  ui_story_5020_50201701_145_dialog_content = "¿Eh? ¡Eso es inesperado! ¿Me llamaste?",
  ui_story_5020_50201701_146_dialog_content = "Ven aquí, nuestro pequeño trabajador. Decir PlayerName-sama lo que viste cuando te ausentaste del trabajo ese día.",
  ui_story_5020_50201701_147_dialog_content = "Yo... fui a admirar los cerezos en flor en el <color=#FFB400>cementerio</color> fuera de la ciudad... Esta es la estación en la que caen los cerezos en flor...",
  ui_story_5020_50201701_148_dialog_content = "En la entrada, vi a un hombre adentro...",
  ui_story_5020_50201701_149_dialog_content = "¡¿?!",
  ui_story_5020_50201701_150_dialog_content = "(¡El hombre visitó el cementerio antes que nosotros!)",
  ui_story_5020_50201701_151_dialog_content = "¿Quién es?",
  ui_story_5020_50201701_152_dialog_content = "Ah... PlayerName-sama es tan feroz e impaciente...",
  ui_story_5020_50201701_153_dialog_content = "Yo... Lo siento...",
  ui_story_5020_50201701_154_dialog_content = "Él no se dio cuenta de mí, pero lo vi claramente...",
  ui_story_5020_50201701_155_dialog_content = "Ese hombre era… <color=#FFB400>general fujikumo</color>…",
  ui_story_5020_50201701_156_dialog_content = "...",
  ui_story_5020_50201701_157_dialog_content = "Se paró frente a una tumba en silencio, sin un solo samurái cerca...",
  ui_story_5020_50201701_158_dialog_content = "Pensé que tomaría el sable dorado que yacía frente a la lápida... Pero no lo hizo...",
  ui_story_5020_50201701_159_dialog_content = "Dejó solemnemente un libro antes de irse...",
  ui_story_5020_50201701_160_dialog_content = "Entonces... Entonces casi me ve... Me escapé de una vez...",
  ui_story_5020_50201701_161_dialog_content = "...",
  ui_story_5020_50201701_162_dialog_content = "Era Fujikumo...",
  ui_story_5020_50201701_163_dialog_content = "¡Así es! El insensible general rindió homenaje a un viejo amigo en un rincón desolado de la isla...",
  ui_story_5020_50201701_164_dialog_content = "¡Mmm! ¡Esto atraerá a muchos más clientes nuevos!",
  ui_story_5020_50201701_165_dialog_content = "¡Oye! Pero esto...",
  ui_story_5020_50201701_166_dialog_content = "No pasa nada, PlayerName.",
  ui_story_5020_50201701_167_dialog_content = "Si este pudiera ser el último recuerdo del general y la anterior sacerdotisa en la Isla de las Nubes...",
  ui_story_5020_50201701_168_dialog_content = "Es un muy buen final para el pasado de la isla.",
  ui_story_5020_50201701_169_dialog_content = "Después de todo, una nueva era…",
  ui_story_5020_50201701_170_dialog_content = "¡Está a punto de empezar!",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201701_172_dialog_content = "¡Moverse! Mueva su puesto de la carretera al castillo principal.",
  ui_story_5020_50201701_173_dialog_content = "¿Castillo principal? ¿Qué castillo? ¿Quién es este forastero?",
  ui_story_5020_50201701_174_dialog_content = "...",
  ui_story_5020_50201701_175_dialog_content = "¡Mirar! La isla principal ya ha enviado tropas. Ese uniforme lleva el patrón de la isla principal.",
  ui_story_5020_50201701_176_dialog_content = "Como era de esperar, no renunciarán a su control sobre Cloud Island.",
  ui_story_5020_50201701_177_dialog_content = "Rinne¿Te quedarás en este lugar?",
  ui_story_5020_50201701_178_dialog_content = "Jejeje He hecho mi plan… Y tú…",
  ui_story_5020_50201701_179_dialog_content = "¿Cómo piensas irte?",
  ui_story_5020_50201701_180_dialog_content = "No te preocupes. Conduciremos el Colossus y tomaremos el mismo camino de regreso.",
  ui_story_5020_50201701_181_dialog_content = "Hablando de eso... a Soroz le vendría bien algún servicio...",
  ui_story_5020_50201701_182_dialog_content = "¿Coloso? ¿Soroz?",
  ui_story_5020_50201701_183_dialog_content = "Ahh... Muchas palabras nuevas para aprender...",
  ui_story_5020_50201701_184_dialog_content = "Realmente necesito ir y explorar el mundo exterior.",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>Puerto de Koufu-jou</color>",
  ui_story_5020_50201701_186_dialog_content = "Bueno. ¡Es hora de decir adiós!",
  ui_story_5020_50201701_187_dialog_content = "Mi barco debería estar aquí en cualquier momento.",
  ui_story_5020_50201701_188_dialog_content = "Patético.",
  ui_story_5020_50201701_189_dialog_content = "No estoy interesado en despedirte...",
  ui_story_5020_50201701_190_dialog_content = "Pero esto es parte de la forma en que Cloud Island trata a nuestros huéspedes.",
  ui_story_5020_50201701_191_dialog_content = "Amemori...",
  ui_story_5020_50201701_192_dialog_content = "Yo...",
  ui_story_5020_50201701_193_dialog_content = "<size=45>Guauuu... ¡Guau!</size>",
  ui_story_5020_50201701_194_dialog_content = "¡Tú! ¿Qué quieres?",
  ui_story_5020_50201701_195_dialog_content = "Wuahhhh... Amemori ¡No puedo soportar verme ir tampoco! I...",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>No quiero despedirme... ¡Guau!</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "Ahí ahí. Yao, no llores.",
  ui_story_5020_50201701_198_dialog_content = "Nos veremos otra vez.",
  ui_story_5020_50201701_199_dialog_content = "Vaya... ¿Qué?",
  ui_story_5020_50201701_200_dialog_content = "Rinne... Tú...",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>¡Guau, guau! no vas conmigo?</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>Guau guau...</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "Ah oh...",
  ui_story_5020_50201701_204_dialog_content = "Yao, escuchar.",
  ui_story_5020_50201701_205_dialog_content = "Tengo mucho que hacer aquí en Cloud Island...",
  ui_story_5020_50201701_206_dialog_content = "Las fuerzas de la isla principal ya están actuando. Debo quedarme aquí para mantener controles y equilibrios.",
  ui_story_5020_50201701_207_dialog_content = "He guardado tanto el Espejo de la nube como el Rebanada del cielo de forma segura...",
  ui_story_5020_50201701_208_dialog_content = "Usaré mi propia fuerza para mantener la paz y el orden en la Isla de las Nubes.",
  ui_story_5020_50201701_209_dialog_content = "Por supuesto... Amemori y el Wisp también me ayudará. ¿Bien?",
  ui_story_5020_50201701_210_dialog_content = "Definitivamente.",
  ui_story_5020_50201701_211_dialog_content = "Contigo o sin ti, la misión de Wisp siempre ha sido luchar contra la isla principal.",
  ui_story_5020_50201701_212_dialog_content = "Como puedes ver, querido Yao... Tengo que quedarme y provocar cambios en Cloud Island.",
  ui_story_5020_50201701_213_dialog_content = "¿Confías en mí?",
  ui_story_5020_50201701_214_dialog_content = "*sollozo*... lo sé Rinne puede hacer esto...",
  ui_story_5020_50201701_215_dialog_content = "Entonces... Rinne y Amemori... Momo, Anzu y Kayano...",
  ui_story_5020_50201701_216_dialog_content = "¡Por favor cuídate!",
  ui_story_5020_50201701_217_dialog_content = "Oh y PlayerName y Vice!",
  ui_story_5020_50201701_218_dialog_content = "¿Si?",
  ui_story_5020_50201701_219_dialog_content = "Gracias por tomar mi caso y viajar aquí conmigo.",
  ui_story_5020_50201701_220_dialog_content = "Gracias por todos estos amigos que hicimos... Todos ustedes son tan valiosos como los recuerdos...",
  ui_story_5020_50201701_221_dialog_content = "Las cosas que esta isla me ha dado serán apreciadas por el resto de mi vida.",
  ui_story_5020_50201701_222_dialog_content = "*Sniff*",
  ui_story_5020_50201701_223_dialog_content = "(¡Maldita sea! Será mejor que la consuele ahora...)",
  ui_story_5020_50201701_224_dialog_content = "Por esa razón...",
  ui_story_5020_50201701_225_dialog_content = "¡Una gran cantidad, mucho más allá de los 7 dígitos, se transferirá a su cuenta tan pronto como regrese al clan Lin!",
  ui_story_5020_50201701_226_dialog_content = "¡¿Eh?!",
  ui_story_5020_50201701_227_dialog_content = "… ¿No es bueno? ¡Esta es la única manera de expresar mi gratitud!",
  ui_story_5020_50201701_228_dialog_content = "¡Eso es demasiado!",
  ui_story_5020_50201701_229_dialog_content = "Ah... ¿Cómo deberíamos gastar este dinero? Tenemos que arreglar el Coloso... Entonces...",
  ui_story_5020_50201701_230_dialog_content = "(¿Ya no puedes esperar?)",
  ui_story_5020_50201701_231_dialog_content = "¡Ay! Algo se acerca lentamente...",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>Bip... Guau...</color>",
  ui_story_5020_50201701_233_dialog_content = "Hmm... Agh...",
  ui_story_5020_50201701_234_dialog_content = "Así que este es el poder del mar...",
  ui_story_5020_50201701_235_dialog_content = "¡Guau! ¡Hermana, por favor! ¡Me estás poniendo nervioso!",
  ui_story_5020_50201701_236_dialog_content = "¡No le digas a nadie que el célebre Ying del reputado clan Lin no puede manejar un paseo en bote!",
  ui_story_5020_50201701_237_dialog_content = "Deja de... *vomitar* Deja de gritar...",
  ui_story_5020_50201701_238_dialog_content = "*Sollozo*",
  ui_story_5020_50201701_239_dialog_content = "Nuestro distinguido cliente que come siete tazones de ramen de una sentada...",
  ui_story_5020_50201701_240_dialog_content = "Vuelve a visitar Cloud Island cuando encuentres tiempo...",
  ui_story_5020_50201701_241_dialog_content = "¡Kaniya Ramen está aquí para servirte!",
  ui_story_5020_50201701_242_dialog_content = "*Sollozo*",
  ui_story_5020_50201701_243_dialog_content = "Hmm... Jefes...",
  ui_story_5020_50201701_244_dialog_content = "El nuevo plato que Guerrero Yao hecho definitivamente será un gran éxito...",
  ui_story_5020_50201701_245_dialog_content = "No te enfades demasiado...",
  ui_story_5020_50201701_246_dialog_content = "¡Estás en lo correcto!",
  ui_story_5020_50201701_247_dialog_content = "Yao...",
  ui_story_5020_50201701_248_dialog_content = "Viajes seguros...",
  ui_story_5020_50201701_249_dialog_content = "No pierdas la cara la próxima vez.",
  ui_story_5020_50201701_250_dialog_content = "Ah...",
  ui_story_5020_50201701_251_dialog_content = "Ustedes...",
  ui_story_5020_50201701_252_dialog_content = "¡Espero verte pronto!",
  ui_story_5020_50201701_253_dialog_content = "Yao abordó el barco. Rinne se despidió con la mano. Amemori estaba detrás de ella, observando en silencio.",
  ui_story_5020_50201701_254_dialog_content = "Creo que apreciarían cada segundo de esta despedida antes de que el barco se pierda de vista.",
  ui_story_5020_50201701_255_dialog_content = "Hace diez años, la muerte separó a las tres niñas.",
  ui_story_5020_50201701_256_dialog_content = "Hoy, la muerte los vuelve a enviar por caminos diferentes.",
  ui_story_5020_50201701_257_dialog_content = "La nieve de color rosa pálido floreció y cayó en Cloud Island año tras año durante la última década, viendo a las chicas reunirse antes de separarse.",
  ui_story_5020_50201701_258_dialog_content = "También vio a los difuntos reunirse una vez más más allá de la muerte.",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>El fin</color>"
}
return config
